CREATE OR REPLACE FUNCTION "public"."admin_adjust_user_bonus"("target_user_id" "uuid", "bonus_amount" integer, "reason" "text", "expired_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id uuid;
    is_user_admin boolean;
    current_bonus integer;
    new_bonus integer;
BEGIN
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION '인증이 필요합니다.';
    END IF;

    SELECT is_admin() INTO is_user_admin;
    IF NOT is_user_admin THEN
        RAISE EXCEPTION '관리자 권한이 필요합니다.';
    END IF;

    SELECT COALESCE(star_candy_bonus, 0)
    INTO current_bonus
    FROM user_profiles
    WHERE id = target_user_id AND deleted_at IS NULL;

    IF current_bonus IS NULL THEN
        RAISE EXCEPTION '사용자를 찾을 수 없습니다.';
    END IF;

    IF bonus_amount > 0 THEN
        INSERT INTO star_candy_bonus_history (
            user_id, amount, type, remain_amount, transaction_id, expired_dt, created_at, updated_at
        ) VALUES (
            target_user_id,
            bonus_amount,
            'GIFT',
            bonus_amount,
            'admin-adjust:' || current_user_id || ':' || to_char(NOW(), 'YYYY-MM-DD-HH24MISS'),
            NOW() + (expired_days || ' days')::INTERVAL,
            NOW(), NOW()
        );
        new_bonus := current_bonus + bonus_amount;
    ELSIF bonus_amount < 0 THEN
        IF current_bonus < ABS(bonus_amount) THEN
            RAISE EXCEPTION '회수할 보너스가 현재 잔액보다 많습니다. 현재: %, 요청: %', current_bonus, ABS(bonus_amount);
        END IF;

        UPDATE user_profiles
        SET star_candy_bonus = star_candy_bonus + bonus_amount,
            updated_at = NOW()
        WHERE id = target_user_id;
        new_bonus := current_bonus + bonus_amount;
    ELSE
        RAISE EXCEPTION '조정 금액은 0이 될 수 없습니다.';
    END IF;

    INSERT INTO audit_logs (
        "timestamp", user_id, action_type, action_description,
        resource_type, resource_id, old_values, new_values,
        success, severity, tags, created_at
    ) VALUES (
        NOW(),
        current_user_id::text,
        CASE WHEN bonus_amount > 0 THEN 'BONUS_GRANT' ELSE 'BONUS_REVOKE' END,
        reason,
        'user_bonus',
        target_user_id::text,
        jsonb_build_object('bonus', current_bonus)::text,
        jsonb_build_object('bonus', new_bonus, 'change', bonus_amount)::text,
        true,
        'medium',
        'admin,bonus_adjust',
        NOW()
    );

    RETURN jsonb_build_object(
        'success', true,
        'previous_bonus', current_bonus,
        'new_bonus', new_bonus,
        'change_amount', bonus_amount,
        'reason', reason
    );
END;
$$;

COMMENT ON FUNCTION "public"."admin_adjust_user_bonus"("target_user_id" "uuid", "bonus_amount" integer, "reason" "text", "expired_days" integer) IS '보너스 수동 지급/회수 (audit_logs 자동 기록)';

CREATE OR REPLACE FUNCTION "public"."admin_check_bonus_drift"("target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id uuid;
    is_user_admin boolean;
BEGIN
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION '인증이 필요합니다.';
    END IF;

    SELECT is_admin() INTO is_user_admin;
    IF NOT is_user_admin THEN
        RAISE EXCEPTION '관리자 권한이 필요합니다.';
    END IF;

    RETURN (
        SELECT jsonb_build_object(
            'user_id', up.id,
            'nickname', up.nickname,
            'profile_bonus', COALESCE(up.star_candy_bonus, 0),
            'calculated_bonus', COALESCE(calc.total, 0),
            'drift', COALESCE(up.star_candy_bonus, 0) - COALESCE(calc.total, 0),
            'has_drift', COALESCE(up.star_candy_bonus, 0) != COALESCE(calc.total, 0)
        )
        FROM user_profiles up
        LEFT JOIN LATERAL (
            SELECT SUM(h.remain_amount)::int AS total
            FROM star_candy_bonus_history h
            WHERE h.user_id = target_user_id
              AND h.deleted_at IS NULL
              AND h.remain_amount > 0
              AND h.parent_id IS NULL
              AND (h.expired_dt IS NULL OR h.expired_dt > NOW())
        ) calc ON true
        WHERE up.id = target_user_id
    );
END;
$$;

COMMENT ON FUNCTION "public"."admin_check_bonus_drift"("target_user_id" "uuid") IS '보너스 잔액 drift 확인 (프로필 vs 계산값 비교)';

CREATE OR REPLACE FUNCTION "public"."admin_get_user_bonus_history"("target_user_id" "uuid", "limit_count" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id uuid;
    is_user_admin boolean;
    history_data jsonb;
    summary_data jsonb;
BEGIN
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION '인증이 필요합니다.';
    END IF;

    SELECT is_admin() INTO is_user_admin;
    IF NOT is_user_admin THEN
        RAISE EXCEPTION '관리자 권한이 필요합니다.';
    END IF;

    SELECT jsonb_agg(row_to_json(t)::jsonb)
    INTO history_data
    FROM (
        SELECT h.id, h.amount, h.remain_amount, h.type, h.transaction_id,
               h.expired_dt, h.created_at, h.deleted_at,
               h.parent_id, h.vote_pick_id
        FROM star_candy_bonus_history h
        WHERE h.user_id = target_user_id
        ORDER BY h.created_at DESC
        LIMIT limit_count
    ) t;

    SELECT jsonb_build_object(
        'current_balance', COALESCE(up.star_candy_bonus, 0),
        'calculated_balance', COALESCE((
            SELECT SUM(h.remain_amount)
            FROM star_candy_bonus_history h
            WHERE h.user_id = target_user_id
              AND h.deleted_at IS NULL
              AND h.remain_amount > 0
              AND h.parent_id IS NULL
              AND (h.expired_dt IS NULL OR h.expired_dt > NOW())
        ), 0),
        'total_earned', COALESCE((
            SELECT SUM(h.amount) FROM star_candy_bonus_history h
            WHERE h.user_id = target_user_id AND h.deleted_at IS NULL
        ), 0),
        'total_deleted', COALESCE((
            SELECT SUM(h.amount) FROM star_candy_bonus_history h
            WHERE h.user_id = target_user_id AND h.deleted_at IS NOT NULL
        ), 0),
        'has_drift', COALESCE(up.star_candy_bonus, 0) != COALESCE((
            SELECT SUM(h.remain_amount)
            FROM star_candy_bonus_history h
            WHERE h.user_id = target_user_id
              AND h.deleted_at IS NULL
              AND h.remain_amount > 0
              AND h.parent_id IS NULL
              AND (h.expired_dt IS NULL OR h.expired_dt > NOW())
        ), 0)
    )
    INTO summary_data
    FROM user_profiles up
    WHERE up.id = target_user_id;

    RETURN jsonb_build_object(
        'history', COALESCE(history_data, '[]'::jsonb),
        'summary', summary_data
    );
END;
$$;

COMMENT ON FUNCTION "public"."admin_get_user_bonus_history"("target_user_id" "uuid", "limit_count" integer) IS '관리자용 사용자 보너스 히스토리 조회 (요약 + drift 감지 포함)';

CREATE OR REPLACE FUNCTION "public"."auto_fix_bonus_drift"() RETURNS TABLE("user_id" "uuid", "old_bonus" numeric, "new_bonus" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    rec RECORD;
    v_result NUMERIC;
    v_count INT := 0;
BEGIN
    FOR rec IN
        SELECT d.user_id, d.profile_bonus, d.history_bonus, d.delta
        FROM vw_star_candy_bonus_drift d
        WHERE ABS(d.delta) > 0
        LIMIT 200
    LOOP
        v_result := recompute_user_bonus(rec.user_id);
        v_count := v_count + 1;

        user_id := rec.user_id;
        old_bonus := rec.profile_bonus;
        new_bonus := v_result;
        RETURN NEXT;
    END LOOP;

    IF v_count > 0 THEN
        INSERT INTO custom_logs (operation, details, log_time)
        VALUES ('auto_fix_bonus_drift',
                jsonb_build_object('fixed_count', v_count)::text,
                NOW());
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."auto_resolve_stale_qna_threads"("inactivity_days" integer DEFAULT 14) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  cfg_days INTEGER;
  rec RECORD;
BEGIN
  SELECT COALESCE(NULLIF(TRIM(value), '')::integer, inactivity_days)
  INTO cfg_days
  FROM config
  WHERE key = 'qna_auto_resolve_days'
  LIMIT 1;

  IF cfg_days IS NULL THEN
    cfg_days := 14;
  END IF;

  FOR rec IN (
    WITH latest_msg AS (
      SELECT DISTINCT ON (m.thread_id)
        m.thread_id,
        m.created_at AS last_msg_at,
        m.is_admin_message
      FROM qna_messages m
      ORDER BY m.thread_id, m.created_at DESC
    )
    SELECT t.id AS thread_id, lm.last_msg_at
    FROM qna_threads t
    JOIN latest_msg lm ON lm.thread_id = t.id
    WHERE t.status = 'IN_PROGRESS'
      AND lm.is_admin_message = true
      AND lm.last_msg_at < NOW() - (cfg_days || ' days')::interval
  ) LOOP
    UPDATE qna_threads
    SET status = 'RESOLVED'
    WHERE id = rec.thread_id AND status = 'IN_PROGRESS';

    INSERT INTO audit_logs (
      id, timestamp, user_id, user_email, action_type, action_description,
      resource_type, resource_id, id_old, success, severity, classification, metadata
    ) VALUES (
      gen_random_uuid(),
      NOW(),
      'system',
      NULL,
      'auto_resolve_qna',
      'Auto-resolved QnA due to inactivity',
      'qna_thread',
      rec.thread_id::text,
      rec.thread_id::text,
      true,
      'low',
      'internal',
      '{"inactivity_days": ' || cfg_days || '}'
    );
  END LOOP;
END;
$$;

