CREATE OR REPLACE FUNCTION "public"."batch_revoke_abuser_bonus"("p_user_ids" "uuid"[], "p_reason" "text", "p_admin_id" "uuid" DEFAULT NULL::"uuid", "p_dry_run" boolean DEFAULT true) RETURNS TABLE("user_id" "uuid", "affected_records" bigint, "total_revoked" bigint, "user_nickname" "text", "user_was_banned" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_uid UUID;
  v_result RECORD;
BEGIN
  IF array_length(p_user_ids, 1) > 100 THEN
    RAISE EXCEPTION '한 번에 최대 100명까지 처리할 수 있습니다. 현재: %', array_length(p_user_ids, 1);
  END IF;

  FOREACH v_uid IN ARRAY p_user_ids
  LOOP
    SELECT * INTO v_result
    FROM public.revoke_abuser_bonus(v_uid, p_reason, p_admin_id, p_dry_run);

    user_id := v_uid;
    affected_records := v_result.affected_records;
    total_revoked := v_result.total_revoked;
    user_nickname := v_result.user_nickname;
    user_was_banned := v_result.user_was_banned;
    RETURN NEXT;
  END LOOP;
END;
$$;

