CREATE OR REPLACE FUNCTION "public"."can_vote"("p_user_id" "uuid", "p_vote_amount" integer) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_star_candy INT := 0;
    v_star_candy_bonus INT := 0;
    v_total_available INT := 0;
BEGIN
    IF p_vote_amount <= 0 THEN
        RAISE EXCEPTION
            USING
                MESSAGE = format('Invalid vote amount: %s (must be > 0)', p_vote_amount),
                HINT = 'Check vote amount input from client.';
    END IF;

    SELECT star_candy, star_candy_bonus
    INTO STRICT v_star_candy, v_star_candy_bonus
    FROM user_profiles
    WHERE id = p_user_id;

    v_total_available := v_star_candy + v_star_candy_bonus;

    IF v_total_available < p_vote_amount THEN
        RAISE EXCEPTION
            USING
                MESSAGE = format(
                        'Insufficient balance: requested = %s, available = %s (star_candy = %s, bonus = %s)',
                        p_vote_amount, v_total_available, v_star_candy, v_star_candy_bonus
                          ),
                HINT = 'Check star_candy and bonus values in user_profiles.';
    END IF;

    RETURN TRUE;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE EXCEPTION
            USING
                MESSAGE = format('User not found in user_profiles: %s', p_user_id),
                HINT = 'Verify that the user is registered and has a profile entry.';

    WHEN OTHERS THEN
        RAISE EXCEPTION
            USING
                MESSAGE = format('Unexpected error in can_vote(): %s', SQLERRM),
                HINT = 'Check logs for full stack trace and debug context.';
END;
$$;

CREATE OR REPLACE FUNCTION "public"."check_bonus_state"("check_time" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("total_bonuses" bigint, "active_bonuses" bigint, "expirable_bonuses" bigint, "earliest_expiry" timestamp with time zone, "latest_expiry" timestamp with time zone)
    LANGUAGE "sql"
    AS $$
SELECT
    COUNT(*) as total_bonuses,
    COUNT(*) FILTER (WHERE remain_amount > 0) as active_bonuses,
    COUNT(*) FILTER (WHERE expired_dt <= check_time AND remain_amount > 0) as expirable_bonuses,
    MIN(expired_dt) FILTER (WHERE remain_amount > 0) as earliest_expiry,
    MAX(expired_dt) FILTER (WHERE remain_amount > 0) as latest_expiry
FROM star_candy_bonus_history;
$$;

CREATE OR REPLACE FUNCTION "public"."cleanup_deleted_qnas"("days_old" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM qnas
  WHERE
    deleted_at IS NOT NULL
    AND deleted_at < NOW() - INTERVAL '1 day' * days_old;

  GET DIAGNOSTICS deleted_count = ROW_COUNT;

  RETURN deleted_count;
END;
$$;

COMMENT ON FUNCTION "public"."cleanup_deleted_qnas"("days_old" integer) IS 'Permanently delete QnA items deleted more than X days ago';

CREATE OR REPLACE FUNCTION "public"."cleanup_exhausted_buckets_batch"("batch_limit" integer DEFAULT 50000) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rows_affected INT;
BEGIN
  UPDATE star_candy_bonus_history
  SET deleted_at = NOW()
  WHERE id IN (
    SELECT id
    FROM star_candy_bonus_history
    WHERE remain_amount = 0
      AND deleted_at IS NULL
      AND parent_id IS NULL
    LIMIT batch_limit
  );

  GET DIAGNOSTICS rows_affected = ROW_COUNT;
  RETURN rows_affected;
END;
$$;

COMMENT ON FUNCTION "public"."cleanup_exhausted_buckets_batch"("batch_limit" integer) IS '소진된 보너스 버킷 배치 정리 (soft-delete)';

CREATE OR REPLACE FUNCTION "public"."cleanup_expired_audit_logs"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM audit_logs
  WHERE created_at < NOW() - INTERVAL '1 day' * retention_period
  AND retention_period IS NOT NULL;

  GET DIAGNOSTICS deleted_count = ROW_COUNT;

  INSERT INTO audit_logs (
    id,
    timestamp,
    user_id,
    action_type,
    action_description,
    resource_type,
    resource_id,
    id_old,
    success,
    severity,
    classification,
    metadata
  ) VALUES (
    'cleanup-' || extract(epoch from now()) || '-' || floor(random() * 1000),
    NOW(),
    'system',
    'system_maintenance',
    'Cleaned up ' || deleted_count || ' expired audit logs',
    'system',
    'system',
    'system',
    true,
    'low',
    'internal',
    '{"deleted_count": ' || deleted_count || '}'
  );

  RETURN deleted_count;
END;
$$;

