    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."consolidate_bonus_buckets"("p_user_id" "uuid") RETURNS TABLE("consolidated_count" bigint, "new_bucket_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_group RECORD;
  v_total_consolidated BIGINT := 0;
  v_total_new BIGINT := 0;
BEGIN
  SET LOCAL app.skip_sync_bonus = 'true';

  FOR v_group IN
    SELECT
      COALESCE(h.expired_dt::text, '__null__') AS expiry_key,
      h.expired_dt,
      COUNT(*) AS cnt,
      SUM(h.remain_amount)::int AS total
    FROM star_candy_bonus_history h
    WHERE h.user_id = p_user_id
      AND h.parent_id IS NULL
      AND h.deleted_at IS NULL
      AND h.remain_amount > 0
      AND h.remain_amount = h.amount
    GROUP BY h.expired_dt
    HAVING COUNT(*) > 1
  LOOP
    INSERT INTO star_candy_bonus_history
      (type, amount, remain_amount, user_id, expired_dt, transaction_id)
    VALUES
      ('AD', v_group.total, v_group.total, p_user_id, v_group.expired_dt,
       'consolidated:' || p_user_id || ':' || to_char(NOW() AT TIME ZONE 'Asia/Seoul', 'YYYY-MM-DD'));

    WITH to_delete AS (
      SELECT id
      FROM star_candy_bonus_history
      WHERE user_id = p_user_id
        AND parent_id IS NULL
        AND deleted_at IS NULL
        AND remain_amount > 0
        AND remain_amount = amount
        AND type = 'AD'
        AND (
          (expired_dt IS NULL AND v_group.expired_dt IS NULL)
          OR expired_dt = v_group.expired_dt
        )
        AND amount < v_group.total
    )
    UPDATE star_candy_bonus_history
    SET deleted_at = NOW(), remain_amount = 0, updated_at = NOW()
    WHERE id IN (SELECT id FROM to_delete);

    v_total_consolidated := v_total_consolidated + v_group.cnt;
    v_total_new := v_total_new + 1;
  END LOOP;

  IF v_total_consolidated > 0 THEN
    PERFORM public.recompute_user_bonus(p_user_id);
  END IF;

  consolidated_count := v_total_consolidated;
  new_bucket_count := v_total_new;
  RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."consolidate_bonus_buckets_batch"("p_min_buckets" integer DEFAULT 10, "p_limit" integer DEFAULT 50) RETURNS TABLE("user_id" "uuid", "consolidated_count" bigint, "new_bucket_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_user RECORD;
  v_result RECORD;
BEGIN
  FOR v_user IN
    SELECT h.user_id, COUNT(*) AS bucket_count
    FROM star_candy_bonus_history h
    WHERE h.parent_id IS NULL
      AND h.deleted_at IS NULL
      AND h.remain_amount > 0
      AND h.remain_amount = h.amount
    GROUP BY h.user_id
    HAVING COUNT(*) > p_min_buckets
    ORDER BY COUNT(*) DESC
    LIMIT p_limit
  LOOP
    SELECT * INTO v_result
    FROM public.consolidate_bonus_buckets(v_user.user_id);

    user_id := v_user.user_id;
    consolidated_count := v_result.consolidated_count;
    new_bucket_count := v_result.new_bucket_count;
    RETURN NEXT;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."create_boards_for_existing_artists"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$DECLARE
    artist_record RECORD;
BEGIN
    FOR artist_record IN SELECT * FROM artist LOOP
            INSERT INTO boards (name, description, artist_id, is_official)
            VALUES (
                       artist_record.name,
                       json_build_object('artist_info', json_build_object(
                               'name', artist_record.name,
                               'gender', artist_record.gender,
                               'birthdate', json_build_object('year', artist_record.yy, 'month', artist_record.mm, 'day', artist_record.dd)
                                                        )),
                       artist_record.id,
                       true
                   )
            ON CONFLICT (artist_id) DO UPDATE
                SET name = EXCLUDED.name,
                    description = EXCLUDED.description;
        END LOOP;
END;$$;

CREATE OR REPLACE FUNCTION "public"."create_boards_for_existing_artists_meme"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    artist_record RECORD;
BEGIN
    FOR artist_record IN SELECT * FROM artist LOOP
            INSERT INTO community.boards (name, artist_id, is_official)
            VALUES (
                       '{"ko":"밈", "en":"Meme", "ja":"Meme", "zh":"Meme"}'::json,
                           artist_record.id,
                       true
                   );
        END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."create_monthly_votes"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    current_month_start   date := date_trunc('month', now())::date;
    next_month_start      date := current_month_start + interval '1 month';
    next_next_month_start date := current_month_start + interval '2 month';

    current_first_saturday  timestamptz;
    current_second_saturday timestamptz;
    current_third_saturday  timestamptz;
    current_fourth_saturday timestamptz;

    next_first_saturday   timestamptz;
    next_second_saturday  timestamptz;
    next_third_saturday   timestamptz;
    next_fourth_saturday  timestamptz;

    next_month_1st_saturday timestamptz;
    next_month_2nd_saturday timestamptz;

    debut_visible_at timestamptz;
    debut_start_at   timestamptz;
    debut_stop_at    timestamptz;

    birth_visible_at timestamptz;
    birth_start_at   timestamptz;
    birth_stop_at    timestamptz;

    musical_birth_visible_at timestamptz;
    musical_birth_start_at   timestamptz;
    musical_birth_stop_at    timestamptz;

    inserted_debut_vote_id INT;
    inserted_birth_male_vote_id INT;
    inserted_birth_female_vote_id INT;
    inserted_musical_vote_id INT;

    result_msg TEXT := '--- create_monthly_votes() result ---' || E'\n';
BEGIN
    WITH base AS (SELECT current_month_start AS d),
         first_sat AS (
             SELECT (
                        d + ((6 - EXTRACT(isodow FROM d)::int + 7) % 7) * interval '1 day'
                            + interval '9 hours'
                        )::timestamptz AS sat FROM base
         )
    SELECT sat, sat + interval '7 days', sat + interval '14 days', sat + interval '21 days'
    INTO current_first_saturday, current_second_saturday, current_third_saturday, current_fourth_saturday
    FROM first_sat;

    WITH base AS (SELECT next_month_start AS d),
         first_sat AS (
             SELECT (
                        d + ((6 - EXTRACT(isodow FROM d)::int + 7) % 7) * interval '1 day'
                            + interval '9 hours'
                        )::timestamptz AS sat FROM base
         )
    SELECT sat, sat + interval '7 days', sat + interval '14 days', sat + interval '21 days'
    INTO next_first_saturday, next_second_saturday, next_third_saturday, next_fourth_saturday
    FROM first_sat;

    WITH base AS (SELECT next_month_start AS d),
         first_sat AS (
             SELECT (
                        d + ((6 - EXTRACT(isodow FROM d)::int + 7) % 7) * interval '1 day'
                            + interval '9 hours'
                        )::timestamptz AS sat FROM base
         )
    SELECT sat, sat + interval '7 days'
    INTO next_month_1st_saturday, next_month_2nd_saturday
    FROM first_sat;

    debut_visible_at := current_first_saturday;
    debut_start_at   := current_second_saturday;
    debut_stop_at    := current_fourth_saturday;

    birth_visible_at := current_third_saturday;
    birth_start_at   := current_fourth_saturday;
    birth_stop_at    := next_month_2nd_saturday;

    musical_birth_visible_at := current_second_saturday;
    musical_birth_start_at   := current_third_saturday;
    musical_birth_stop_at    := next_month_1st_saturday;

    IF NOT EXISTS (
        SELECT 1
        FROM vote
        WHERE area = 'kpop'
          AND vote_category = 'debut'
          AND (title->>'ko') = to_char(next_month_start, 'MM') || '월 데뷔 투표'
          AND (title->>'en') = to_char(next_month_start, 'FMMonth') || ' Debut Vote'
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'kpop', 'debut', NULL,
                   debut_visible_at, debut_start_at, debut_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_month_start, 'MM') || '월 데뷔 투표',
                           'en', to_char(next_month_start, 'FMMonth') || ' Debut Vote'
                   )
               ) RETURNING id INTO inserted_debut_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_debut_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_kpop = TRUE
          AND a.debut_mm = EXTRACT(MONTH FROM next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[KPOP] Debut vote created for ' || to_char(next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[KPOP] Debut vote already exists for ' || to_char(next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vote
        WHERE area = 'kpop' AND vote_category = 'birthday' AND vote_sub_category = 'male'
          AND date_trunc('month', start_at) = next_next_month_start
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'kpop', 'birthday', 'male',
                   birth_visible_at, birth_start_at, birth_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_next_month_start, 'MM') || '월 생일 투표(남자)',
                           'en', to_char(next_next_month_start, 'FMMonth') || ' Birthday Poll (Male)'
                   )
               ) RETURNING id INTO inserted_birth_male_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_birth_male_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_kpop = TRUE AND a.gender = 'MALE'
          AND EXTRACT(MONTH FROM a.birth_date) = EXTRACT(MONTH FROM next_next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[KPOP] Birthday(MALE) created for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[KPOP] Birthday(MALE) already exists for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vote
        WHERE area = 'kpop' AND vote_category = 'birthday' AND vote_sub_category = 'female'
          AND date_trunc('month', start_at) = next_next_month_start
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'kpop', 'birthday', 'female',
                   birth_visible_at, birth_start_at, birth_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_next_month_start, 'MM') || '월 생일 투표(여자)',
                           'en', to_char(next_next_month_start, 'FMMonth') || ' Birthday Poll (Female)'
                   )
               ) RETURNING id INTO inserted_birth_female_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_birth_female_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_kpop = TRUE AND a.gender = 'FEMALE'
          AND EXTRACT(MONTH FROM a.birth_date) = EXTRACT(MONTH FROM next_next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[KPOP] Birthday(FEMALE) created for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[KPOP] Birthday(FEMALE) already exists for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vote
        WHERE area = 'musical' AND vote_category = 'birthday' AND vote_sub_category IS NULL
          AND date_trunc('month', start_at) = next_next_month_start
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'musical', 'birthday', NULL,
                   musical_birth_visible_at, musical_birth_start_at, musical_birth_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_next_month_start, 'MM') || '월 뮤지컬 생일 투표',
                           'en', to_char(next_next_month_start, 'FMMonth') || ' Musical Birthday Poll'
                   )
               ) RETURNING id INTO inserted_musical_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_musical_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_musical = TRUE
          AND EXTRACT(MONTH FROM a.birth_date) = EXTRACT(MONTH FROM next_next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[Musical] Birthday created for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[Musical] Birthday already exists for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    RAISE NOTICE '%', result_msg;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error in create_monthly_votes(): %', SQLERRM;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."create_or_update_artist_board"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    updated_name jsonb;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.deleted_at IS NOT NULL AND (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at) THEN
        UPDATE boards
        SET deleted_at = NEW.deleted_at
        WHERE artist_id = NEW.id AND deleted_at IS DISTINCT FROM NEW.deleted_at;
        RETURN NEW;
    END IF;

    updated_name := jsonb_build_object(
                        'ko', CASE WHEN NEW.name->>'ko' IS NOT NULL THEN 'Picnic! ' || (NEW.name->>'ko') ELSE NEW.name->>'ko' END,
                        'en', CASE WHEN NEW.name->>'en' IS NOT NULL THEN 'Picnic! ' || (NEW.name->>'en') ELSE NEW.name->>'en' END,
                        'ja', CASE WHEN NEW.name->>'ja' IS NOT NULL THEN 'Picnic! ' || (NEW.name->>'ja') ELSE NEW.name->>'ja' END,
                        'zh', CASE WHEN NEW.name->>'zh' IS NOT NULL THEN 'Picnic! ' || (NEW.name->>'zh') ELSE NEW.name->>'zh' END
                ) || (NEW.name::jsonb - 'ko' - 'en' - 'ja' - 'zh');

    IF NOT EXISTS (SELECT 1 FROM boards WHERE artist_id = NEW.id AND is_official = true AND "order" = 1) THEN
        INSERT INTO boards (name, artist_id, is_official, status, "order")
        VALUES (
                   updated_name,
                   NEW.id,
                   true,
                   'approved',
                   1
               );
    ELSE
        UPDATE boards
        SET name = updated_name,
            status = 'approved'
        WHERE artist_id = NEW.id AND is_official = true AND "order" = 1;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM boards WHERE artist_id = NEW.id AND is_official = true AND "order" = 2) THEN
        INSERT INTO boards (name, artist_id, is_official, status, "order")
        VALUES (
                   '{"ko":"Picnic! 밈", "en":"Picnic! Meme", "ja":"Picnic! ミーム", "zh":"Picnic! 备忘录"}'::json,
                   NEW.id,
                   true,
                   'approved',
                   2
               );
    ELSE
        UPDATE boards
        SET status = 'approved'
        WHERE artist_id = NEW.id AND is_official = true AND "order" = 2;
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."create_vote_item_request_with_user"("vote_id_param" integer, "artist_id_param" integer, "user_id_param" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    new_request_id UUID;
    result_data JSONB;
BEGIN
    IF EXISTS (
        SELECT 1 FROM "public"."vote_item_request_users" viru
        WHERE viru.vote_id = vote_id_param
          AND viru.user_id = user_id_param
          AND viru.artist_id = artist_id_param
    ) THEN
        RAISE EXCEPTION '이미 해당 아티스트에 대해 신청하셨습니다.';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM "public"."artist" WHERE id = artist_id_param
    ) THEN
        RAISE EXCEPTION '존재하지 않는 아티스트입니다.';
    END IF;

    new_request_id := uuid_generate_v4();

    INSERT INTO "public"."vote_item_request_users" (
        id,
        vote_item_request_id,
        vote_id,
        user_id,
        artist_id,
        status
    )
    VALUES (
               new_request_id,
               new_request_id,  -- vote_item_request_id는 자신의 id와 동일
               vote_id_param,
               user_id_param,
               artist_id_param,
               'pending'
           );

    SELECT jsonb_build_object(
               'vote_item_request', jsonb_build_object(
            'id', new_request_id,
            'vote_id', vote_id_param,
            'status', 'pending',
            'created_at', NOW(),
            'updated_at', NOW()
                                    ),
               'user_request', to_jsonb(viru.*),
               'artist', to_jsonb(a.*)
           ) INTO result_data
    FROM "public"."vote_item_request_users" viru
             JOIN "public"."artist" a ON viru.artist_id = a.id
    WHERE viru.vote_item_request_id = new_request_id AND viru.user_id = user_id_param;

    RETURN result_data;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."create_weekly_votes"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    _msg text := '--- create_weekly_votes() ---' || E'\n';
BEGIN
    WITH now_kst(ts) AS (
        SELECT now() AT TIME ZONE 'Asia/Seoul'
    ),
         next_mon(d) AS (
             SELECT ((ts::date) + ((8 - EXTRACT(isodow FROM ts)::int) % 7))::date
             FROM now_kst
         ),
         schedule AS (
             SELECT
                 make_timestamptz(
                         EXTRACT(year FROM (d - 1))::int,
                         EXTRACT(month FROM (d - 1))::int,
                         EXTRACT(day FROM (d - 1))::int,
                         23, 30, 0,
                         'Asia/Seoul'
                 ) AS visible_at,
                 make_timestamptz(
                         EXTRACT(year FROM d)::int,
                         EXTRACT(month FROM d)::int,
                         EXTRACT(day FROM d)::int,
                         10, 0, 0,
                         'Asia/Seoul'
                 ) AS start_at,
                 make_timestamptz(
                         EXTRACT(year FROM (d + 6))::int,
                         EXTRACT(month FROM (d + 6))::int,
                         EXTRACT(day FROM (d + 6))::int,
                         23, 0, 0,
                         'Asia/Seoul'
                 ) AS stop_at
             FROM next_mon
             WHERE (make_date(EXTRACT(year FROM d)::int, 12, 31) - d) > 14
         )
    INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
    SELECT
        'kpop'  AS area,
        'weekly' AS vote_category,
        NULL    AS vote_sub_category,
        s.visible_at,
        s.start_at,
        s.stop_at,
        jsonb_build_object(
                'ko',
                to_char(s.start_at AT TIME ZONE 'Asia/Seoul', 'YYYY') || ' ' ||
                to_char(s.start_at AT TIME ZONE 'Asia/Seoul', 'IW') || '주차 위클리 핔차트',
                'en',
                to_char(s.start_at AT TIME ZONE 'Asia/Seoul', 'YYYY') || ' Week ' ||
                to_char(s.start_at AT TIME ZONE 'Asia/Seoul', 'IW') || ' Weekly PIC Chart'
        ) AS title
    FROM schedule s
    WHERE NOT EXISTS (
        SELECT 1
        FROM vote v
        WHERE v.area = 'kpop'
          AND v.vote_category = 'weekly'
          AND v.start_at = s.start_at
          AND v.deleted_at IS NULL
    );

    WITH now_kst(ts) AS (
        SELECT now() AT TIME ZONE 'Asia/Seoul'
    ),
         next_mon(d) AS (
             SELECT ((ts::date) + ((8 - EXTRACT(isodow FROM ts)::int) % 7))::date
             FROM now_kst
         ),
         schedule AS (
             SELECT
                 make_timestamptz(
                         EXTRACT(year FROM d)::int,
                         EXTRACT(month FROM d)::int,
                         EXTRACT(day FROM d)::int,
                         10, 0, 0,
                         'Asia/Seoul'
                 ) AS start_at
             FROM next_mon
             WHERE (make_date(EXTRACT(year FROM d)::int, 12, 31) - d) > 14
         ),
         v_target AS (
             SELECT v.id, v.start_at
             FROM schedule s
                      JOIN vote v
                           ON v.area = 'kpop'
                               AND v.vote_category = 'weekly'
                               AND v.start_at = s.start_at
                               AND v.deleted_at IS NULL
         ),
         winners AS (
             SELECT
                 vi.artist_id,
                 EXTRACT(year FROM (v.start_at AT TIME ZONE 'Asia/Seoul'))::int AS y
             FROM vote_item vi
                      JOIN vote v ON v.id = vi.vote_id
             WHERE v.area = 'kpop'
               AND v.vote_category = 'weekly'
               AND v.deleted_at IS NULL
               AND vi.deleted_at IS NULL
               AND vi.vote_total IS NOT NULL
               AND vi.vote_total = (
                 SELECT MAX(vi2.vote_total)
                 FROM vote_item vi2
                 WHERE vi2.vote_id = vi.vote_id
                   AND vi2.deleted_at IS NULL
             )
             GROUP BY vi.artist_id, y
         ),
         artists AS (
             SELECT
                 a.id AS artist_id,
                 vt.id AS vote_id,
                 EXTRACT(year FROM (vt.start_at AT TIME ZONE 'Asia/Seoul'))::int AS y
             FROM v_target vt
                      CROSS JOIN artist a
             WHERE a.deleted_at IS NULL
               AND a.is_kpop = TRUE
               AND a.id <> 0
               AND NOT EXISTS (
                 SELECT 1
                 FROM winners w
                 WHERE w.artist_id = a.id
                   AND w.y = EXTRACT(year FROM (vt.start_at AT TIME ZONE 'Asia/Seoul'))::int
             )
         )
    INSERT INTO vote_item (vote_id, artist_id, group_id)
    SELECT ar.vote_id, ar.artist_id, 0
    FROM artists ar
    WHERE NOT EXISTS (
        SELECT 1
        FROM vote_item vi
        WHERE vi.vote_id = ar.vote_id
          AND vi.artist_id = ar.artist_id
          AND vi.deleted_at IS NULL
    );

    WITH now_kst(ts) AS (
        SELECT now() AT TIME ZONE 'Asia/Seoul'
    ),
         next_mon(d) AS (
             SELECT ((ts::date) + ((8 - EXTRACT(isodow FROM ts)::int) % 7))::date
             FROM now_kst
         ),
         schedule AS (
             SELECT
                 make_timestamptz(
                         EXTRACT(year FROM d)::int,
                         EXTRACT(month FROM d)::int,
                         EXTRACT(day FROM d)::int,
                         10, 0, 0,
                         'Asia/Seoul'
                 ) AS start_at
             FROM next_mon
             WHERE (make_date(EXTRACT(year FROM d)::int, 12, 31) - d) > 14
         )
    INSERT INTO vote_reward (vote_id, reward_id)
    SELECT v.id, 8
    FROM schedule s
             JOIN vote v
                  ON v.area = 'kpop'
                      AND v.vote_category = 'weekly'
                      AND v.start_at = s.start_at
                      AND v.deleted_at IS NULL
    WHERE NOT EXISTS (
        SELECT 1
        FROM vote_reward vr
        WHERE vr.vote_id = v.id
          AND vr.reward_id = 8
    );

    RAISE NOTICE '%', _msg;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error in create_weekly_votes(): %', SQLERRM;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."deduct_star_candy"("p_user_id" "uuid", "p_amount" integer, "p_vote_pick_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    INSERT INTO star_candy_history (type, user_id, amount, vote_pick_id)
    VALUES ('VOTE', p_user_id, p_amount, p_vote_pick_id);

    UPDATE user_profiles
    SET star_candy = GREATEST(star_candy - p_amount, 0)
    WHERE id = p_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."deduct_star_candy_bonus"("p_user_id" "uuid", "p_amount" integer, "p_bonus_id" integer, "p_vote_pick_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE star_candy_bonus_history
    SET remain_amount = GREATEST(remain_amount - p_amount, 0),
        updated_at = NOW()
    WHERE id = p_bonus_id;

    INSERT INTO star_candy_bonus_history (user_id, amount, remain_amount, parent_id, vote_pick_id)
    VALUES (p_user_id, p_amount, p_amount, p_bonus_id, p_vote_pick_id);

    UPDATE user_profiles
    SET star_candy_bonus = GREATEST(star_candy_bonus - p_amount, 0)
    WHERE id = p_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."detect_abuser_candidates"("p_daily_threshold" integer DEFAULT 200, "p_min_days" integer DEFAULT 3, "p_lookback_days" integer DEFAULT 30) RETURNS TABLE("user_id" "uuid", "nickname" "text", "email" "text", "is_banned" boolean, "daily_avg" numeric, "max_daily" bigint, "suspicious_days" bigint, "total_bonus" bigint, "active_bonus" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH daily_counts AS (
    SELECT
      h.user_id,
      DATE(h.created_at AT TIME ZONE 'Asia/Seoul') AS day,
      COUNT(*) AS daily_count,
      SUM(h.amount) AS daily_amount
    FROM star_candy_bonus_history h
    WHERE h.type = 'AD'
      AND h.parent_id IS NULL
      AND h.created_at >= NOW() - (p_lookback_days || ' days')::INTERVAL
    GROUP BY h.user_id, DATE(h.created_at AT TIME ZONE 'Asia/Seoul')
    HAVING COUNT(*) >= p_daily_threshold
  ),
  suspicious_users AS (
    SELECT
      dc.user_id,
      ROUND(AVG(dc.daily_count), 1) AS daily_avg,
      MAX(dc.daily_count) AS max_daily,
      COUNT(*) AS suspicious_days,
      SUM(dc.daily_amount) AS total_bonus
    FROM daily_counts dc
    GROUP BY dc.user_id
    HAVING COUNT(*) >= p_min_days
  )
  SELECT
    su.user_id,
    up.nickname,
    up.email,
    (up.deleted_at IS NOT NULL) AS is_banned,
    su.daily_avg,
    su.max_daily,
    su.suspicious_days,
    su.total_bonus,
    COALESCE(up.star_candy_bonus, 0) AS active_bonus
  FROM suspicious_users su
  JOIN user_profiles up ON up.id = su.user_id
  ORDER BY su.total_bonus DESC;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."enqueue_bonus_recalc"("p_user_id" "uuid", "p_source" "text" DEFAULT 'trigger'::"text", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF p_user_id IS NULL THEN
        RETURN;
    END IF;

    INSERT INTO public.user_bonus_update_queue (user_id, last_source, last_error, next_run_at, last_enqueued_at)
    VALUES (p_user_id, p_source, p_error, NOW(), NOW())
    ON CONFLICT (user_id) DO UPDATE
        SET
            last_source     = EXCLUDED.last_source,
            last_error      = COALESCE(p_error, public.user_bonus_update_queue.last_error),
            attempts        = 0,
            next_run_at     = NOW(),
            last_enqueued_at = NOW(),
            updated_at      = NOW();
END;
$$;

CREATE OR REPLACE FUNCTION "public"."enqueue_user_bonus_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  uid uuid := coalesce(NEW.user_id, OLD.user_id);
BEGIN
  INSERT INTO public.user_bonus_update_queue(user_id)
  VALUES (uid)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."expire_star_candy_bonus"("cutoff_time" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("updated_count" bigint, "updated_amount" bigint, "affected_users" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_batch_id           integer;
  v_start_time         timestamptz;
  v_end_time           timestamptz;
  v_effective_cutoff   timestamptz;
  v_batch_rows         integer;
  v_batch_amount       bigint;
  v_batch_users        bigint;
  v_chunk_count        integer := 500;            -- 더 작은 배치 크기
  v_prev_timeout       text;
  v_prev_locktimeout   text;
BEGIN
  PERFORM set_config('TimeZone', 'Asia/Seoul', true);

  v_prev_timeout := current_setting('statement_timeout', true);
  v_prev_locktimeout := current_setting('lock_timeout', true);
  PERFORM set_config('statement_timeout', '0', false); -- 세션 범위
  PERFORM set_config('lock_timeout', '0', false);
  PERFORM set_config('statement_timeout', '0', true);  -- 트랜잭션 범위도 확실히
  PERFORM set_config('lock_timeout', '0', true);

  PERFORM set_config('app.skip_sync_bonus', '1', true);

  v_start_time := now();
  v_effective_cutoff := COALESCE(cutoff_time, now());

  INSERT INTO batch_log (batch_name, start_time, status, details)
  VALUES ('expire_star_candy_bonus', v_start_time, 'STARTED', jsonb_build_object('expiry_time', v_effective_cutoff))
  RETURNING id INTO v_batch_id;

  updated_count  := 0;
  updated_amount := 0;
  affected_users := 0;

  CREATE TEMP TABLE IF NOT EXISTS tmp_affected_users(user_id uuid PRIMARY KEY) ON COMMIT DROP;
  TRUNCATE tmp_affected_users;
  CREATE TEMP TABLE IF NOT EXISTS tmp_upd_rows(user_id uuid, remain_amount int) ON COMMIT DROP;
  TRUNCATE tmp_upd_rows;

  LOOP
    TRUNCATE tmp_upd_rows;

    WITH cte AS (
      SELECT id, user_id, remain_amount
      FROM public.star_candy_bonus_history
      WHERE expired_dt <= v_effective_cutoff
        AND remain_amount > 0
        AND deleted_at IS NULL
      ORDER BY expired_dt
      LIMIT v_chunk_count
      FOR UPDATE SKIP LOCKED
    ), upd AS (
      UPDATE public.star_candy_bonus_history h
      SET remain_amount = 0
      FROM cte
      WHERE h.id = cte.id
      RETURNING h.user_id, cte.remain_amount
    )
    INSERT INTO tmp_upd_rows(user_id, remain_amount)
    SELECT user_id, remain_amount FROM upd;

    SELECT COALESCE(COUNT(*), 0)::integer,
           COALESCE(SUM(remain_amount), 0)::bigint,
           COALESCE(COUNT(DISTINCT user_id), 0)::bigint
      INTO v_batch_rows, v_batch_amount, v_batch_users
      FROM tmp_upd_rows;

    EXIT WHEN v_batch_rows = 0; -- 처리 완료

    updated_count  := updated_count  + v_batch_rows;
    updated_amount := updated_amount + v_batch_amount;
    affected_users := affected_users + v_batch_users;

    INSERT INTO tmp_affected_users(user_id)
    SELECT DISTINCT user_id FROM tmp_upd_rows
    ON CONFLICT (user_id) DO NOTHING;
  END LOOP;

  WITH agg AS (
    SELECT u.user_id,
           COALESCE(SUM(h.remain_amount), 0) AS total_remain
    FROM tmp_affected_users u
    LEFT JOIN public.star_candy_bonus_history h
      ON h.user_id = u.user_id
     AND h.remain_amount > 0
     AND h.expired_dt > now()
     AND h.deleted_at IS NULL
    GROUP BY u.user_id
  )
  UPDATE public.user_profiles up
  SET star_candy_bonus = agg.total_remain,
      updated_at       = now()
  FROM agg
  WHERE up.id = agg.user_id;

  v_end_time := now();

  UPDATE batch_log
     SET end_time = v_end_time,
         status   = 'COMPLETED',
         details  = details || jsonb_build_object(
           'updated_count',  updated_count,
           'updated_amount', updated_amount,
           'affected_users', affected_users,
           'duration_sec',   extract(epoch from (v_end_time - v_start_time)),
           'chunk_size',     v_chunk_count
         )
   WHERE id = v_batch_id;

  PERFORM set_config('app.skip_sync_bonus', '0', true);
  PERFORM set_config('statement_timeout', v_prev_timeout, false);
  PERFORM set_config('lock_timeout', v_prev_locktimeout, false);

  RETURN QUERY SELECT updated_count, updated_amount, affected_users;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."expire_star_candy_bonus_batch"("cutoff_time" timestamp with time zone, "chunk_size" integer DEFAULT 500) RETURNS TABLE("batch_count" integer, "batch_amount" bigint, "batch_users" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_prev_timeout text;
BEGIN
  PERFORM set_config('TimeZone','Asia/Seoul',true);
  PERFORM set_config('app.skip_sync_bonus','1',true);

  v_prev_timeout := current_setting('statement_timeout', true);
  PERFORM set_config('statement_timeout','0', true);

  CREATE TEMP TABLE IF NOT EXISTS tmp_upd_rows(user_id uuid, remain_amount int) ON COMMIT DROP;
  TRUNCATE tmp_upd_rows;

  WITH cte AS (
    SELECT id, user_id, remain_amount
    FROM public.star_candy_bonus_history
    WHERE expired_dt <= cutoff_time
      AND remain_amount > 0
      AND deleted_at IS NULL
    ORDER BY expired_dt
    LIMIT chunk_size
    FOR UPDATE SKIP LOCKED
  ), upd AS (
    UPDATE public.star_candy_bonus_history h
    SET remain_amount = 0
    FROM cte
    WHERE h.id = cte.id
    RETURNING h.user_id, cte.remain_amount
  )
  INSERT INTO tmp_upd_rows(user_id, remain_amount)
  SELECT user_id, remain_amount FROM upd;

  SELECT COALESCE(COUNT(*),0), COALESCE(SUM(remain_amount),0), COALESCE(COUNT(DISTINCT user_id),0)
  INTO batch_count, batch_amount, batch_users
  FROM tmp_upd_rows;

  WITH affected AS (
    SELECT DISTINCT user_id FROM tmp_upd_rows
  ), agg AS (
    SELECT a.user_id,
           COALESCE(SUM(h.remain_amount),0) AS total_remain
    FROM affected a
    LEFT JOIN public.star_candy_bonus_history h
      ON h.user_id = a.user_id
     AND h.remain_amount > 0
     AND h.expired_dt > now()
     AND h.deleted_at IS NULL
    GROUP BY a.user_id
  )
  UPDATE public.user_profiles up
  SET star_candy_bonus = agg.total_remain,
      updated_at = now()
  FROM agg
  WHERE up.id = agg.user_id;

  PERFORM set_config('statement_timeout', v_prev_timeout, true);
  PERFORM set_config('app.skip_sync_bonus','0',true);

  RETURN QUERY SELECT batch_count, batch_amount, batch_users;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."expire_star_candy_bonus_core"("cutoff_time" timestamp with time zone, "chunk_size" integer DEFAULT 500) RETURNS TABLE("batch_count" integer, "batch_amount" bigint, "batch_users" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
BEGIN
  PERFORM set_config('TimeZone','Asia/Seoul',true);
  PERFORM set_config('app.skip_sync_bonus','1',true);

  CREATE TEMP TABLE IF NOT EXISTS tmp_upd_rows(user_id uuid, remain_amount int) ON COMMIT DROP;
  TRUNCATE tmp_upd_rows;

  WITH cte AS (
    SELECT id, user_id, remain_amount
    FROM public.star_candy_bonus_history
    WHERE expired_dt <= cutoff_time
      AND remain_amount > 0
      AND deleted_at IS NULL
    ORDER BY expired_dt
    LIMIT chunk_size
    FOR UPDATE SKIP LOCKED
  ), upd AS (
    UPDATE public.star_candy_bonus_history h
    SET remain_amount = 0
    FROM cte
    WHERE h.id = cte.id
    RETURNING h.user_id, cte.remain_amount
  )
  INSERT INTO tmp_upd_rows(user_id, remain_amount)
  SELECT user_id, remain_amount FROM upd;

  SELECT COALESCE(COUNT(*),0), COALESCE(SUM(remain_amount),0), COALESCE(COUNT(DISTINCT user_id),0)
  INTO batch_count, batch_amount, batch_users
  FROM tmp_upd_rows;

  INSERT INTO public.user_bonus_update_queue(user_id)
  SELECT DISTINCT user_id FROM tmp_upd_rows
  ON CONFLICT (user_id) DO NOTHING;

  RETURN QUERY SELECT batch_count, batch_amount, batch_users;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."fill_receipts_tx_key"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  plat text := lower(btrim(NEW.platform));
  env  text := lower(btrim(NEW.environment));
  inapp_last jsonb;
  latest_last jsonb;
BEGIN
  IF NEW.status <> 'valid' THEN
    RETURN NEW;
  END IF;

  IF NEW.tx_key IS NOT NULL AND btrim(NEW.tx_key) <> '' THEN
    RETURN NEW;
  END IF;

  IF plat = 'ios' THEN
    NEW.tx_key :=
      COALESCE(
        NEW.verification_data #>> '{jwt_payload,transactionId}',
        NEW.verification_data #>> '{jwt_payload,originalTransactionId}',
        NULL
      );

    IF NEW.tx_key IS NULL THEN
      inapp_last := NEW.verification_data #> '{receipt,in_app,-1}';
      latest_last := NEW.verification_data #> '{latest_receipt_info,-1}';

      NEW.tx_key :=
        COALESCE(
          inapp_last #>> '{transaction_id}',
          inapp_last #>> '{original_transaction_id}',
          latest_last #>> '{transaction_id}',
          latest_last #>> '{original_transaction_id}',
          NULL
        );
    END IF;
  END IF;

  IF NEW.tx_key IS NULL AND plat = 'android' THEN
    NEW.tx_key := NEW.receipt_data;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."generate_receipt_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF (NEW.receipt_data IS NOT NULL AND
        (NEW.receipt_hash IS NULL OR OLD.receipt_data != NEW.receipt_data)) THEN
        NEW.receipt_hash := encode(digest(NEW.receipt_data, 'md5'), 'hex');
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."get_artist_paid_votes"("p_vote_id" bigint DEFAULT NULL::bigint, "p_exclude_admin" boolean DEFAULT true) RETURNS TABLE("artist_id" bigint, "artist_name" "jsonb", "paid_candy_sum" numeric, "paid_vote_count" bigint, "paid_voter_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
select
    a.id as artist_id,
    a.name::jsonb as artist_name,
    sum(coalesce(vp.star_candy_usage, 0))::numeric as paid_candy_sum,
    count(*)::bigint as paid_vote_count,
    count(distinct vp.user_id)::bigint as paid_voter_count
from public.vote_pick vp
         join public.vote_item vi on vi.id = vp.vote_item_id
         join public.artist a on a.id = vi.artist_id
         left join public.user_profiles up on up.id = vp.user_id
where coalesce(vp.deleted_at, null) is null
  and coalesce(vp.star_candy_usage, 0) > 0
  and (p_vote_id is null or vp.vote_id = p_vote_id)
  and (not p_exclude_admin or coalesce(up.is_admin, false) = false)
group by a.id, a.name::jsonb
order by paid_candy_sum desc, paid_vote_count desc;
$$;

COMMENT ON FUNCTION "public"."get_artist_paid_votes"("p_vote_id" bigint, "p_exclude_admin" boolean) IS '아티스트별 유료(스타캔디 사용) 투표 합계를 반환. vote_id 필터와 관리자 제외 옵션 지원.';

CREATE OR REPLACE FUNCTION "public"."get_artist_request_count"("vote_id_param" integer, "artist_id_param" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    request_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO request_count
    FROM "public"."vote_item_request_users" viru
    WHERE viru.vote_id = vote_id_param AND viru.artist_id = artist_id_param;

    RETURN COALESCE(request_count, 0);
END;
$$;

