CREATE OR REPLACE FUNCTION "public"."get_expiring_bonus_prediction"() RETURNS TABLE("prediction_month" "text", "expiring_amount" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    current_timestamp TIMESTAMP WITH TIME ZONE := NOW() AT TIME ZONE 'UTC';
    cutoff_timestamp TIMESTAMP WITH TIME ZONE;
    next_month DATE;
    two_months_later DATE;
BEGIN
    cutoff_timestamp := DATE_TRUNC('month', current_timestamp) + INTERVAL '14 days 15 hours';

    next_month := DATE_TRUNC('month', current_timestamp + INTERVAL '1 month');
    two_months_later := DATE_TRUNC('month', current_timestamp + INTERVAL '2 months');

    IF current_timestamp < cutoff_timestamp THEN
        RETURN QUERY
            SELECT
                TO_CHAR(next_month, 'YYYY-MM') AS prediction_month,
                COALESCE(SUM(remain_amount), 0)::BIGINT AS expiring_amount
            FROM star_candy_bonus_history
            WHERE user_id = auth.uid()
              AND expired_dt >= next_month
              AND expired_dt < two_months_later
            UNION ALL
            SELECT
                TO_CHAR(two_months_later, 'YYYY-MM') AS prediction_month,
                COALESCE(SUM(remain_amount), 0)::BIGINT AS expiring_amount
            FROM star_candy_bonus_history
            WHERE user_id = auth.uid()
              AND expired_dt >= two_months_later
              AND expired_dt < (two_months_later + INTERVAL '1 month');
    ELSE
        RETURN QUERY
            SELECT
                TO_CHAR(next_month, 'YYYY-MM') AS prediction_month,
                COALESCE(SUM(remain_amount), 0)::BIGINT AS expiring_amount
            FROM star_candy_bonus_history
            WHERE user_id = auth.uid()
              AND expired_dt >= next_month
              AND expired_dt < two_months_later;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."get_expiring_bonus_prediction"("uri" character varying) RETURNS TABLE("prediction_month" "text", "expiring_amount" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    current_ts timestamp with time zone := now() at time zone 'Asia/Seoul'; -- KST 기준
    this_month date := date_trunc('month', current_ts);
    next_month date := this_month + interval '1 month';
    month_after_next date := this_month + interval '2 month';
begin
    return query
        select
            to_char(next_month, 'YYYY-MM') as prediction_month,
            coalesce(sum(remain_amount), 0)::bigint as expiring_amount
        from star_candy_bonus_history
        where user_id = auth.uid()
          and created_at >= this_month
          and created_at < this_month + interval '15 days'
          and expired_dt >= next_month
          and expired_dt < next_month + interval '1 month';

    return query
        select
            to_char(month_after_next, 'YYYY-MM') as prediction_month,
            coalesce(sum(remain_amount), 0)::bigint as expiring_amount
        from star_candy_bonus_history
        where user_id = auth.uid()
          and created_at >= this_month + interval '15 days'
          and created_at < next_month
          and expired_dt >= month_after_next
          and expired_dt < month_after_next + interval '1 month';
end;
$$;

CREATE OR REPLACE FUNCTION "public"."get_expiring_bonus_prediction_v2"("uri" "text" DEFAULT ''::"text") RETURNS TABLE("prediction_month" "text", "sum" bigint)
    LANGUAGE "plpgsql"
    AS $$
declare
  now_utc            timestamptz := now();                         -- 현재 UTC
  y_utc              int := extract(year  from now_utc);
  m_utc              int := extract(month from now_utc);

  curr_boundary_utc  timestamptz := make_timestamptz(y_utc, m_utc, 14, 15, 0, 0, 'UTC'); -- 이번달 14일 15:00 UTC
  next_boundary_utc  timestamptz;      -- 익월 14일 15:00 UTC
  prev_start_utc     timestamptz;      -- [prev_start_utc, next_boundary_utc) = 익월 구간
  next_next_utc      timestamptz;      -- 익익월 14일 15:00 UTC
begin
  if now_utc < curr_boundary_utc then
    next_boundary_utc := curr_boundary_utc;
  else
    next_boundary_utc := curr_boundary_utc + interval '1 month';
  end if;

  prev_start_utc := next_boundary_utc - interval '1 month';
  next_next_utc  := next_boundary_utc + interval '1 month';

  return query
    select
      to_char(next_boundary_utc, 'YYYY-MM') as prediction_month,
      coalesce((
        select sum(remain_amount)::bigint
        from public.star_candy_bonus_history h
        where h.user_id = auth.uid()
          and h.expired_dt >= prev_start_utc
          and h.expired_dt <  next_boundary_utc
      ), 0) as sum
    union all
    select
      to_char(next_next_utc, 'YYYY-MM') as prediction_month,
      coalesce((
        select sum(remain_amount)::bigint
        from public.star_candy_bonus_history h
        where h.user_id = auth.uid()
          and h.expired_dt >= next_boundary_utc
          and h.expired_dt <  next_next_utc
      ), 0) as sum
    order by 1;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."get_goonghap_i18n"("p_goonghap_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    is_paid_status boolean;
BEGIN
    SELECT is_paid INTO is_paid_status
    FROM goonghap_results
    WHERE id = p_goonghap_id;

    IF NOT FOUND THEN
        RETURN '[]'::jsonb;
    END IF;

    RETURN (
        SELECT COALESCE(jsonb_agg(
                                CASE
                                    WHEN is_paid_status THEN to_jsonb(i18n.*)
                                    ELSE to_jsonb(i18n.*) - 'details' - 'tips' || jsonb_build_object('details', NULL, 'tips', NULL)
                                    END
                        ), '[]'::jsonb)
        FROM goonghap_results_i18n i18n
        WHERE i18n.goonghap_id = p_goonghap_id
    );
END;
$$;

COMMENT ON FUNCTION "public"."get_goonghap_i18n"("p_goonghap_id" "uuid") IS '궁합 i18n 데이터 조회 (is_paid=false일 때 details, tips 숨김)';

CREATE OR REPLACE FUNCTION "public"."get_goonghap_result"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
  is_paid_status boolean;
  main_data jsonb;
  artist_data jsonb;
BEGIN
  SELECT to_jsonb(gr.*), gr.is_paid
  INTO main_data, is_paid_status
  FROM goonghap_results gr
  WHERE gr.id = p_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'artist_name', a.name,
    'artist_image', a.image
  )
  INTO artist_data
  FROM artist a
  WHERE a.id = (main_data->>'artist_id')::integer;

  IF artist_data IS NULL THEN
    artist_data := jsonb_build_object('artist_name', NULL, 'artist_image', NULL);
  END IF;

  result := main_data || artist_data || jsonb_build_object(
    'goonghap_results_i18n', (
      SELECT COALESCE(jsonb_agg(
        CASE
          WHEN is_paid_status THEN to_jsonb(i18n.*)
          ELSE to_jsonb(i18n.*) - 'details' - 'tips' || jsonb_build_object('details', NULL, 'tips', NULL)
        END
      ), '[]'::jsonb)
      FROM goonghap_results_i18n i18n
      WHERE i18n.goonghap_id = p_id
    )
  );

  RETURN result;
END;
$$;

COMMENT ON FUNCTION "public"."get_goonghap_result"("p_id" "uuid") IS '궁합 결과 조회 (artist 정보 포함, is_paid=false일 때 details, tips 숨김)';

CREATE OR REPLACE FUNCTION "public"."get_user_activity_unified"("p_user_id" "uuid", "p_limit" integer, "p_offset" integer) RETURNS TABLE("unified_id" "text", "source" "text", "created_at" timestamp with time zone, "user_id" "uuid", "amount" numeric, "subtype" "text", "transaction_id" "text", "vote_pick_id" bigint, "vote_title" "jsonb", "vote_item_title" "jsonb", "artist_name" "jsonb", "receipt_platform" "text", "receipt_product_id" "text", "receipt_status" "text", "receipt_environment" "text", "ad_source" "text", "ad_network" "text", "ad_reward_name" "text", "star_gain" numeric, "bonus_gain" numeric)
    LANGUAGE "sql" STABLE
    AS $$
with star_agg as (
    select coalesce(transaction_id::text, '') as txn,
           sum(case when amount > 0 then amount else 0 end)::numeric as sum_amount
    from public.star_candy_history
    where user_id = p_user_id
    group by 1
),
     bonus_agg as (
         select coalesce(transaction_id::text, '') as txn,
                sum(case when amount > 0 then amount else 0 end)::numeric as sum_amount
         from public.star_candy_bonus_history
         where user_id = p_user_id
         group by 1
     ),
     ad as (
         select
             ('AD:' || coalesce(vta.transaction_id, '')) as unified_id,
             'AD'::text as source,
             vta.created_at,
             vta.user_id,
             vta.reward_amount::numeric as amount,
             vta.reward_type::text as subtype,
             vta.transaction_id::text as transaction_id,
             null::bigint as vote_pick_id,
             null::jsonb as vote_title,
             null::jsonb as vote_item_title,
             null::jsonb as artist_name,
             vta.platform::text as receipt_platform,
             null::text as receipt_product_id,
             null::text as receipt_status,
             null::text as receipt_environment,
             vta.source::text as ad_source,
             case
                 when vta.source in ('admob','applovin','unity','tiktok','ironsource','vungle','adcolony','pangle','pincrux','tapjoy') then vta.source::text
                 else coalesce(nullif(vta.source::text, ''), nullif(vta.ad_network::text, ''))
                 end as ad_network,
             vta.reward_name::text as ad_reward_name,
             coalesce(s.sum_amount, 0) as star_gain,
             coalesce(b.sum_amount, 0) as bonus_gain
         from public.view_transaction_all vta
                  left join star_agg s on s.txn = vta.transaction_id::text
                  left join bonus_agg b on b.txn = vta.transaction_id::text
         where vta.user_id = p_user_id
     ),
     receipt as (
         select
             ('RECEIPT:' || r.id::text) as unified_id,
             'RECEIPT'::text as source,
             r.created_at,
             r.user_id,
             null::numeric as amount,
             null::text as subtype,
             null::text as transaction_id,
             null::bigint as vote_pick_id,
             null::jsonb as vote_title,
             null::jsonb as vote_item_title,
             null::jsonb as artist_name,
             r.platform::text as receipt_platform,
             r.product_id::text as receipt_product_id,
             r.status::text as receipt_status,
             r.environment::text as receipt_environment,
             null::text as ad_source,
             null::text as ad_network,
             null::text as ad_reward_name,
             coalesce(p.star_candy, 0)::numeric as star_gain,
             coalesce(p.star_candy_bonus, 0)::numeric as bonus_gain
         from public.receipts r
                  left join public.products p on p.id = r.product_id
         where r.user_id = p_user_id
     ),
     vote as (
         select
             ('VOTE:' || vp.id::text) as unified_id,
             'VOTE'::text as source,
             vp.created_at,
             vp.user_id,
             vp.amount::numeric as amount,
             'VOTE'::text as subtype,
             null::text as transaction_id,
             vp.id::bigint as vote_pick_id,
             v.title::jsonb as vote_title,
             null::jsonb as vote_item_title,
             a.name::jsonb as artist_name,
             null::text as receipt_platform,
             null::text as receipt_product_id,
             null::text as receipt_status,
             null::text as receipt_environment,
             null::text as ad_source,
             null::text as ad_network,
             null::text as ad_reward_name,
             null::numeric as star_gain,
             null::numeric as bonus_gain
         from public.vote_pick vp
                  left join public.vote v on v.id = vp.vote_id
                  left join public.vote_item vi on vi.id = vp.vote_item_id
                  left join public.artist a on a.id = vi.artist_id
         where vp.user_id = p_user_id
     )
select *
from (
         select * from receipt
         union all
         select * from ad
         union all
         select * from vote
     ) u
order by created_at desc
limit p_limit offset p_offset;
$$;

CREATE OR REPLACE FUNCTION "public"."get_user_activity_unified_count"("p_user_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE
    AS $$
select (
           (select count(*) from public.receipts r where r.user_id = p_user_id) +
           (select count(*) from public.view_transaction_all v where v.user_id = p_user_id) +
           (select count(*) from public.vote_pick vp where vp.user_id = p_user_id)
           )::bigint;
$$;

CREATE OR REPLACE FUNCTION "public"."get_user_profile"("user_id" "uuid") RETURNS TABLE("id" "uuid", "email" "text", "nickname" "text", "avatar_url" "text", "is_admin" boolean, "star_candy" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF auth.uid() != user_id THEN
        RAISE EXCEPTION 'Access denied: Can only view own profile';
    END IF;

    RETURN QUERY
    SELECT
        up.id,
        up.email,
        up.nickname,
        up.avatar_url,
        up.is_admin,
        up.star_candy,
        up.created_at,
        up.updated_at
    FROM user_profiles up
    WHERE up.id = user_id
    AND up.deleted_at IS NULL;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."get_user_qna_stats"("user_id_param" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
BEGIN
  SELECT json_build_object(
    'total', COUNT(*),
    'pending', COUNT(*) FILTER (WHERE status = 'PENDING'),
    'answered', COUNT(*) FILTER (WHERE status = 'ANSWERED'),
    'resolved', COUNT(*) FILTER (WHERE status = 'RESOLVED')
  )
  INTO result
  FROM qnas
  WHERE
    created_by::uuid = user_id_param::uuid
    AND deleted_at IS NULL;

  RETURN result;
END;
$$;

COMMENT ON FUNCTION "public"."get_user_qna_stats"("user_id_param" "text") IS 'Get QnA statistics for a user (excluding deleted items)';

CREATE OR REPLACE FUNCTION "public"."get_vote_and_user_info"("p_vote_id" integer, "p_user_id" integer) RETURNS TABLE("stop_at" "text", "star_candy" integer, "star_candy_bonus" integer, "total_bonus_remain" bigint)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
        SELECT
            to_char(v.stop_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),  -- Convert to ISO 8601 format
            up.star_candy,
            up.star_candy_bonus,
            COALESCE(SUM(scbh.remain_amount), 0) as total_bonus_remain
        FROM vote v
                 JOIN user_profiles up ON up.id = p_user_id
                 LEFT JOIN star_candy_bonus_history scbh ON scbh.user_id = up.id AND scbh.expired_dt > NOW() AND scbh.remain_amount > 0
        WHERE v.id = p_vote_id
        GROUP BY v.stop_at, up.star_candy, up.star_candy_bonus;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$declare
    v_nickname text;
    v_avatar_url text;
    v_email text;
    v_provider text;
    v_unique_nickname text;
    v_random_number int;
begin
    insert into public.debug_logs (log_message)
    values ('Trigger function handle_new_user() called with user ID: ' || new.id);

    insert into public.debug_logs (log_message)
    values ('raw_user_meta_data: ' || coalesce(new.raw_user_meta_data::text, 'NULL'));

    v_provider := new.raw_user_meta_data->>'provider';
    insert into public.debug_logs (log_message)
    values ('Login provider: ' || coalesce(v_provider, 'unknown'));

    v_email := new.email;
    insert into public.debug_logs (log_message)
    values ('Email: ' || coalesce(v_email, 'NULL'));

    if v_provider = 'apple' then
        v_nickname := split_part(v_email, '@', 1);
        v_avatar_url := null; -- 애플은 picture를 제공하지 않음
        insert into public.debug_logs (log_message)
        values ('Apple login detected. Extracted nickname: ' || coalesce(v_nickname, 'NULL'));
    else
        v_nickname := coalesce(new.raw_user_meta_data->>'name', split_part(v_email, '@', 1));
        v_avatar_url := new.raw_user_meta_data->>'picture';
        insert into public.debug_logs (log_message)
        values ('Non-Apple login detected. Nickname: ' || coalesce(v_nickname, 'NULL'));
    end if;

    v_nickname := replace(v_nickname, ' ', '');

    insert into public.debug_logs (log_message)
    values ('Nickname after removing spaces: ' || coalesce(v_nickname, 'NULL'));

    v_random_number := floor(random() * 9000 + 1000)::int;

    v_unique_nickname := v_nickname || v_random_number::text;

    while exists (select 1 from public.user_profiles where nickname = v_unique_nickname) loop
        v_random_number := floor(random() * 9000 + 1000)::int;
        v_unique_nickname := v_nickname || v_random_number::text;
    end loop;

    insert into public.debug_logs (log_message)
    values ('Generated unique nickname: ' || v_unique_nickname);

    insert into public.debug_logs (log_message)
    values ('Final values - v_unique_nickname: ' || coalesce(v_unique_nickname, 'NULL') ||
            ', v_avatar_url: ' || coalesce(v_avatar_url, 'NULL') ||
            ', v_email: ' || coalesce(v_email, 'NULL'));

    insert into public.debug_logs (log_message)
    values ('Attempting to insert into user_profiles');

    insert into public.user_profiles (id, nickname, avatar_url, email)
    values (new.id, v_unique_nickname, v_avatar_url, v_email);

    insert into public.debug_logs (log_message)
    values ('New user profile created for user ID: ' || new.id || ', Provider: ' || v_provider || ', Unique Nickname: ' || v_unique_nickname);

    return new;
exception
    when others then
        insert into public.debug_logs (log_message)
        values ('Error creating user profile: ' || sqlerrm || ', Provider: ' || coalesce(v_provider, 'unknown'));
        return null;
end;$$;

CREATE OR REPLACE FUNCTION "public"."handle_receipt_deletion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    _vote_pick_record RECORD;
BEGIN
    FOR _vote_pick_record IN
        SELECT * FROM vote_pick
        WHERE user_id = OLD.user_id
        LOOP
            UPDATE vote_item
            SET vote_total = vote_total - _vote_pick_record.amount
            WHERE id = _vote_pick_record.vote_item_id;
        END LOOP;

    DELETE FROM vote_pick
    WHERE user_id = OLD.user_id;

    UPDATE user_profiles
    SET
        star_candy = 0,
        star_candy_bonus = 0
    WHERE id = OLD.user_id;

    DELETE FROM star_candy_history
    WHERE user_id = OLD.user_id;

    DELETE FROM star_candy_bonus_history
    WHERE user_id = OLD.user_id;

    RETURN OLD;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."has_user_requested_artist"("vote_id_param" integer, "artist_id_param" integer, "user_id_param" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
