        SELECT 1 FROM "public"."vote_item_request_users" viru
        WHERE viru.vote_id = vote_id_param
          AND viru.artist_id = artist_id_param
          AND viru.user_id = user_id_param
    );
END;
$$;

CREATE OR REPLACE FUNCTION "public"."increment_star_candy"("p_user_id" "uuid", "p_amount" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  new_balance INTEGER;
BEGIN
  UPDATE user_profiles
  SET star_candy = COALESCE(star_candy, 0) + p_amount
  WHERE id = p_user_id
  RETURNING star_candy INTO new_balance;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User profile not found: %', p_user_id;
  END IF;

  RETURN new_balance;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."increment_star_candy_bonus"("p_user_id" "uuid", "p_amount" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  new_balance INTEGER;
BEGIN
  UPDATE user_profiles
  SET star_candy_bonus = COALESCE(star_candy_bonus, 0) + p_amount
  WHERE id = p_user_id
  RETURNING star_candy_bonus INTO new_balance;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User profile not found: %', p_user_id;
  END IF;

  RETURN new_balance;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."increment_user_star_candy_bonus"("p_user_id" "uuid", "p_amount" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    UPDATE user_profiles
    SET star_candy_bonus = COALESCE(star_candy_bonus, 0) + p_amount
    WHERE id = p_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."increment_view_count"("post_id_param" "uuid", "viewer_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    post_author_id uuid;
BEGIN
    SELECT user_id INTO post_author_id
    FROM posts
    WHERE post_id = post_id_param;

    IF viewer_id IS NOT NULL AND post_author_id != viewer_id AND
       NOT EXISTS (
           SELECT 1
           FROM post_views
           WHERE post_id = post_id_param AND user_id = viewer_id
       ) THEN
        UPDATE posts
        SET view_count = view_count + 1
        WHERE post_id = post_id_param;

        INSERT INTO post_views (post_id, user_id)
        VALUES (post_id_param, viewer_id)
        ON CONFLICT (post_id, user_id) DO NOTHING;
    END IF;
END;
$$;

