CREATE OR REPLACE FUNCTION "public"."is_vote_item_request_open"("vote_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    vote_start_at TIMESTAMP;
    vote_stop_at TIMESTAMP;
    now_time TIMESTAMP;
BEGIN
    SELECT start_at, stop_at INTO vote_start_at, vote_stop_at
    FROM "public"."vote"
    WHERE id = vote_id;

    now_time := NOW();

    RETURN (vote_start_at IS NULL OR now_time < vote_stop_at);
END;
$$;

CREATE OR REPLACE FUNCTION "public"."list_bonus_drift"("p_limit" integer DEFAULT 100, "p_threshold" numeric DEFAULT 1) RETURNS TABLE("user_id" "uuid", "profile_bonus" numeric, "history_bonus" numeric, "delta" numeric, "last_history_at" timestamp with time zone)
    LANGUAGE "sql"
    AS $$
SELECT user_id, profile_bonus, history_bonus, delta, last_history_at
FROM public.vw_star_candy_bonus_drift
WHERE ABS(delta) >= COALESCE(p_threshold, 1)
ORDER BY ABS(delta) DESC
LIMIT COALESCE(p_limit, 100);
$$;

CREATE OR REPLACE FUNCTION "public"."list_bonus_drift"("p_threshold" numeric DEFAULT 5, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 10) RETURNS TABLE("user_id" "uuid", "profile_bonus" numeric, "history_bonus" numeric, "delta" numeric, "last_history_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "sql"
    AS $$
WITH drift AS (
    SELECT
        up.id AS user_id,
        up.star_candy_bonus AS profile_bonus,
        COALESCE(SUM(
                         CASE
                             WHEN h.parent_id IS NULL
                                 AND h.deleted_at IS NULL
                                 AND COALESCE(h.remain_amount, 0) > 0
                                 THEN h.remain_amount
                             ELSE 0
                             END
                 ), 0) AS history_bonus,
        MAX(h.updated_at) AS last_history_at
    FROM public.user_profiles up
             LEFT JOIN public.star_candy_bonus_history h
                       ON h.user_id = up.id
    GROUP BY up.id, up.star_candy_bonus
), filtered AS (
    SELECT
        d.*,
        d.history_bonus - COALESCE(d.profile_bonus, 0) AS delta
    FROM drift d
    WHERE ABS(d.history_bonus - COALESCE(d.profile_bonus, 0)) >= COALESCE(p_threshold, 5)
)
SELECT
    f.user_id,
    f.profile_bonus,
    f.history_bonus,
    f.delta,
    f.last_history_at,
    COUNT(*) OVER () AS total_count
FROM filtered f
ORDER BY ABS(f.delta) DESC
LIMIT COALESCE(p_page_size, 10)
    OFFSET (GREATEST(p_page, 1) - 1) * COALESCE(p_page_size, 10);
$$;

COMMENT ON FUNCTION "public"."list_bonus_drift"("p_threshold" numeric, "p_page" integer, "p_page_size" integer) IS 'Returns paginated bonus differences (history vs profile) ordered by absolute delta with window-count total.';

CREATE OR REPLACE FUNCTION "public"."log_user_bonus_queue_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    INSERT INTO public.user_bonus_queue_audit(user_id, source, note)
    VALUES (OLD.user_id, current_setting('application_name', true), TG_ARGV[0]);
    RETURN OLD;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."next_star_candy_bonus_expiry"("p_source" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    ts_utc TIMESTAMPTZ := p_source;
    ts_kst TIMESTAMPTZ := p_source + INTERVAL '9 hours';
    target_month INT;
    target_year  INT;
BEGIN
    target_year  := EXTRACT(YEAR FROM ts_kst);
    target_month := EXTRACT(MONTH FROM ts_kst)::INT - 1;

    IF EXTRACT(DAY FROM ts_kst) < 15 THEN
        target_month := target_month + 1;
    ELSE
        target_month := target_month + 2;
    END IF;

    WHILE target_month >= 12 LOOP
            target_month := target_month - 12;
            target_year  := target_year + 1;
        END LOOP;

    RETURN make_timestamptz(target_year, target_month + 1, 15, 0, 0, 0) AT TIME ZONE 'Asia/Seoul' - INTERVAL '9 hours';
END;
$$;

CREATE OR REPLACE FUNCTION "public"."perform_pic_vote_transaction"("p_vote_id" integer, "p_vote_item_id" integer, "p_amount" integer, "p_user_id" "uuid") RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_vote_data RECORD;
    v_vote_pick_id INT;
    v_result JSON;
BEGIN
    SELECT
        v.stop_at > NOW() as is_open,
        pvi.vote_total as existing_vote_total
    INTO v_vote_data
    FROM pic_vote v
             JOIN pic_vote_item pvi ON pvi.id = p_vote_item_id
    WHERE v.id = p_vote_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION '투표 없음';
    END IF;

    IF NOT v_vote_data.is_open THEN
        RAISE EXCEPTION '투표가 종료되었습니다';
    END IF;

    IF NOT can_vote(p_user_id, p_amount) THEN
        RAISE EXCEPTION '보유한 star_candy 및 bonus가 부족합니다';
    END IF;

    BEGIN
        INSERT INTO pic_vote_pick (vote_id, vote_item_id, amount, user_id)
        VALUES (p_vote_id, p_vote_item_id, p_amount, p_user_id)
        RETURNING id INTO v_vote_pick_id;

        PERFORM perform_vote_deduction(p_user_id, p_amount, v_vote_pick_id);

        v_result := json_build_object(
                'existingVoteTotal', v_vote_data.existing_vote_total,
                'addedVoteTotal', p_amount,
                'updatedVoteTotal', v_vote_data.existing_vote_total + p_amount,
                'updatedAt', NOW(),
                'votePickId', v_vote_pick_id
                    );

        RETURN v_result;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE EXCEPTION '트랜잭션 실패: %', SQLERRM;
    END;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."perform_vote_deduction"("p_user_id" "uuid", "p_vote_amount" integer, "p_vote_pick_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_user_profile user_profiles%ROWTYPE;
    v_remaining_amt INT;
    v_deduction_amt INT;
BEGIN
    SELECT *
    INTO STRICT v_user_profile
    FROM user_profiles
    WHERE id = p_user_id
        FOR UPDATE;

    IF v_user_profile.star_candy + v_user_profile.star_candy_bonus < p_vote_amount THEN
        RAISE EXCEPTION
            USING
                MESSAGE = format(
                        'Insufficient total balance: requested = %s, star_candy = %s, bonus = %s',
                        p_vote_amount, v_user_profile.star_candy, v_user_profile.star_candy_bonus
                          ),
                HINT = 'Ensure user_profiles has sufficient balance.';
    END IF;

    v_remaining_amt := p_vote_amount;

    IF v_user_profile.star_candy_bonus > 0 AND v_remaining_amt > 0 THEN
        v_deduction_amt := LEAST(v_user_profile.star_candy_bonus, v_remaining_amt);

        UPDATE user_profiles
        SET star_candy_bonus = star_candy_bonus - v_deduction_amt
        WHERE id = p_user_id;

        v_remaining_amt := v_remaining_amt - v_deduction_amt;
    END IF;

    IF v_remaining_amt > 0 THEN
        IF v_user_profile.star_candy < v_remaining_amt THEN
            RAISE EXCEPTION
                USING
                    MESSAGE = format(
                            'star_candy 부족: tried to deduct %s, only %s available',
                            v_remaining_amt, v_user_profile.star_candy
                              ),
                    HINT = 'This should not occur if can_vote() passed.';
        END IF;

        UPDATE user_profiles
        SET star_candy = star_candy - v_remaining_amt
        WHERE id = p_user_id;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."perform_vote_transaction"("p_vote_id" integer, "p_vote_item_id" integer, "p_amount" integer, "p_user_id" "uuid") RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_vote_data        RECORD;
    v_vote_pick_id     INT;
    v_result           JSON;
BEGIN
    SELECT
        v.stop_at > NOW() AS is_open,
        vi.vote_total     AS existing_vote_total
    INTO v_vote_data
    FROM vote v
         JOIN vote_item vi ON vi.id = p_vote_item_id
    WHERE v.id = p_vote_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Vote not found';
    END IF;

    IF NOT v_vote_data.is_open THEN
        RAISE EXCEPTION 'Vote is closed';
    END IF;

    IF NOT can_vote(p_user_id, p_amount) THEN
        RAISE EXCEPTION 'Insufficient star_candy and star_candy_bonus to vote';
    END IF;

    BEGIN
        INSERT INTO vote_pick (vote_id, vote_item_id, amount, user_id)
        VALUES (p_vote_id, p_vote_item_id, p_amount, p_user_id)
        RETURNING id INTO v_vote_pick_id;

        PERFORM perform_vote_deduction(p_user_id, p_amount, v_vote_pick_id);

        v_result := json_build_object(
            'existingVoteTotal', v_vote_data.existing_vote_total,
            'addedVoteTotal', p_amount,
            'updatedVoteTotal', v_vote_data.existing_vote_total + p_amount,
            'updatedAt', NOW()
        );

        RETURN v_result;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE EXCEPTION 'Transaction failed: %', SQLERRM;
    END;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."prevent_general_category_modification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF (TG_OP = 'DELETE') THEN
        IF OLD.code = 'GENERAL' THEN
            RAISE EXCEPTION 'GENERAL 카테고리는 삭제할 수 없습니다.';
        END IF;
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        IF OLD.code = 'GENERAL' AND NEW.code <> OLD.code THEN
            RAISE EXCEPTION 'GENERAL 카테고리의 코드는 변경할 수 없습니다.';
        END IF;
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."process_attendance_check"("p_user_id" "uuid", "p_check_date" "date", "p_reward_amount" integer, "p_weekly_bonus_amount" integer, "p_expired_dt" timestamp with time zone, "p_transaction_id" "text", "p_weekly_transaction_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.attendance_check (user_id, check_date, reward_amount, weekly_bonus_amount)
  VALUES (p_user_id, p_check_date, p_reward_amount, p_weekly_bonus_amount);

  INSERT INTO public.star_candy_bonus_history (user_id, type, amount, remain_amount, expired_dt, transaction_id)
  VALUES (p_user_id, 'ATTENDANCE', p_reward_amount, p_reward_amount, p_expired_dt, p_transaction_id);

  IF p_weekly_bonus_amount > 0 AND p_weekly_transaction_id IS NOT NULL THEN
    INSERT INTO public.star_candy_bonus_history (user_id, type, amount, remain_amount, expired_dt, transaction_id)
    VALUES (p_user_id, 'ATTENDANCE_WEEKLY', p_weekly_bonus_amount, p_weekly_bonus_amount, p_expired_dt, p_weekly_transaction_id);
  END IF;

  RETURN jsonb_build_object('success', true);

EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'code', 'ALREADY_CHECKED');
END;
$$;

CREATE OR REPLACE FUNCTION "public"."process_bonus_recalc"("p_limit" integer DEFAULT 50) RETURNS TABLE("user_id" "uuid", "processed_at" timestamp with time zone, "status" "text", "message" "text")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    rec RECORD;
    v_now TIMESTAMPTZ := NOW();
BEGIN
    FOR rec IN
        SELECT *
        FROM public.user_bonus_update_queue
        WHERE next_run_at <= v_now
        ORDER BY next_run_at, id
            FOR UPDATE SKIP LOCKED
        LIMIT COALESCE(p_limit, 50)
        LOOP
            BEGIN
                PERFORM public.recompute_user_bonus(rec.user_id);
                DELETE FROM public.user_bonus_update_queue WHERE id = rec.id;

                user_id      := rec.user_id;
                processed_at := NOW();
                status       := 'ok';
                message      := NULL;
                RETURN NEXT;
            EXCEPTION
                WHEN OTHERS THEN
                    UPDATE public.user_bonus_update_queue
                    SET attempts   = rec.attempts + 1,
                        last_error = SQLERRM,
                        next_run_at = NOW() + make_interval(mins => LEAST(60, POWER(2, LEAST(rec.attempts + 1, 8))))
                    WHERE id = rec.id;

                    user_id      := rec.user_id;
                    processed_at := NOW();
                    status       := 'error';
                    message      := SQLERRM;
                    RETURN NEXT;
            END;
        END LOOP;

    RETURN;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."process_compatibility_payment"("p_user_id" "uuid", "p_compatibility_id" "uuid", "p_star_candy_amount" integer DEFAULT 100) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
SELECT public.process_goonghap_payment(p_user_id, p_compatibility_id, p_star_candy_amount);
$$;

CREATE OR REPLACE FUNCTION "public"."process_goonghap_payment"("p_user_id" "uuid", "p_goonghap_id" "uuid", "p_star_candy_amount" integer DEFAULT 100) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE user_profiles
    SET star_candy = star_candy - p_star_candy_amount
    WHERE id = p_user_id
      AND star_candy >= p_star_candy_amount;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient star candy or user not found';
    END IF;

    INSERT INTO star_candy_history (user_id, amount, type, reference_id)
    VALUES (p_user_id, -p_star_candy_amount, 'OPEN_GOONGHAP', p_goonghap_id);

    UPDATE goonghap_results
    SET is_paid = true,
        paid_at = now()
    WHERE id = p_goonghap_id;
END;
$$;

COMMENT ON FUNCTION "public"."process_goonghap_payment"("p_user_id" "uuid", "p_goonghap_id" "uuid", "p_star_candy_amount" integer) IS '궁합 결과 유료 결제 처리';

CREATE OR REPLACE FUNCTION "public"."process_paypal_capture"("p_user_id" "uuid", "p_order_id" "text", "p_capture_id" "text", "p_product_id" "text", "p_star_candy" integer, "p_bonus_amount" integer, "p_amount" "text", "p_currency" "text", "p_status" "text", "p_environment" "text", "p_payment_details" "jsonb", "p_verification_data" "jsonb", "p_bonus_expiry" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_receipt_id bigint;
  v_transaction_id text := 'PAYPAL_' || p_order_id;
  v_receipt_data jsonb;
BEGIN
  v_receipt_data := jsonb_build_object(
    'order_id', p_order_id,
    'capture_id', p_capture_id,
    'amount', p_amount,
    'currency', p_currency,
    'status', p_status,
    'payment_details', p_payment_details
  );

  IF EXISTS (
    SELECT 1 FROM public.star_candy_history WHERE transaction_id = v_transaction_id
  ) OR EXISTS (
    SELECT 1 FROM public.star_candy_bonus_history
    WHERE user_id = p_user_id AND transaction_id = v_transaction_id
  ) THEN
    RAISE LOG 'process_paypal_capture: idempotent skip via history pre-check, transaction_id=%, user_id=%, order_id=%',
      v_transaction_id, p_user_id, p_order_id;
    RETURN NULL;
  END IF;

  BEGIN
    INSERT INTO public.receipts (
      user_id, product_id, receipt_data, receipt_hash, status, platform, environment, verification_data
    ) VALUES (
      p_user_id, p_product_id, v_receipt_data::text, p_order_id, 'completed', 'web', p_environment, p_verification_data
    )
    RETURNING id INTO v_receipt_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE LOG 'process_paypal_capture: idempotent skip via receipts unique index, order_id=%, user_id=%',
        p_order_id, p_user_id;
      RETURN NULL;
  END;

  INSERT INTO public.star_candy_history (user_id, amount, type, transaction_id)
  VALUES (p_user_id, p_star_candy, 'PURCHASE'::candy_history_type, v_transaction_id);

  UPDATE public.user_profiles
  SET star_candy = star_candy + p_star_candy, updated_at = now()
  WHERE id = p_user_id;

  IF p_bonus_amount > 0 THEN
    INSERT INTO public.star_candy_bonus_history (
      user_id, amount, remain_amount, type, transaction_id, expired_dt
    ) VALUES (
      p_user_id, p_bonus_amount, p_bonus_amount, 'PURCHASE', v_transaction_id, p_bonus_expiry
    );

    UPDATE public.user_profiles
    SET star_candy_bonus = star_candy_bonus + p_bonus_amount, updated_at = now()
    WHERE id = p_user_id;
  END IF;

  RETURN jsonb_build_object(
    'receipt_id', v_receipt_id,
    'granted_star_candy', p_star_candy,
    'granted_bonus', p_bonus_amount
  );
END;
$$;

COMMENT ON FUNCTION "public"."process_paypal_capture"("p_user_id" "uuid", "p_order_id" "text", "p_capture_id" "text", "p_product_id" "text", "p_star_candy" integer, "p_bonus_amount" integer, "p_amount" "text", "p_currency" "text", "p_status" "text", "p_environment" "text", "p_payment_details" "jsonb", "p_verification_data" "jsonb", "p_bonus_expiry" timestamp with time zone) IS 'Atomic PayPal capture processing: receipt + star_candy history + balance + bonus in single transaction. NULL = already processed (idempotent). Error = rollback. Caller MUST be service_role.';

CREATE OR REPLACE FUNCTION "public"."process_portone_capture"("p_user_id" "uuid", "p_payment_id" "text", "p_product_id" "text", "p_star_candy" integer, "p_bonus_amount" integer, "p_total_amount" numeric, "p_currency" "text", "p_status" "text", "p_method" "text", "p_environment" "text", "p_receipt_data" "jsonb", "p_verification_data" "jsonb", "p_bonus_expiry" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_receipt_id bigint;
  v_transaction_id text := 'PURCHASE_' || p_payment_id;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.star_candy_history WHERE transaction_id = v_transaction_id
  ) OR EXISTS (
    SELECT 1 FROM public.star_candy_bonus_history
    WHERE user_id = p_user_id AND transaction_id = v_transaction_id
  ) THEN
    RAISE LOG 'process_portone_capture: idempotent skip via history pre-check, transaction_id=%, user_id=%, payment_id=%',
      v_transaction_id, p_user_id, p_payment_id;
    RETURN NULL;
  END IF;

  BEGIN
    INSERT INTO public.receipts (
      user_id, product_id, receipt_data, receipt_hash, status, platform, environment, verification_data
    ) VALUES (
      p_user_id, p_product_id, p_receipt_data::text, p_payment_id, 'completed', 'web', p_environment, p_verification_data
    )
    RETURNING id INTO v_receipt_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE LOG 'process_portone_capture: idempotent skip via receipts unique index, payment_id=%, user_id=%',
        p_payment_id, p_user_id;
      RETURN NULL;
  END;

  INSERT INTO public.star_candy_history (user_id, amount, type, transaction_id)
  VALUES (p_user_id, p_star_candy, 'PURCHASE'::candy_history_type, v_transaction_id);

  UPDATE public.user_profiles
  SET star_candy = star_candy + p_star_candy, updated_at = now()
  WHERE id = p_user_id;

  IF p_bonus_amount > 0 THEN
    INSERT INTO public.star_candy_bonus_history (
      user_id, amount, remain_amount, type, transaction_id, expired_dt
    ) VALUES (
      p_user_id, p_bonus_amount, p_bonus_amount, 'PURCHASE', v_transaction_id, p_bonus_expiry
    );

    UPDATE public.user_profiles
    SET star_candy_bonus = star_candy_bonus + p_bonus_amount, updated_at = now()
    WHERE id = p_user_id;
  END IF;

  PERFORM p_total_amount, p_currency, p_status, p_method;

  RETURN jsonb_build_object(
    'receipt_id', v_receipt_id,
    'granted_star_candy', p_star_candy,
    'granted_bonus', p_bonus_amount
  );
END;
$$;

COMMENT ON FUNCTION "public"."process_portone_capture"("p_user_id" "uuid", "p_payment_id" "text", "p_product_id" "text", "p_star_candy" integer, "p_bonus_amount" integer, "p_total_amount" numeric, "p_currency" "text", "p_status" "text", "p_method" "text", "p_environment" "text", "p_receipt_data" "jsonb", "p_verification_data" "jsonb", "p_bonus_expiry" timestamp with time zone) IS 'Atomic PortOne v2 capture processing. Mirrors process_paypal_capture but uses PURCHASE_<paymentId> transaction_id prefix. NULL = already processed. Caller MUST be service_role.';

CREATE OR REPLACE FUNCTION "public"."process_vote"("p_vote_id" integer, "p_vote_item_id" integer, "p_amount" integer, "p_user_id" "uuid", "p_total_bonus_remain" bigint) RETURNS TABLE("vote_total" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_vote_pick_id INTEGER;
    v_deducted_bonus INTEGER;
    v_deducted_regular INTEGER;
BEGIN
    INSERT INTO vote_pick (vote_id, vote_item_id, amount, user_id)
    VALUES (p_vote_id, p_vote_item_id, p_amount, p_user_id)
    RETURNING id INTO v_vote_pick_id;

    UPDATE vote_item
    SET vote_total = vote_total + p_amount
    WHERE id = p_vote_item_id
    RETURNING vote_total INTO vote_total;

    v_deducted_bonus := LEAST(p_amount, p_total_bonus_remain);

    WITH bonus_deduction AS (
        UPDATE star_candy_bonus_history
            SET remain_amount =
                    CASE
                        WHEN remain_amount >= v_deducted_bonus THEN remain_amount - v_deducted_bonus
                        ELSE 0
                        END,
                updated_at = NOW()
            WHERE user_id = p_user_id
                AND expired_dt > NOW()
                AND remain_amount > 0
            RETURNING
                id,
                CASE
                    WHEN remain_amount >= v_deducted_bonus THEN v_deducted_bonus
                    ELSE remain_amount
                    END as deducted_amount
    )
    INSERT INTO star_candy_bonus_history (user_id, amount, remain_amount, parent_id, vote_pick_id)
    SELECT p_user_id, deducted_amount, deducted_amount, id, v_vote_pick_id
    FROM bonus_deduction
    WHERE deducted_amount > 0;

    v_deducted_regular := p_amount - v_deducted_bonus;

    UPDATE user_profiles
    SET
        star_candy_bonus = GREATEST(star_candy_bonus - v_deducted_bonus, 0),
        star_candy = GREATEST(star_candy - v_deducted_regular, 0)
    WHERE id = p_user_id;

    IF v_deducted_regular > 0 THEN
        INSERT INTO star_candy_history (type, user_id, amount, vote_pick_id)
        VALUES ('VOTE', p_user_id, v_deducted_regular, v_vote_pick_id);
    END IF;

    RETURN;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."process_vote_item_queue"("p_vote_item_id" integer) RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
SELECT public.process_vote_item_queue(p_vote_item_id::bigint, 1000);
$$;

CREATE OR REPLACE FUNCTION "public"."process_vote_item_queue"("p_vote_item_id" bigint, "p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_processed integer := 0;
    v_vote_id   bigint;
    v_add_star  numeric := 0;
    v_add_bonus numeric := 0;
    v_add_votes numeric := 0;
    v_ids       bigint[];
BEGIN
    WITH s AS (
        SELECT id,
               COALESCE(delta_star, 0)  AS d_star,
               COALESCE(delta_bonus, 0) AS d_bonus,
               COALESCE(delta_amount, 0) AS d_votes
        FROM public.vote_item_update_queue
        WHERE vote_item_id = p_vote_item_id
        ORDER BY id
            FOR UPDATE SKIP LOCKED
        LIMIT p_limit
    )
    SELECT array_agg(id), COALESCE(SUM(d_star), 0), COALESCE(SUM(d_bonus), 0), COALESCE(SUM(d_votes), 0)
    INTO v_ids, v_add_star, v_add_bonus, v_add_votes
    FROM s;

    v_processed := COALESCE(array_length(v_ids, 1), 0);
    IF v_processed = 0 THEN
        RETURN 0;
    END IF;

    UPDATE public.vote_item vi
    SET star_candy_total       = COALESCE(vi.star_candy_total, 0) + v_add_star,
        star_candy_bonus_total = COALESCE(vi.star_candy_bonus_total, 0) + v_add_bonus,
        vote_total             = COALESCE(vi.vote_total, 0) + v_add_votes,
        updated_at = NOW()
    WHERE vi.id = p_vote_item_id
    RETURNING vi.vote_id INTO v_vote_id;

    IF v_vote_id IS NOT NULL AND (v_add_star <> 0 OR v_add_bonus <> 0 OR v_add_votes <> 0) THEN
        UPDATE public.vote v
        SET star_candy_total       = COALESCE(v.star_candy_total, 0) + v_add_star,
            star_candy_bonus_total = COALESCE(v.star_candy_bonus_total, 0) + v_add_bonus,
            vote_total             = COALESCE(v.vote_total, 0) + v_add_votes,
            updated_at = NOW()
        WHERE v.id = v_vote_id;
    END IF;

    DELETE FROM public.vote_item_update_queue q
    WHERE q.id = ANY (v_ids);

    RETURN v_processed;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."process_vote_item_update_queue"() RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
SELECT public.process_vote_item_update_queue(1000);
$$;

CREATE OR REPLACE FUNCTION "public"."process_vote_item_update_queue"("p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_ids       bigint[];
    v_processed integer := 0;
BEGIN
    SELECT array_agg(id)
    INTO v_ids
    FROM (
             SELECT id
             FROM public.vote_item_update_queue
             ORDER BY id
                 FOR UPDATE SKIP LOCKED
             LIMIT p_limit
         ) q;

    v_processed := COALESCE(array_length(v_ids, 1), 0);

    IF v_processed > 0 THEN
        WITH by_item AS (
            SELECT vote_item_id,
                   SUM(COALESCE(delta_star, 0))  AS add_star,
                   SUM(COALESCE(delta_bonus, 0)) AS add_bonus,
                   SUM(COALESCE(delta_amount, 0)) AS add_votes
            FROM public.vote_item_update_queue
            WHERE id = ANY (v_ids)
            GROUP BY vote_item_id
        ), upd_item AS (
            UPDATE public.vote_item vi
                SET star_candy_total       = COALESCE(vi.star_candy_total, 0) + bi.add_star,
                    star_candy_bonus_total = COALESCE(vi.star_candy_bonus_total, 0) + bi.add_bonus,
                    vote_total             = COALESCE(vi.vote_total, 0) + COALESCE(bi.add_votes, 0),
                    updated_at = NOW()
                FROM by_item bi
                WHERE vi.id = bi.vote_item_id
                RETURNING vi.vote_id, bi.add_star, bi.add_bonus, bi.add_votes
        )
        UPDATE public.vote v
        SET star_candy_total       = COALESCE(v.star_candy_total, 0) + bv.add_star,
            star_candy_bonus_total = COALESCE(v.star_candy_bonus_total, 0) + bv.add_bonus,
            vote_total             = COALESCE(v.vote_total, 0) + COALESCE(bv.add_votes, 0),
            updated_at = NOW()
        FROM (
                 SELECT vote_id,
                        SUM(add_star)  AS add_star,
                        SUM(add_bonus) AS add_bonus,
                        SUM(COALESCE(add_votes, 0)) AS add_votes
                 FROM upd_item
                 GROUP BY vote_id
             ) bv
        WHERE v.id = bv.vote_id;

        DELETE FROM public.vote_item_update_queue q
        WHERE q.id = ANY (v_ids);
    END IF;

    RETURN v_processed;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."recompute_user_bonus"("p_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_total NUMERIC := 0;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN 0;
    END IF;

    SELECT COALESCE(SUM(h.remain_amount), 0)
    INTO v_total
    FROM public.star_candy_bonus_history AS h
    WHERE h.user_id = p_user_id
      AND h.parent_id IS NULL
      AND COALESCE(h.remain_amount, 0) > 0
      AND h.deleted_at IS NULL
      AND (h.expired_dt IS NULL OR h.expired_dt > NOW());

    UPDATE public.user_profiles
    SET star_candy_bonus = v_total,
        updated_at       = NOW()
    WHERE id = p_user_id;

    RETURN v_total;
EXCEPTION
    WHEN OTHERS THEN
        PERFORM public.enqueue_bonus_recalc(p_user_id, 'recompute', SQLERRM);
        RAISE;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."repair_bonus_balance"("p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "old_bonus" numeric, "new_bonus" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_old NUMERIC;
    v_new NUMERIC;
BEGIN
    SELECT star_candy_bonus INTO v_old FROM public.user_profiles WHERE id = p_user_id;
    v_new := public.recompute_user_bonus(p_user_id);

    user_id   := p_user_id;
    old_bonus := v_old;
    new_bonus := v_new;
    RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."repair_bonus_balance_bulk"("p_threshold" numeric DEFAULT 1, "p_limit" integer DEFAULT 500) RETURNS TABLE("queued_user_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN
        SELECT user_id
        FROM public.list_bonus_drift(
                COALESCE(p_threshold, 1),
                1,
                COALESCE(p_limit, 500)
             )
        LOOP
            PERFORM public.enqueue_bonus_recalc(
                    rec.user_id,
                    'bulk-repair',
                    format('delta>= %s', p_threshold)
                    );

            queued_user_id := rec.user_id;
            RETURN NEXT;
        END LOOP;

    RETURN;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."restore_qna"("qna_id_param" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE qnas
  SET
    deleted_at = NULL,
    updated_at = NOW()
  WHERE
    qna_id = qna_id_param
    AND deleted_at IS NOT NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'QnA not found or not deleted';
  END IF;
END;
$$;

COMMENT ON FUNCTION "public"."restore_qna"("qna_id_param" integer) IS 'Restore a soft-deleted QnA item by clearing deleted_at';

CREATE OR REPLACE FUNCTION "public"."revoke_abuser_bonus"("p_user_id" "uuid", "p_reason" "text", "p_admin_id" "uuid" DEFAULT NULL::"uuid", "p_dry_run" boolean DEFAULT true) RETURNS TABLE("affected_records" bigint, "total_revoked" bigint, "was_dry_run" boolean, "user_nickname" "text", "user_was_banned" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_affected BIGINT;
  v_total BIGINT;
  v_nickname TEXT;
  v_was_banned BOOLEAN;
  v_old_bonus INT;
BEGIN
  SELECT up.nickname, (up.deleted_at IS NOT NULL), COALESCE(up.star_candy_bonus, 0)
  INTO v_nickname, v_was_banned, v_old_bonus
  FROM user_profiles up
  WHERE up.id = p_user_id;

  IF v_nickname IS NULL THEN
    RAISE EXCEPTION '사용자를 찾을 수 없습니다: %', p_user_id;
  END IF;

  SELECT COUNT(*), COALESCE(SUM(h.remain_amount), 0)
  INTO v_affected, v_total
  FROM star_candy_bonus_history h
  WHERE h.user_id = p_user_id
    AND h.type = 'AD'
    AND h.parent_id IS NULL
    AND h.deleted_at IS NULL
    AND h.remain_amount > 0
    AND h.transaction_id IS NULL;

  IF NOT p_dry_run AND v_total > 0 THEN
    SET LOCAL app.skip_sync_bonus = 'true';

    UPDATE star_candy_bonus_history
    SET remain_amount = 0, updated_at = NOW()
    WHERE user_id = p_user_id
      AND type = 'AD'
      AND parent_id IS NULL
      AND deleted_at IS NULL
      AND remain_amount > 0
      AND transaction_id IS NULL;

    PERFORM public.recompute_user_bonus(p_user_id);

    INSERT INTO audit_logs (
      "timestamp", user_id, action_type, action_description,
      resource_type, resource_id, old_values, new_values,
      success, severity, tags, created_at
    ) VALUES (
      NOW(),
      COALESCE(p_admin_id::text, 'system'),
      'ABUSER_BONUS_REVOKE',
      p_reason,
      'user_bonus',
      p_user_id::text,
      jsonb_build_object('bonus_before', v_old_bonus, 'revoked_records', v_affected, 'revoked_amount', v_total)::text,
      jsonb_build_object('bonus_after', v_old_bonus - v_total)::text,
      true,
      'high',
      'abuser,bonus_revoke',
      NOW()
    );
  END IF;

  affected_records := v_affected;
  total_revoked := v_total;
  was_dry_run := p_dry_run;
  user_nickname := v_nickname;
  user_was_banned := v_was_banned;
  RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."rollback_transaction"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
END;
$$;

CREATE OR REPLACE FUNCTION "public"."run_expire_star_candy_bonus_once"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_jobid bigint := NULLIF(current_setting('cron.job_id', true),'')::bigint;
  v_total int := 0;
  v_cnt int;
BEGIN
  LOOP
    SELECT batch_count INTO v_cnt
    FROM public.expire_star_candy_bonus_batch(now());

    EXIT WHEN v_cnt = 0; -- 더 이상 처리할 배치 없음 → 다음 로직으로 이동

    v_total := v_total + v_cnt;

    IF v_total >= 2000 THEN
      RETURN;
    END IF;
  END LOOP;

  IF v_jobid IS NOT NULL THEN
    PERFORM cron.unschedule(v_jobid);
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."search_artists"("search_term" "text" DEFAULT NULL::"text") RETURNS TABLE("id" bigint, "name" "jsonb", "image" "jsonb", "birth_date" "date", "artist_group" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
        SELECT
            a.id,
            a.name,
            a.image,
            a.birth_date,
            jsonb_build_object(
                'id', ag.id,
                'name', ag.name,
                'image', ag.image
            ) as artist_group
        FROM
            artist a
                LEFT JOIN
            artist_group ag ON a.group_id = ag.id
        WHERE
            search_term IS NULL OR
            EXISTS (
                SELECT 1 FROM jsonb_each_text(a.name) AS name_kv
                WHERE name_kv.value ILIKE '%' || search_term || '%'
            ) OR
            EXISTS (
                SELECT 1 FROM jsonb_each_text(ag.name) AS group_name_kv
                WHERE group_name_kv.value ILIKE '%' || search_term || '%'
            );
END;
$$;

