CREATE OR REPLACE FUNCTION "public"."sync_or_enqueue_bonus"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID := COALESCE(NEW.user_id, OLD.user_id);
    v_delta   NUMERIC := 0;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.parent_id IS NULL THEN
            v_delta := COALESCE(NEW.remain_amount, 0);
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        IF COALESCE(NEW.parent_id, OLD.parent_id) IS NULL THEN
            v_delta := COALESCE(NEW.remain_amount, 0) - COALESCE(OLD.remain_amount, 0);
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        IF OLD.parent_id IS NULL THEN
            v_delta := -COALESCE(OLD.remain_amount, 0);
        END IF;
    END IF;

    IF v_delta = 0 THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    RAISE LOG '[sync_or_enqueue_bonus] op=% user=% delta=%', TG_OP, v_user_id, v_delta;

    BEGIN
        UPDATE public.user_profiles
        SET star_candy_bonus = GREATEST(0, COALESCE(star_candy_bonus, 0) + v_delta),
            updated_at       = NOW()
        WHERE id = v_user_id;
        IF NOT FOUND THEN
            RAISE LOG '[sync_or_enqueue_bonus] enqueue missing profile user=%', v_user_id;
            PERFORM public.enqueue_bonus_recalc(v_user_id, 'trigger:missing_profile', 'user profile not found');
        END IF;
        RETURN COALESCE(NEW, OLD);
    EXCEPTION
        WHEN OTHERS THEN
            RAISE LOG '[sync_or_enqueue_bonus] enqueue due to error, user=%, err=%', v_user_id, SQLERRM;
            PERFORM public.enqueue_bonus_recalc(v_user_id, 'trigger:error', SQLERRM);
            RETURN COALESCE(NEW, OLD);
    END;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."sync_or_enqueue_user_bonus"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  uid uuid := coalesce(NEW.user_id, OLD.user_id);
  v_skip text := current_setting('app.skip_sync_bonus', true);
BEGIN
  IF coalesce(v_skip,'0') = '1' THEN
    INSERT INTO public.user_bonus_update_queue(user_id)
    VALUES (uid)
    ON CONFLICT (user_id) DO NOTHING;
    RETURN NULL;
  END IF;

  BEGIN
    UPDATE public.user_profiles up
    SET star_candy_bonus = (
          SELECT coalesce(sum(h.remain_amount), 0)
          FROM public.star_candy_bonus_history h
          WHERE h.user_id = uid
            AND h.remain_amount > 0
            AND h.expired_dt > now()
            AND h.deleted_at IS NULL
        ),
        updated_at = now()
    WHERE up.id = uid;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.user_bonus_update_queue(user_id)
    VALUES (uid)
    ON CONFLICT (user_id) DO NOTHING;
  END;

  RETURN NULL;
END;
$$;

