CREATE OR REPLACE FUNCTION "public"."sync_user_profile_bonus"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  uid uuid := coalesce(NEW.user_id, OLD.user_id);
  v_skip text;
BEGIN
  v_skip := current_setting('app.skip_sync_bonus', true);
  IF coalesce(v_skip, '0') = '1' THEN
    RETURN NULL;
  END IF;

  UPDATE user_profiles up
