        SELECT coalesce(sum(h.remain_amount), 0)
        FROM star_candy_bonus_history h
        WHERE h.user_id = uid
          AND h.remain_amount > 0
          AND h.expired_dt > now()
          AND h.deleted_at IS NULL
      ),
      updated_at = now()
  WHERE up.id = uid;

  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."sync_user_profiles_from_queue"("max_rows" integer DEFAULT 2000) RETURNS TABLE("updated_users" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
BEGIN
  PERFORM set_config('TimeZone','Asia/Seoul',true);

  CREATE TEMP TABLE IF NOT EXISTS tmp_queue(user_id uuid primary key) ON COMMIT DROP;
  TRUNCATE tmp_queue;

  INSERT INTO tmp_queue(user_id)
  SELECT user_id
  FROM public.user_bonus_update_queue
  ORDER BY id
  LIMIT max_rows;

  WITH agg AS (
    SELECT q.user_id,
           COALESCE(SUM(h.remain_amount),0) AS total_remain
    FROM tmp_queue q
    LEFT JOIN public.star_candy_bonus_history h
      ON h.user_id = q.user_id
     AND h.remain_amount > 0
     AND h.expired_dt > now()
     AND h.deleted_at IS NULL
    GROUP BY q.user_id
  )
  UPDATE public.user_profiles up
  SET star_candy_bonus = agg.total_remain,
      updated_at = now()
  FROM agg
  WHERE up.id = agg.user_id;

  DELETE FROM public.user_bonus_update_queue q
  USING tmp_queue t
  WHERE q.user_id = t.user_id;

  RETURN QUERY SELECT COUNT(*)::integer FROM tmp_queue;
END;
$$;

