CREATE OR REPLACE FUNCTION "public"."sync_vote_area_arrays"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.areas IS NOT NULL AND array_length(NEW.areas, 1) > 0 THEN
        NEW.area := NEW.areas[1];
    ELSIF NEW.area IS NOT NULL AND (NEW.areas IS NULL OR array_length(NEW.areas, 1) IS NULL) THEN
        NEW.areas := ARRAY[NEW.area];
    ELSIF NEW.area IS NULL AND (NEW.areas IS NULL OR array_length(NEW.areas, 1) IS NULL) THEN
        NEW.area := 'all';
        NEW.areas := ARRAY['all'];
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."test_expire_star_candy_bonus"("test_datetime" timestamp with time zone) RETURNS TABLE("operation" "text", "details" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    expire_result RECORD;
    log_entry RECORD;
    batch_log_entry RECORD;
    test_start_time TIMESTAMP WITH TIME ZONE;
    test_end_time TIMESTAMP WITH TIME ZONE;
    test_batch_id INTEGER;
    test_details JSONB;
    execution_error TEXT;
BEGIN
    test_start_time := NOW();

    BEGIN
        INSERT INTO batch_log (batch_name, start_time, status, details)
        VALUES ('test_expire_star_candy_bonus', test_start_time, 'STARTED', jsonb_build_object('test_datetime', test_datetime))
        RETURNING id INTO test_batch_id;

        DELETE FROM bonus_expiry_log;

        SELECT * INTO expire_result FROM expire_star_candy_bonus(test_datetime);

        RAISE EXCEPTION 'Intentional rollback for testing';
    EXCEPTION
        WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS execution_error = PG_EXCEPTION_CONTEXT;

            IF SQLERRM != 'Intentional rollback for testing' THEN
                INSERT INTO bonus_expiry_log (operation, details)
                VALUES ('Test Function Error', jsonb_build_object('error_message', SQLERRM, 'error_context', execution_error));
            END IF;

            ROLLBACK;
    END;

    test_details := jsonb_build_object(
            'expired_count', COALESCE(expire_result.expired_count, 0),
            'expired_amount', COALESCE(expire_result.expired_amount, 0),
            'affected_users', COALESCE(expire_result.affected_users, 0),
            'duration', EXTRACT(EPOCH FROM (NOW() - test_start_time)),
            'is_test', true,
            'execution_error', execution_error
                    );

    test_end_time := NOW();
    UPDATE batch_log bl
    SET end_time = test_end_time,
        status = CASE WHEN execution_error IS NULL THEN 'COMPLETED' ELSE 'ERROR' END,
        details = bl.details || test_details
    WHERE id = test_batch_id;

    IF expire_result IS NOT NULL THEN
        operation := 'Expire Function Result';
        details := jsonb_build_object(
                'expired_count', expire_result.expired_count,
                'expired_amount', expire_result.expired_amount,
                'affected_users', expire_result.affected_users
                   );
        RETURN NEXT;
    ELSE
        operation := 'Expire Function Result';
        details := jsonb_build_object('message', 'No results available', 'error', execution_error);
        RETURN NEXT;
    END IF;

    FOR log_entry IN SELECT * FROM bonus_expiry_log ORDER BY created_at
        LOOP
            operation := log_entry.operation;
            details := log_entry.details;
            RETURN NEXT;
        END LOOP;

    SELECT * INTO batch_log_entry FROM batch_log WHERE id = test_batch_id;
    operation := 'Test Batch Log';
    details := jsonb_build_object(
            'batch_id', batch_log_entry.id,
            'start_time', batch_log_entry.start_time,
            'end_time', batch_log_entry.end_time,
            'status', batch_log_entry.status,
            'details', batch_log_entry.details
               );
    RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."test_realtime_update"("vote_id_param" integer) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    test_vote_item_id INTEGER;
    result_text TEXT;
BEGIN
    SELECT id INTO test_vote_item_id
    FROM vote_item
    WHERE vote_id = vote_id_param
    LIMIT 1;

    IF test_vote_item_id IS NULL THEN
        RETURN 'Error: No vote_item found for vote_id ' || vote_id_param;
    END IF;

    UPDATE vote_item
    SET updated_at = NOW()
    WHERE id = test_vote_item_id;

    result_text := 'Test realtime update sent for vote_item ' || test_vote_item_id || ' (vote_id: ' || vote_id_param || ')';

    RAISE NOTICE '%', result_text;

    RETURN result_text;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."trg_vote_pick_aggregate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
    if (tg_op = 'DELETE') then
        perform postgres.public.update_vote_item_and_vote_totals(old.vote_item_id);
    elsif (tg_op = 'INSERT') then
        perform postgres.public.update_vote_item_and_vote_totals(new.vote_item_id);
    elsif (tg_op = 'UPDATE') then
        if (old.vote_item_id is distinct from new.vote_item_id) then
            perform postgres.public.update_vote_item_and_vote_totals(old.vote_item_id);
            perform postgres.public.update_vote_item_and_vote_totals(new.vote_item_id);
        else
            perform postgres.public.update_vote_item_and_vote_totals(new.vote_item_id);
        end if;
    end if;
    return null;
end;
$$;

