CREATE OR REPLACE FUNCTION "public"."update_artist_debut_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.debut_yy IS DISTINCT FROM OLD.debut_yy
        OR NEW.debut_mm IS DISTINCT FROM OLD.debut_mm
        OR NEW.debut_dd IS DISTINCT FROM OLD.debut_dd THEN
        UPDATE artist
        SET debut_yy = NEW.debut_yy,
            debut_mm = NEW.debut_mm,
            debut_dd = NEW.debut_dd
        WHERE group_id = NEW.id;
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_birth_date"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.yy IS NOT NULL AND NEW.mm IS NOT NULL AND NEW.dd IS NOT NULL THEN
        BEGIN
            NEW.birth_date := MAKE_DATE(NEW.yy::int, NEW.mm::int, NEW.dd::int);
        EXCEPTION WHEN OTHERS THEN
            NEW.birth_date := NULL;
        END;
    ELSE
        NEW.birth_date := NULL;
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_comment_likes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE comments
        SET likes = likes + 1
        WHERE comment_id = NEW.comment_id;
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
            UPDATE comments
            SET likes = likes - 1
            WHERE comment_id = NEW.comment_id;
        ELSIF NEW.deleted_at IS NULL AND OLD.deleted_at IS NOT NULL THEN
            UPDATE comments
            SET likes = likes + 1
            WHERE comment_id = NEW.comment_id;
        END IF;
    END IF;
    RETURN NEW;
END;$$;

CREATE OR REPLACE FUNCTION "public"."update_comment_replies"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    post_id_var UUID;
    log_details JSONB;
BEGIN
    SELECT post_id INTO post_id_var FROM comments WHERE comment_id = COALESCE(NEW.comment_id, OLD.comment_id);

    log_details := jsonb_build_object(
            'operation', TG_OP,
            'post_id', post_id_var,
            'comment_id', COALESCE(NEW.comment_id, OLD.comment_id)
                   );

    IF TG_OP = 'INSERT' THEN
        log_details := log_details || jsonb_build_object('action', 'Inserting new comment');

        UPDATE posts
        SET reply_count = reply_count + 1
        WHERE post_id = post_id_var;

        log_details := log_details || jsonb_build_object('updated_post_reply_count', true);

        IF NEW.parent_comment_id IS NOT NULL THEN
            UPDATE comments
            SET replies = replies + 1
            WHERE comment_id = NEW.parent_comment_id
              AND deleted_at IS NULL;

            log_details := log_details || jsonb_build_object('updated_parent_comment_replies', true);
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        log_details := log_details || jsonb_build_object('action', 'Updating comment');
        IF (NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL) OR
           (NEW.deleted_at IS NULL AND OLD.deleted_at IS NOT NULL) THEN

            UPDATE posts
            SET reply_count = CASE
                                  WHEN NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN reply_count - 1
                                  WHEN NEW.deleted_at IS NULL AND OLD.deleted_at IS NOT NULL THEN reply_count + 1
                                  ELSE reply_count
                END
            WHERE post_id = post_id_var;

            log_details := log_details || jsonb_build_object('updated_post_reply_count', true);

            IF NEW.parent_comment_id IS NOT NULL THEN
                UPDATE comments
                SET replies = CASE
                                  WHEN NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN replies - 1
                                  WHEN NEW.deleted_at IS NULL AND OLD.deleted_at IS NOT NULL THEN replies + 1
                                  ELSE replies
                    END
                WHERE comment_id = NEW.parent_comment_id
                  AND deleted_at IS NULL;

                log_details := log_details || jsonb_build_object('updated_parent_comment_replies', true);
            END IF;
        ELSE
            log_details := log_details || jsonb_build_object('deleted_at_changed', false);
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        log_details := log_details || jsonb_build_object('action', 'Deleting comment');

        UPDATE posts
        SET reply_count = reply_count - 1
        WHERE post_id = post_id_var;

        log_details := log_details || jsonb_build_object('updated_post_reply_count', true);

        IF OLD.parent_comment_id IS NOT NULL THEN
            UPDATE comments
            SET replies = replies - 1
            WHERE comment_id = OLD.parent_comment_id
              AND deleted_at IS NULL;

            log_details := log_details || jsonb_build_object('updated_parent_comment_replies', true);
        END IF;
    END IF;

    INSERT INTO custom_logs (operation, details) VALUES (TG_OP, log_details);

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_date_components"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.birth_date IS NOT NULL THEN
        NEW.yy := EXTRACT(YEAR FROM NEW.birth_date)::bigint;
        NEW.mm := EXTRACT(MONTH FROM NEW.birth_date)::bigint;
        NEW.dd := EXTRACT(DAY FROM NEW.birth_date)::bigint;
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_last_updated"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.last_updated = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_timestamp"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_total_pic_vote"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE pic_vote_item
    SET vote_total = pic_vote_item.vote_total + NEW.amount
    WHERE id = NEW.vote_item_id;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_total_vote"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE vote_item
    SET vote_total = vote_item.vote_total + NEW.amount
    WHERE id = NEW.vote_item_id;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_vote_item_and_vote_totals"("p_vote_item_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE public.vote_item AS vi
  SET
    vote_total = COALESCE(sub.vote_total, 0),
    star_candy_total = COALESCE(sub.star_candy_total, 0),
    star_candy_bonus_total = COALESCE(sub.star_candy_bonus_total, 0),
    updated_at = NOW()
  FROM (
    SELECT
      COALESCE(SUM(vp.amount), 0)               AS vote_total,
      COALESCE(SUM(vp.star_candy_usage), 0)     AS star_candy_total,
      COALESCE(SUM(vp.star_candy_bonus_usage), 0) AS star_candy_bonus_total
    FROM public.vote_pick vp
    WHERE vp.vote_item_id = p_vote_item_id
  ) sub
  WHERE vi.id = p_vote_item_id;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_vote_item_totals_bak"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE vote_item
    SET
      vote_total = COALESCE((
        SELECT SUM(amount)
        FROM vote_pick
        WHERE vote_item_id = OLD.vote_item_id
      ), 0),
      updated_at = NOW()
    WHERE id = OLD.vote_item_id;

    RETURN OLD;
  ELSE
    UPDATE vote_item
    SET
      vote_total = COALESCE((
        SELECT SUM(amount)
        FROM vote_pick
        WHERE vote_item_id = NEW.vote_item_id
      ), 0),
      updated_at = NOW()
    WHERE id = NEW.vote_item_id;

    RETURN NEW;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_vote_item_usage_columns_bak"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.vote_total != OLD.vote_total AND
       NEW.star_candy_total = 0 AND
       NEW.star_candy_bonus_total = 0 THEN
        NEW.star_candy_total = OLD.star_candy_total + (NEW.vote_total - OLD.vote_total);
        NEW.star_candy_bonus_total = OLD.star_candy_bonus_total;
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_vote_pick_usage_columns_bak"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND
       NEW.star_candy_usage = 0 AND
       NEW.star_candy_bonus_usage = 0 AND
       NEW.amount > 0 THEN
        NEW.star_candy_usage = NEW.amount;
        NEW.star_candy_bonus_usage = 0;
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_vote_totals_batch_bak"("p_vote_ids" integer[]) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
begin
    update vote_item vi
    set
        vote_total = coalesce(agg.total_votes, 0),
        star_candy_total = coalesce(agg.star_candy_sum, 0),
        star_candy_bonus_total = coalesce(agg.bonus_sum, 0)
    from (
             select
                 vote_item_id,
                 sum(coalesce(star_candy_usage, 0) + coalesce(star_candy_bonus_usage, 0)) as total_votes,
                 sum(coalesce(star_candy_usage, 0)) as star_candy_sum,
                 sum(coalesce(star_candy_bonus_usage, 0)) as bonus_sum
             from vote_pick
             where deleted_at is null
               and vote_id = any(p_vote_ids)
             group by vote_item_id
         ) agg
    where vi.id = agg.vote_item_id
      and vi.vote_id = any(p_vote_ids);

    update vote v
    set
        vote_total = coalesce(agg2.total_votes, 0),
        star_candy_total = coalesce(agg2.star_candy_sum, 0),
        star_candy_bonus_total = coalesce(agg2.bonus_sum, 0)
    from (
             select
                 vote_id,
                 sum(coalesce(vote_total, 0)) as total_votes,
                 sum(coalesce(star_candy_total, 0)) as star_candy_sum,
                 sum(coalesce(star_candy_bonus_total, 0)) as bonus_sum
             from vote_item
             where vote_id = any(p_vote_ids)
             group by vote_id
         ) agg2
    where v.id = agg2.vote_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."upsert_ad_bonus"("p_user_id" "uuid", "p_amount" integer, "p_transaction_id" "text", "p_expired_dt" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_existing_id BIGINT;
  v_today_start TIMESTAMPTZ;
  v_daily_total INT;
  v_minute_total INT;
  v_one_minute_ago TIMESTAMPTZ;
  v_is_deleted BOOLEAN;
BEGIN
  IF p_amount > 1000 THEN
    RAISE EXCEPTION 'reward amount exceeds maximum allowed value: %', p_amount;
  END IF;

  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'reward amount must be positive: %', p_amount;
  END IF;

  SELECT (deleted_at IS NOT NULL) INTO v_is_deleted
  FROM user_profiles
  WHERE id = p_user_id;

  IF v_is_deleted IS NULL THEN
    RAISE EXCEPTION 'user not found: %', p_user_id;
  END IF;

  IF v_is_deleted THEN
    RAISE EXCEPTION 'user account is deactivated: %', p_user_id;
  END IF;

  v_one_minute_ago := NOW() - INTERVAL '1 minute';

  SELECT (
    (SELECT COUNT(*) FROM transaction_admob
     WHERE user_id = p_user_id AND created_at >= v_one_minute_ago) +
    (SELECT COUNT(*) FROM transaction_pangle
     WHERE user_id = p_user_id AND created_at >= v_one_minute_ago) +
    (SELECT COUNT(*) FROM transaction_tapjoy
     WHERE user_id = p_user_id AND created_at >= v_one_minute_ago) +
    (SELECT COUNT(*) FROM transaction_pincrux
     WHERE usr_key = p_user_id::text AND created_at >= v_one_minute_ago)
  ) INTO v_minute_total;

  IF v_minute_total >= 3 THEN
    RAISE EXCEPTION 'per-minute ad reward rate limit exceeded for user %', p_user_id;
  END IF;

  v_today_start := date_trunc('day', NOW() AT TIME ZONE 'Asia/Seoul')
                    AT TIME ZONE 'Asia/Seoul';

  SELECT (
    (SELECT COUNT(*) FROM transaction_admob
     WHERE user_id = p_user_id AND created_at >= v_today_start) +
    (SELECT COUNT(*) FROM transaction_pangle
     WHERE user_id = p_user_id AND created_at >= v_today_start) +
    (SELECT COUNT(*) FROM transaction_tapjoy
     WHERE user_id = p_user_id AND created_at >= v_today_start) +
    (SELECT COUNT(*) FROM transaction_pincrux
     WHERE usr_key = p_user_id::text AND created_at >= v_today_start)
  ) INTO v_daily_total;

  IF v_daily_total >= 120 THEN
    RAISE EXCEPTION 'daily ad reward limit exceeded for user %', p_user_id;
  END IF;

  SELECT id INTO v_existing_id
  FROM star_candy_bonus_history
  WHERE user_id = p_user_id
    AND parent_id IS NULL
    AND deleted_at IS NULL
    AND type = 'AD'
    AND remain_amount = amount
    AND (
      (expired_dt IS NULL AND p_expired_dt IS NULL)
      OR expired_dt = p_expired_dt
    )
    AND created_at >= v_today_start
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_id IS NOT NULL THEN
    UPDATE star_candy_bonus_history
    SET amount = amount + p_amount,
        remain_amount = remain_amount + p_amount,
        updated_at = NOW()
    WHERE id = v_existing_id;
  ELSE
    INSERT INTO star_candy_bonus_history
      (type, amount, remain_amount, user_id, transaction_id, expired_dt)
    VALUES
      ('AD', p_amount, p_amount, p_user_id, p_transaction_id, p_expired_dt);
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."upsert_user_push_token"("p_user_id" "uuid", "p_platform" "text", "p_token" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF p_platform NOT IN ('ios','android','web','macos','windows') THEN
    RAISE EXCEPTION 'Unsupported platform: %', p_platform USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.user_push_tokens (user_id, token_ios, token_android, token_web, token_macos, token_windows)
  VALUES (
    p_user_id,
    CASE WHEN p_platform = 'ios' THEN p_token ELSE NULL END,
    CASE WHEN p_platform = 'android' THEN p_token ELSE NULL END,
    CASE WHEN p_platform = 'web' THEN p_token ELSE NULL END,
    CASE WHEN p_platform = 'macos' THEN p_token ELSE NULL END,
    CASE WHEN p_platform = 'windows' THEN p_token ELSE NULL END
  )
  ON CONFLICT (user_id) DO UPDATE SET
    token_ios = CASE WHEN EXCLUDED.token_ios IS NOT NULL THEN EXCLUDED.token_ios ELSE user_push_tokens.token_ios END,
    token_android = CASE WHEN EXCLUDED.token_android IS NOT NULL THEN EXCLUDED.token_android ELSE user_push_tokens.token_android END,
    token_web = CASE WHEN EXCLUDED.token_web IS NOT NULL THEN EXCLUDED.token_web ELSE user_push_tokens.token_web END,
    token_macos = CASE WHEN EXCLUDED.token_macos IS NOT NULL THEN EXCLUDED.token_macos ELSE user_push_tokens.token_macos END,
    token_windows = CASE WHEN EXCLUDED.token_windows IS NOT NULL THEN EXCLUDED.token_windows ELSE user_push_tokens.token_windows END,
    updated_at = NOW();
END;
$$;

CREATE OR REPLACE FUNCTION "public"."upsert_user_push_token"("p_user_id" "uuid", "p_platform" "text", "p_token" "text", "p_device_locale" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
  DECLARE
    v_column_name TEXT;
  BEGIN
    v_column_name := 'token_' || p_platform;

    INSERT INTO user_push_tokens (user_id, device_locale)
    VALUES (p_user_id, p_device_locale)
    ON CONFLICT (user_id) DO UPDATE
    SET
      device_locale = COALESCE(EXCLUDED.device_locale, user_push_tokens.device_locale),
      updated_at = NOW();

    EXECUTE format(
      'UPDATE user_push_tokens SET %I = $1, updated_at = NOW() WHERE user_id = $2',
      v_column_name
    ) USING p_token, p_user_id;
  END;
  $_$;

CREATE OR REPLACE FUNCTION "public"."use_star_candy_bonus"("p_user_id" "uuid", "p_amount" integer) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
declare
    remaining integer := p_amount;
    used integer := 0;
    r record;
    to_use integer;
begin
    for r in
        select id, remain_amount
        from star_candy_bonus_history
        where user_id = p_user_id
          and remain_amount > 0
          and expired_dt > now() at time zone 'Asia/Seoul'
          and deleted_at is null
        order by expired_dt asc, created_at asc
    loop
        exit when remaining <= 0;

        to_use := least(remaining, r.remain_amount);

        update star_candy_bonus_history
        set remain_amount = remain_amount - to_use,
            updated_at = now()
        where id = r.id;

        remaining := remaining - to_use;
        used := used + to_use;
    end loop;

    if used < p_amount then
        raise exception 'Insufficient bonus star candy: requested %, used %, missing %',
            p_amount, used, p_amount - used;
    end if;

    insert into star_candy_bonus_history (
        user_id, amount, remain_amount, type,
        parent_id, vote_pick_id, created_at, expired_dt
    ) values (
        p_user_id, used, 0, 'VOTE',
        null, null, now(), null
    );

    return used;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."use_star_candy_bonus"("p_user_id" "uuid", "p_amount" integer, "p_vote_pick_id" integer) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
declare
    remaining integer := p_amount;
    used integer := 0;
    r record;
    to_use integer;
begin

    for r in
        select id, remain_amount
        from star_candy_bonus_history
        where user_id = p_user_id
          and remain_amount > 0
          and expired_dt > now() at time zone 'Asia/Seoul'
          and deleted_at is null
        order by expired_dt asc, created_at asc
        for update skip locked
    loop
        exit when remaining <= 0;

        to_use := least(remaining, r.remain_amount);

        if to_use > r.remain_amount then
          raise exception 'Concurrent update detected: row remain_amount < to_use';
        end if;

        update star_candy_bonus_history
        set remain_amount = remain_amount - to_use,
            updated_at = now()
        where id = r.id;

        remaining := remaining - to_use;
        used := used + to_use;
    end loop;

    if used < p_amount then
        raise exception 'Insufficient bonus star candy: requested %, used %, missing %',
            p_amount, used, p_amount - used
            using errcode = 'P0001';  -- user-defined exception
    end if;

    insert into star_candy_bonus_history (
        user_id, amount, remain_amount, type,
        parent_id, vote_pick_id, created_at, expired_dt
    ) values (
        p_user_id, used, 0, 'VOTE',
        null, p_vote_pick_id, now(), null
    );

    return used;
end;
$$;

