    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE "public"."activities_id_seq" OWNED BY "public"."activities"."id";

CREATE TABLE IF NOT EXISTS "public"."ad_campaigns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "advertiser" "text",
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "visible_from" timestamp with time zone,
    "visible_to" timestamp with time zone,
    "weight" integer DEFAULT 1 NOT NULL,
    "total_cap" bigint,
    "served_count" bigint DEFAULT 0 NOT NULL,
    "video_key" "text" NOT NULL,
    "cta_url" "text",
    "reward_view" integer DEFAULT 0 NOT NULL,
    "reward_more" integer DEFAULT 0 NOT NULL,
    "reward_like" integer DEFAULT 0 NOT NULL,
    "reward_subscribe" integer DEFAULT 0 NOT NULL,
    "reward_comment" integer DEFAULT 0 NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "ad_campaigns_status_chk" CHECK (("status" = ANY (ARRAY['ACTIVE'::"text", 'PAUSED'::"text"])))
);

CREATE OR REPLACE VIEW "public"."ad_campaigns_active" AS
 SELECT "ad_campaigns"."id",
    "ad_campaigns"."title",
    "ad_campaigns"."advertiser",
    "ad_campaigns"."status",
    "ad_campaigns"."visible_from",
    "ad_campaigns"."visible_to",
    "ad_campaigns"."weight",
    "ad_campaigns"."total_cap",
    "ad_campaigns"."served_count",
    "ad_campaigns"."video_key",
    "ad_campaigns"."cta_url",
    "ad_campaigns"."reward_view",
    "ad_campaigns"."reward_more",
    "ad_campaigns"."reward_like",
    "ad_campaigns"."reward_subscribe",
    "ad_campaigns"."reward_comment",
    "ad_campaigns"."is_default",
    "ad_campaigns"."created_at",
    "ad_campaigns"."updated_at"
   FROM "public"."ad_campaigns"
  WHERE (("ad_campaigns"."status" = 'ACTIVE'::"text") AND (("ad_campaigns"."visible_from" IS NULL) OR ("ad_campaigns"."visible_from" <= "now"())) AND (("ad_campaigns"."visible_to" IS NULL) OR ("ad_campaigns"."visible_to" >= "now"())) AND (("ad_campaigns"."total_cap" IS NULL) OR ("ad_campaigns"."served_count" < "ad_campaigns"."total_cap")));

