CREATE TABLE IF NOT EXISTS "public"."vote_item_request_users" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "vote_item_request_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "artist_id" integer DEFAULT 0 NOT NULL,
    "vote_id" integer DEFAULT 0 NOT NULL,
    "status" character varying(50) DEFAULT 'pending'::character varying NOT NULL,
    CONSTRAINT "vote_item_request_users_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'in-progress'::character varying, 'cancelled'::character varying])::"text"[])))
);

CREATE OR REPLACE VIEW "public"."artist_request_statistics" AS
 SELECT "a"."id" AS "artist_id",
    ("a"."name" ->> 'ko'::"text") AS "artist_name",
    ("ag"."name" ->> 'ko'::"text") AS "artist_group",
    "a"."image" AS "artist_image",
    "count"(*) AS "total_requests",
    "count"(
        CASE
            WHEN (("viru"."status")::"text" = 'pending'::"text") THEN 1
            ELSE NULL::integer
        END) AS "pending_requests",
    "count"(
        CASE
            WHEN (("viru"."status")::"text" = 'approved'::"text") THEN 1
            ELSE NULL::integer
        END) AS "approved_requests",
    "count"(
        CASE
            WHEN (("viru"."status")::"text" = 'rejected'::"text") THEN 1
            ELSE NULL::integer
        END) AS "rejected_requests",
    "min"("viru"."created_at") AS "first_request_at",
    "max"("viru"."updated_at") AS "last_updated_at"
   FROM (("public"."vote_item_request_users" "viru"
     JOIN "public"."artist" "a" ON (("viru"."artist_id" = "a"."id")))
     LEFT JOIN "public"."artist_group" "ag" ON (("a"."group_id" = "ag"."id")))
  GROUP BY "a"."id", ("a"."name" ->> 'ko'::"text"), ("ag"."name" ->> 'ko'::"text"), "a"."image"
  ORDER BY ("count"(*)) DESC;

