CREATE TABLE IF NOT EXISTS "public"."audit_logs" (
    "id_old" "text" NOT NULL,
    "timestamp" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "text",
    "user_email" "text",
    "user_roles" "text",
    "session_id" "text",
    "action_type" "text" NOT NULL,
    "action_description" "text" NOT NULL,
    "resource_type" "text" NOT NULL,
    "resource_id" "text",
    "resource_name" "text",
    "old_values" "text",
    "new_values" "text",
    "changed_fields" "text",
    "ip_address" "text",
    "user_agent" "text",
    "url" "text",
    "method" "text",
    "success" boolean DEFAULT true NOT NULL,
    "error_message" "text",
    "status_code" integer,
    "metadata" "text",
    "tags" "text",
    "severity" "text" NOT NULL,
    "retention_period" integer,
    "classification" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rid" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    CONSTRAINT "audit_logs_classification_check" CHECK (("classification" = ANY (ARRAY['public'::"text", 'internal'::"text", 'confidential'::"text", 'restricted'::"text"]))),
    CONSTRAINT "audit_logs_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"])))
);

COMMENT ON TABLE "public"."audit_logs" IS '사용자 액션 감사 로그 테이블';

COMMENT ON COLUMN "public"."audit_logs"."id_old" IS '고유 감사 로그 ID';

COMMENT ON COLUMN "public"."audit_logs"."timestamp" IS '액션 발생 시간';

COMMENT ON COLUMN "public"."audit_logs"."user_id" IS '액션을 수행한 사용자 ID';

COMMENT ON COLUMN "public"."audit_logs"."action_type" IS '수행된 액션 타입';

COMMENT ON COLUMN "public"."audit_logs"."resource_type" IS '액션 대상 리소스 타입';

COMMENT ON COLUMN "public"."audit_logs"."old_values" IS '변경 전 값 (JSON, 민감 정보 마스킹됨)';

COMMENT ON COLUMN "public"."audit_logs"."new_values" IS '변경 후 값 (JSON, 민감 정보 마스킹됨)';

COMMENT ON COLUMN "public"."audit_logs"."metadata" IS '추가 메타데이터 (JSON)';

COMMENT ON COLUMN "public"."audit_logs"."severity" IS '액션의 심각도 (low, medium, high, critical)';

COMMENT ON COLUMN "public"."audit_logs"."retention_period" IS '로그 보존 기간 (일 단위)';

COMMENT ON COLUMN "public"."audit_logs"."classification" IS '데이터 분류 (public, internal, confidential, restricted)';

COMMENT ON COLUMN "public"."audit_logs"."id" IS 'UUID PK (converted from integer id_old)';

CREATE OR REPLACE VIEW "public"."audit_log_stats" AS
 SELECT "date"("audit_logs"."timestamp") AS "log_date",
    "audit_logs"."action_type",
    "audit_logs"."resource_type",
    "audit_logs"."severity",
    "audit_logs"."success",
    "count"(*) AS "log_count",
    "count"(DISTINCT "audit_logs"."user_id") AS "unique_users"
   FROM "public"."audit_logs"
  WHERE ("audit_logs"."timestamp" >= ("now"() - '30 days'::interval))
  GROUP BY ("date"("audit_logs"."timestamp")), "audit_logs"."action_type", "audit_logs"."resource_type", "audit_logs"."severity", "audit_logs"."success"
  ORDER BY ("date"("audit_logs"."timestamp")) DESC, ("count"(*)) DESC;

