    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    "user_id" "uuid",
    "product_id" "text",
    "environment" "text",
    "verification_data" "jsonb",
    "receipt_hash" "text",
    "tx_key" "text" GENERATED ALWAYS AS (COALESCE((((("verification_data" -> 'receipt'::"text") -> 'in_app'::"text") -> ("jsonb_array_length"((("verification_data" -> 'receipt'::"text") -> 'in_app'::"text")) - 1)) ->> 'transaction_id'::"text"), (("verification_data" -> 'jwt_payload'::"text") ->> 'transactionId'::"text"), (("verification_data" -> 'jwt_payload'::"text") ->> 'originalTransactionId'::"text"), ((("verification_data" -> 'latest_receipt_info'::"text") -> ("jsonb_array_length"(("verification_data" -> 'latest_receipt_info'::"text")) - 1)) ->> 'transaction_id'::"text"))) STORED
);

COMMENT ON TABLE "public"."receipts" IS 'Stores purchase receipt verification results with hash-based deduplication';

COMMENT ON COLUMN "public"."receipts"."receipt_hash" IS 'MD5 hash of receipt_data for efficient duplicate detection';

