CREATE OR REPLACE VIEW "public"."security_events_summary" AS
 SELECT "date"("audit_logs"."timestamp") AS "event_date",
    "audit_logs"."action_type",
    "audit_logs"."severity",
    "count"(*) AS "event_count",
    "count"(DISTINCT "audit_logs"."user_id") AS "affected_users",
    "count"(DISTINCT "audit_logs"."ip_address") AS "unique_ips"
   FROM "public"."audit_logs"
  WHERE (("audit_logs"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])) OR (("audit_logs"."action_type" = ANY (ARRAY['login_failed'::"text", 'security_violation'::"text", 'suspicious_activity'::"text", 'access_denied'::"text"])) AND ("audit_logs"."timestamp" >= ("now"() - '7 days'::interval))))
  GROUP BY ("date"("audit_logs"."timestamp")), "audit_logs"."action_type", "audit_logs"."severity"
  ORDER BY ("date"("audit_logs"."timestamp")) DESC, ("count"(*)) DESC;

