CREATE OR REPLACE VIEW "public"."user_activity_summary" AS
 SELECT "audit_logs"."user_id",
    "audit_logs"."user_email",
    "date"("audit_logs"."timestamp") AS "activity_date",
    "count"(*) AS "total_actions",
    "count"(
        CASE
            WHEN ("audit_logs"."success" = false) THEN 1
            ELSE NULL::integer
        END) AS "failed_actions",
    "count"(DISTINCT "audit_logs"."action_type") AS "unique_action_types",
    "min"("audit_logs"."timestamp") AS "first_activity",
    "max"("audit_logs"."timestamp") AS "last_activity"
   FROM "public"."audit_logs"
  WHERE (("audit_logs"."user_id" IS NOT NULL) AND ("audit_logs"."timestamp" >= ("now"() - '7 days'::interval)))
  GROUP BY "audit_logs"."user_id", "audit_logs"."user_email", ("date"("audit_logs"."timestamp"))
  ORDER BY ("date"("audit_logs"."timestamp")) DESC, ("count"(*)) DESC;

