    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "role_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE OR REPLACE VIEW "public"."user_vote_item_request_history" AS
 SELECT "viru"."user_id",
    "viru"."vote_id",
    "viru"."status" AS "request_status",
    "a"."id" AS "artist_id",
    ("a"."name" ->> 'ko'::"text") AS "artist_name",
    ("ag"."name" ->> 'ko'::"text") AS "artist_group",
    "a"."image" AS "artist_image",
    "viru"."created_at" AS "requested_at",
    "viru"."updated_at" AS "status_updated_at",
        CASE
            WHEN (("viru"."status")::"text" = 'pending'::"text") THEN '요청 대기중'::"text"
            WHEN (("viru"."status")::"text" = 'approved'::"text") THEN '요청 승인됨'::"text"
            WHEN (("viru"."status")::"text" = 'rejected'::"text") THEN '요청 거절됨'::"text"
            WHEN (("viru"."status")::"text" = 'in-progress'::"text") THEN '요청 진행중'::"text"
            WHEN (("viru"."status")::"text" = 'cancelled'::"text") THEN '요청 취소됨'::"text"
            ELSE '요청 상태 알 수 없음'::"text"
        END AS "request_status_text"
   FROM (("public"."vote_item_request_users" "viru"
     JOIN "public"."artist" "a" ON (("viru"."artist_id" = "a"."id")))
     LEFT JOIN "public"."artist_group" "ag" ON (("a"."group_id" = "ag"."id")))
  ORDER BY "viru"."created_at" DESC;

CREATE TABLE IF NOT EXISTS "public"."version" (
    "id" integer NOT NULL,
    "created_at" timestamp with time zone DEFAULT ('now'::"text")::timestamp(6) with time zone NOT NULL,
    "updated_at" timestamp with time zone DEFAULT ('now'::"text")::timestamp(6) with time zone NOT NULL,
    "deleted_at" timestamp with time zone,
    "ios" "json",
    "android" "json",
    "macos" "json",
    "windows" "json",
    "linux" "json",
    "apk" "json"
);

CREATE SEQUENCE IF NOT EXISTS "public"."version_id_seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE "public"."version_id_seq" OWNED BY "public"."version"."id";

