CREATE OR REPLACE VIEW "public"."view_transaction_all" AS
 SELECT "vta"."ad_network",
    ("vta"."commission")::numeric AS "commission",
    "vta"."created_at",
    "vta"."platform",
    ("vta"."reward_amount")::numeric AS "reward_amount",
    "vta"."reward_name",
    "vta"."reward_type",
    "vta"."source",
    "vta"."transaction_id",
    ("vta"."user_id")::"text" AS "user_id",
    NULL::"text" AS "ad_campaign_id"
   FROM "public"."view_transaction_all_base" "vta"
UNION ALL
 SELECT COALESCE("ac"."title", ("ti"."ad_campaign_id")::"text") AS "ad_network",
    NULL::numeric AS "commission",
    "ti"."created_at",
    "ti"."platform",
    "ti"."reward_amount",
    "ti"."action" AS "reward_name",
    COALESCE("ti"."reward_type", "ti"."action") AS "reward_type",
    'internal'::"text" AS "source",
    ("ti"."id")::"text" AS "transaction_id",
    ("ti"."user_id")::"text" AS "user_id",
    ("ti"."ad_campaign_id")::"text" AS "ad_campaign_id"
   FROM ("public"."transaction_internal" "ti"
     LEFT JOIN "public"."ad_campaigns" "ac" ON (("ac"."id" = "ti"."ad_campaign_id")));

COMMENT ON VIEW "public"."view_transaction_all" IS 'Unified ad transaction view including internal actions (wrapped over original base).';

CREATE TABLE IF NOT EXISTS "public"."vote" (
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
