    "wait_image" character varying(255),
    "result_image" character varying(255),
    "vote_content" character varying(255),
    "start_at" timestamp with time zone,
    "stop_at" timestamp with time zone,
    "visible_at" timestamp with time zone,
    "id" integer NOT NULL,
    "title" "jsonb",
    "order" integer,
    "vote_sub_category" "text",
    "area" "text" NOT NULL,
    "is_partnership" boolean DEFAULT false,
    "partner" "text",
    "vote_total" integer DEFAULT 0,
    "star_candy_total" integer DEFAULT 0,
    "star_candy_bonus_total" integer DEFAULT 0,
