COMMENT ON COLUMN "public"."vote_pick"."star_candy_bonus_usage" IS '보너스 star_candy 사용량';

CREATE OR REPLACE VIEW "public"."view_user_activity_unified" AS
 WITH "star_hist_agg" AS (
         SELECT "star_candy_history"."user_id",
            COALESCE("star_candy_history"."transaction_id", ''::"text") AS "txn_text",
            ("sum"(
                CASE
                    WHEN ("star_candy_history"."amount" > 0) THEN "star_candy_history"."amount"
                    ELSE 0
                END))::numeric AS "sum_amount"
           FROM "public"."star_candy_history"
          GROUP BY "star_candy_history"."user_id", COALESCE("star_candy_history"."transaction_id", ''::"text")
        ), "bonus_hist_agg" AS (
         SELECT "star_candy_bonus_history"."user_id",
            COALESCE("star_candy_bonus_history"."transaction_id", ''::"text") AS "txn_text",
            ("sum"(
                CASE
                    WHEN ("star_candy_bonus_history"."amount" > 0) THEN "star_candy_bonus_history"."amount"
                    ELSE 0
                END))::numeric AS "sum_amount"
           FROM "public"."star_candy_bonus_history"
          GROUP BY "star_candy_bonus_history"."user_id", COALESCE("star_candy_bonus_history"."transaction_id", ''::"text")
        )
 SELECT ('STAR:'::"text" || ("sch"."id")::"text") AS "unified_id",
    'STAR'::"text" AS "source",
    "sch"."created_at",
    "sch"."user_id",
    ("sch"."amount")::numeric AS "amount",
    ("sch"."type")::"text" AS "subtype",
    NULL::numeric AS "remain_amount",
    NULL::timestamp with time zone AS "expired_dt",
    "sch"."transaction_id",
    ("sch"."vote_pick_id")::bigint AS "vote_pick_id",
    NULL::"jsonb" AS "vote_title",
    NULL::"jsonb" AS "vote_item_title",
    NULL::"jsonb" AS "vote_item_name",
    NULL::"jsonb" AS "artist_name",
    NULL::"text" AS "receipt_platform",
    NULL::"text" AS "receipt_product_id",
    NULL::"text" AS "receipt_status",
    NULL::"text" AS "receipt_environment",
    NULL::"text" AS "ad_source",
    NULL::"text" AS "ad_network",
    NULL::"text" AS "ad_reward_name",
    NULL::numeric AS "star_gain",
    NULL::numeric AS "bonus_gain"
   FROM "public"."star_candy_history" "sch"
UNION ALL
 SELECT ('BONUS:'::"text" || ("sbh"."id")::"text") AS "unified_id",
    'BONUS'::"text" AS "source",
    "sbh"."created_at",
    "sbh"."user_id",
    ("sbh"."amount")::numeric AS "amount",
    "sbh"."type" AS "subtype",
    ("sbh"."remain_amount")::numeric AS "remain_amount",
    "sbh"."expired_dt",
    "sbh"."transaction_id",
    ("sbh"."vote_pick_id")::bigint AS "vote_pick_id",
    NULL::"jsonb" AS "vote_title",
    NULL::"jsonb" AS "vote_item_title",
    NULL::"jsonb" AS "vote_item_name",
    NULL::"jsonb" AS "artist_name",
    NULL::"text" AS "receipt_platform",
    NULL::"text" AS "receipt_product_id",
    NULL::"text" AS "receipt_status",
    NULL::"text" AS "receipt_environment",
    NULL::"text" AS "ad_source",
    NULL::"text" AS "ad_network",
    NULL::"text" AS "ad_reward_name",
    NULL::numeric AS "star_gain",
    NULL::numeric AS "bonus_gain"
   FROM "public"."star_candy_bonus_history" "sbh"
UNION ALL
 SELECT ('RECEIPT:'::"text" || ("r"."id")::"text") AS "unified_id",
    'RECEIPT'::"text" AS "source",
    "r"."created_at",
    "r"."user_id",
    NULL::numeric AS "amount",
    NULL::"text" AS "subtype",
    NULL::numeric AS "remain_amount",
    NULL::timestamp with time zone AS "expired_dt",
    NULL::"text" AS "transaction_id",
    NULL::bigint AS "vote_pick_id",
    NULL::"jsonb" AS "vote_title",
    NULL::"jsonb" AS "vote_item_title",
    NULL::"jsonb" AS "vote_item_name",
    NULL::"jsonb" AS "artist_name",
    "r"."platform" AS "receipt_platform",
    "r"."product_id" AS "receipt_product_id",
    "r"."status" AS "receipt_status",
    "r"."environment" AS "receipt_environment",
    NULL::"text" AS "ad_source",
    NULL::"text" AS "ad_network",
    NULL::"text" AS "ad_reward_name",
    (COALESCE("s_txn_id"."sum_amount", (0)::numeric) + COALESCE("s_hash"."sum_amount", (0)::numeric)) AS "star_gain",
    (COALESCE("b_txn_id"."sum_amount", (0)::numeric) + COALESCE("b_hash"."sum_amount", (0)::numeric)) AS "bonus_gain"
   FROM (((("public"."receipts" "r"
     LEFT JOIN "star_hist_agg" "s_txn_id" ON ((("s_txn_id"."txn_text" = ("r"."id")::"text") AND (("s_txn_id"."user_id" = "r"."user_id") OR ("r"."user_id" IS NULL)))))
     LEFT JOIN "star_hist_agg" "s_hash" ON ((("r"."receipt_hash" IS NOT NULL) AND ("s_hash"."txn_text" = "r"."receipt_hash") AND (("s_hash"."user_id" = "r"."user_id") OR ("r"."user_id" IS NULL)))))
     LEFT JOIN "bonus_hist_agg" "b_txn_id" ON ((("b_txn_id"."txn_text" = ("r"."id")::"text") AND (("b_txn_id"."user_id" = "r"."user_id") OR ("r"."user_id" IS NULL)))))
     LEFT JOIN "bonus_hist_agg" "b_hash" ON ((("r"."receipt_hash" IS NOT NULL) AND ("b_hash"."txn_text" = "r"."receipt_hash") AND (("b_hash"."user_id" = "r"."user_id") OR ("r"."user_id" IS NULL)))))
UNION ALL
 SELECT ('AD:'::"text" || COALESCE("vta"."transaction_id", ''::"text")) AS "unified_id",
    'AD'::"text" AS "source",
    "vta"."created_at",
    "vta"."user_id",
    ("vta"."reward_amount")::numeric AS "amount",
    "vta"."reward_type" AS "subtype",
    NULL::numeric AS "remain_amount",
    NULL::timestamp with time zone AS "expired_dt",
    "vta"."transaction_id",
    NULL::bigint AS "vote_pick_id",
    NULL::"jsonb" AS "vote_title",
    NULL::"jsonb" AS "vote_item_title",
    NULL::"jsonb" AS "vote_item_name",
    NULL::"jsonb" AS "artist_name",
    "vta"."platform" AS "receipt_platform",
    NULL::"text" AS "receipt_product_id",
    NULL::"text" AS "receipt_status",
    NULL::"text" AS "receipt_environment",
    "vta"."source" AS "ad_source",
        CASE
            WHEN ("vta"."source" = 'admob'::"text") THEN 'admob'::"text"
            WHEN ("vta"."source" = 'applovin'::"text") THEN 'applovin'::"text"
            WHEN ("vta"."source" = 'unity'::"text") THEN 'unity'::"text"
            WHEN ("vta"."source" = 'tiktok'::"text") THEN 'tiktok'::"text"
            WHEN ("vta"."source" = 'ironsource'::"text") THEN 'ironsource'::"text"
            WHEN ("vta"."source" = 'vungle'::"text") THEN 'vungle'::"text"
            WHEN ("vta"."source" = 'adcolony'::"text") THEN 'adcolony'::"text"
            WHEN ("vta"."source" = 'pangle'::"text") THEN 'pangle'::"text"
            WHEN ("vta"."source" = 'pincrux'::"text") THEN 'pincrux'::"text"
            WHEN ("vta"."source" = 'tapjoy'::"text") THEN 'tapjoy'::"text"
            ELSE COALESCE(NULLIF("vta"."source", ''::"text"), NULLIF("vta"."ad_network", ''::"text"))
        END AS "ad_network",
    "vta"."reward_name" AS "ad_reward_name",
    COALESCE("s_ad"."sum_amount", (0)::numeric) AS "star_gain",
    COALESCE("b_ad"."sum_amount", (0)::numeric) AS "bonus_gain"
   FROM (("public"."view_transaction_all_base" "vta"
     LEFT JOIN "star_hist_agg" "s_ad" ON ((("s_ad"."txn_text" = "vta"."transaction_id") AND (("s_ad"."user_id" = "vta"."user_id") OR ("vta"."user_id" IS NULL)))))
     LEFT JOIN "bonus_hist_agg" "b_ad" ON ((("b_ad"."txn_text" = "vta"."transaction_id") AND (("b_ad"."user_id" = "vta"."user_id") OR ("vta"."user_id" IS NULL)))))
UNION ALL
 SELECT ('VOTE:'::"text" || ("vp"."id")::"text") AS "unified_id",
    'VOTE'::"text" AS "source",
    "vp"."created_at",
    "vp"."user_id",
    ("vp"."amount")::numeric AS "amount",
    'VOTE'::"text" AS "subtype",
    NULL::numeric AS "remain_amount",
    NULL::timestamp with time zone AS "expired_dt",
    NULL::"text" AS "transaction_id",
    ("vp"."id")::bigint AS "vote_pick_id",
    "v"."title" AS "vote_title",
    NULL::"jsonb" AS "vote_item_title",
    NULL::"jsonb" AS "vote_item_name",
    ("a"."name")::"jsonb" AS "artist_name",
    NULL::"text" AS "receipt_platform",
    NULL::"text" AS "receipt_product_id",
    NULL::"text" AS "receipt_status",
    NULL::"text" AS "receipt_environment",
    NULL::"text" AS "ad_source",
    NULL::"text" AS "ad_network",
    NULL::"text" AS "ad_reward_name",
    NULL::numeric AS "star_gain",
    NULL::numeric AS "bonus_gain"
   FROM ((("public"."vote_pick" "vp"
     LEFT JOIN "public"."vote" "v" ON (("v"."id" = "vp"."vote_id")))
     LEFT JOIN "public"."vote_item" "vi" ON (("vi"."id" = "vp"."vote_item_id")))
     LEFT JOIN "public"."artist" "a" ON (("a"."id" = "vi"."artist_id")));

COMMENT ON VIEW "public"."view_user_activity_unified" IS 'Unified view of user activities across candy history, bonus history, receipts, ad transactions, and vote picks.';

CREATE OR REPLACE VIEW "public"."view_user_candy_ledger" AS
 WITH "base" AS (
         SELECT "sch"."user_id",
            "sch"."created_at",
            "sch"."transaction_id",
            ("sch"."type")::"text" AS "type",
            "sch"."amount" AS "star_amount",
            NULL::integer AS "bonus_amount",
            "sch"."vote_pick_id"
           FROM "public"."star_candy_history" "sch"
        UNION ALL
         SELECT "sbh"."user_id",
            "sbh"."created_at",
            "sbh"."transaction_id",
            "sbh"."type",
            NULL::integer AS "star_amount",
            "sbh"."amount" AS "bonus_amount",
            "sbh"."vote_pick_id"
           FROM "public"."star_candy_bonus_history" "sbh"
        ), "grouped" AS (
         SELECT "base"."user_id",
            COALESCE("base"."transaction_id", "concat"("base"."type", '-', "to_char"("base"."created_at", 'YYYYMMDDHH24MISSMS'::"text"), '-', COALESCE("base"."vote_pick_id", 0))) AS "group_key",
            "min"("base"."created_at") AS "created_at",
            "max"("base"."type") AS "type",
            "sum"(COALESCE("base"."star_amount", 0)) AS "star_amount",
            "sum"(COALESCE("base"."bonus_amount", 0)) AS "bonus_amount",
            "max"("base"."vote_pick_id") AS "vote_pick_id"
           FROM "base"
          GROUP BY "base"."user_id", COALESCE("base"."transaction_id", "concat"("base"."type", '-', "to_char"("base"."created_at", 'YYYYMMDDHH24MISSMS'::"text"), '-', COALESCE("base"."vote_pick_id", 0)))
        ), "enriched" AS (
         SELECT "g"."user_id",
            "g"."created_at",
            "g"."type",
            "g"."star_amount",
            "g"."bonus_amount",
            "g"."group_key" AS "transaction_id",
            "g"."vote_pick_id",
            "t"."source",
                CASE
                    WHEN ("t"."source" = 'admob'::"text") THEN 'admob'::"text"
                    WHEN ("t"."source" = 'applovin'::"text") THEN 'applovin'::"text"
                    WHEN ("t"."source" = 'unity'::"text") THEN 'unity'::"text"
                    WHEN ("t"."source" = 'tiktok'::"text") THEN 'tiktok'::"text"
                    WHEN ("t"."source" = 'ironsource'::"text") THEN 'ironsource'::"text"
                    WHEN ("t"."source" = 'vungle'::"text") THEN 'vungle'::"text"
                    WHEN ("t"."source" = 'adcolony'::"text") THEN 'adcolony'::"text"
                    WHEN ("t"."source" = 'pangle'::"text") THEN 'pangle'::"text"
                    WHEN ("t"."source" = 'pincrux'::"text") THEN 'pincrux'::"text"
                    WHEN ("t"."source" = 'tapjoy'::"text") THEN 'tapjoy'::"text"
                    ELSE COALESCE(NULLIF("t"."source", ''::"text"), NULLIF("t"."ad_network", ''::"text"))
                END AS "ad_network",
            "t"."platform",
            "t"."reward_name",
            "t"."reward_type",
            "r"."product_id",
            ("v"."title" ->> 'ko'::"text") AS "vote_title_ko",
            "a"."name" AS "artist_name"
           FROM (((((("grouped" "g"
             LEFT JOIN "public"."view_transaction_all_base" "t" ON ((("t"."user_id" = "g"."user_id") AND ("t"."transaction_id" = "g"."group_key"))))
             LEFT JOIN "public"."receipts" "r" ON ((("r"."user_id" = "g"."user_id") AND (("r"."receipt_hash" = "g"."group_key") OR (("r"."id")::"text" = "g"."group_key")))))
             LEFT JOIN "public"."vote_pick" "vp" ON (("vp"."id" = "g"."vote_pick_id")))
             LEFT JOIN "public"."vote" "v" ON (("v"."id" = "vp"."vote_id")))
             LEFT JOIN "public"."vote_item" "vi" ON (("vi"."id" = "vp"."vote_item_id")))
             LEFT JOIN "public"."artist" "a" ON (("a"."id" = "vi"."artist_id")))
        )
 SELECT "e"."created_at",
    "e"."user_id",
        CASE "e"."type"
            WHEN 'PURCHASE'::"text" THEN '구매'::"text"
            WHEN 'AD'::"text" THEN '광고시청'::"text"
            WHEN 'VOTE'::"text" THEN '투표'::"text"
            WHEN 'VOTE_SHARE_BONUS'::"text" THEN '투표 공유 보너스'::"text"
            WHEN 'GIFT'::"text" THEN '선물'::"text"
            WHEN 'MISSION'::"text" THEN '미션'::"text"
            WHEN 'EXPIRED'::"text" THEN '만료'::"text"
            WHEN 'OPEN_COMPATIBILITY'::"text" THEN '궁합 열람'::"text"
            ELSE "e"."type"
        END AS "category",
        CASE "e"."type"
            WHEN 'PURCHASE'::"text" THEN "e"."product_id"
            WHEN 'AD'::"text" THEN COALESCE("e"."ad_network", "e"."source")
            WHEN 'VOTE'::"text" THEN "e"."vote_title_ko"
            ELSE NULL::"text"
        END AS "name",
        CASE "e"."type"
            WHEN 'AD'::"text" THEN "e"."reward_name"
            WHEN 'VOTE'::"text" THEN (("e"."artist_name")::"jsonb" ->> 'ko'::"text")
            ELSE NULL::"text"
        END AS "detail",
    "e"."ad_network",
    "e"."star_amount",
    "e"."bonus_amount",
    "sum"((COALESCE("e"."star_amount", (0)::bigint) + COALESCE("e"."bonus_amount", (0)::bigint))) OVER (PARTITION BY "e"."user_id" ORDER BY "e"."created_at", "e"."transaction_id" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "balance",
    "e"."transaction_id"
   FROM "enriched" "e";

