CREATE OR REPLACE VIEW "public"."vote_item_request_status_summary" AS
 SELECT "viru"."vote_id",
    "viru"."status" AS "request_status",
    "a"."id" AS "artist_id",
    ("a"."name" ->> 'ko'::"text") AS "artist_name",
    ("ag"."name" ->> 'ko'::"text") AS "artist_group",
    "count"(*) AS "request_count",
    "min"("viru"."created_at") AS "first_request_at",
    "max"("viru"."updated_at") AS "last_updated_at"
   FROM (("public"."vote_item_request_users" "viru"
     JOIN "public"."artist" "a" ON (("viru"."artist_id" = "a"."id")))
     LEFT JOIN "public"."artist_group" "ag" ON (("a"."group_id" = "ag"."id")))
  GROUP BY "viru"."vote_id", "viru"."status", "a"."id", ("a"."name" ->> 'ko'::"text"), ("ag"."name" ->> 'ko'::"text")
  ORDER BY ("count"(*)) DESC;

CREATE OR REPLACE VIEW "public"."vote_item_requests" AS
 SELECT "viru"."id",
    "viru"."vote_id",
    "viru"."status",
    "viru"."created_at",
    "viru"."updated_at",
    "viru"."user_id",
    "viru"."artist_id",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "information_schema"."tables"
              WHERE ((("tables"."table_schema")::"name" = 'public'::"name") AND (("tables"."table_name")::"name" = 'artist'::"name")))) THEN ( SELECT "row_to_json"("a".*) AS "row_to_json"
               FROM "public"."artist" "a"
              WHERE ("a"."id" = "viru"."artist_id"))
            ELSE "json_build_object"('id', "viru"."artist_id", 'name', "json_build_object"('ko', 'Unknown', 'en', 'Unknown'))
        END AS "artist"
   FROM "public"."vote_item_request_users" "viru";

CREATE TABLE IF NOT EXISTS "public"."vote_item_requests_backup" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "vote_id" integer NOT NULL,
    "status" character varying(50) DEFAULT 'pending'::character varying NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "vote_item_requests_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'in-progress'::character varying, 'cancelled'::character varying])::"text"[])))
);

