CREATE OR REPLACE VIEW "public"."vw_star_candy_bonus_drift" AS
 SELECT "up"."id" AS "user_id",
    "up"."star_candy_bonus" AS "profile_bonus",
    COALESCE("sum"(
        CASE
            WHEN (("h"."parent_id" IS NULL) AND ("h"."deleted_at" IS NULL) AND (COALESCE("h"."remain_amount", 0) > 0) AND (("h"."expired_dt" IS NULL) OR ("h"."expired_dt" > "now"()))) THEN "h"."remain_amount"
            ELSE 0
        END), (0)::bigint) AS "history_bonus",
    (COALESCE("sum"(
        CASE
            WHEN (("h"."parent_id" IS NULL) AND ("h"."deleted_at" IS NULL) AND (COALESCE("h"."remain_amount", 0) > 0) AND (("h"."expired_dt" IS NULL) OR ("h"."expired_dt" > "now"()))) THEN "h"."remain_amount"
            ELSE 0
        END), (0)::bigint) - COALESCE("up"."star_candy_bonus", 0)) AS "delta",
    "max"("h"."updated_at") AS "last_history_at"
   FROM ("public"."user_profiles" "up"
     LEFT JOIN "public"."star_candy_bonus_history" "h" ON (("h"."user_id" = "up"."id")))
  GROUP BY "up"."id";

