CREATE POLICY "Admin can access all audit logs" ON "public"."audit_logs" USING ((EXISTS ( SELECT 1
   FROM ("public"."admin_user_roles" "aur"
     JOIN "public"."admin_roles" "ar" ON (("aur"."role_id" = "ar"."id")))
  WHERE (("aur"."user_id" = "auth"."uid"()) AND (("ar"."name")::"text" = ANY ((ARRAY['super_admin'::character varying, 'admin'::character varying])::"text"[]))))));

CREATE POLICY "Admin can manage all qna_messages" ON "public"."qna_messages" USING ("public"."is_admin_or_super"()) WITH CHECK ("public"."is_admin_or_super"());

CREATE POLICY "Admin can manage all qna_threads" ON "public"."qna_threads" USING ((EXISTS ( SELECT 1
   FROM "public"."admin_whitelist" "aw"
  WHERE (("aw"."email" = ("auth"."jwt"() ->> 'email'::"text")) AND ("aw"."is_active" = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."admin_whitelist" "aw"
  WHERE (("aw"."email" = ("auth"."jwt"() ->> 'email'::"text")) AND ("aw"."is_active" = true)))));

