CREATE OR REPLACE FUNCTION public.process_attendance_check(
  p_user_id uuid,
  p_check_date date,
  p_reward_amount integer,
  p_weekly_bonus_amount integer,
  p_expired_dt timestamp with time zone,
  p_transaction_id text,
  p_weekly_transaction_id text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_at timestamptz;
  v_profile_exists boolean;
BEGIN
  SELECT deleted_at, true
    INTO v_deleted_at, v_profile_exists
    FROM public.user_profiles
   WHERE id = p_user_id;

  IF NOT COALESCE(v_profile_exists, false) OR v_deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ACCOUNT_DELETED');
  END IF;

  INSERT INTO public.attendance_check (user_id, check_date, reward_amount, weekly_bonus_amount)
  VALUES (p_user_id, p_check_date, p_reward_amount, p_weekly_bonus_amount);

  INSERT INTO public.star_candy_bonus_history (user_id, type, amount, remain_amount, expired_dt, transaction_id)
  VALUES (p_user_id, 'ATTENDANCE', p_reward_amount, p_reward_amount, p_expired_dt, p_transaction_id);

  IF p_weekly_bonus_amount > 0 AND p_weekly_transaction_id IS NOT NULL THEN
    INSERT INTO public.star_candy_bonus_history (user_id, type, amount, remain_amount, expired_dt, transaction_id)
    VALUES (p_user_id, 'ATTENDANCE_WEEKLY', p_weekly_bonus_amount, p_weekly_bonus_amount, p_expired_dt, p_weekly_transaction_id);
  END IF;

  RETURN jsonb_build_object('success', true);

EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'code', 'ALREADY_CHECKED');
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_monthly_votes()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    current_month_start   date := date_trunc('month', now())::date;
    next_month_start      date := current_month_start + interval '1 month';
    next_next_month_start date := current_month_start + interval '2 month';

    current_first_saturday  timestamptz;
    current_second_saturday timestamptz;
    current_third_saturday  timestamptz;
    current_fourth_saturday timestamptz;

    next_first_saturday   timestamptz;
    next_second_saturday  timestamptz;
    next_third_saturday   timestamptz;
    next_fourth_saturday  timestamptz;

    next_month_1st_saturday timestamptz;
    next_month_2nd_saturday timestamptz;

    debut_visible_at timestamptz;
    debut_start_at   timestamptz;
    debut_stop_at    timestamptz;

    birth_visible_at timestamptz;
    birth_start_at   timestamptz;
    birth_stop_at    timestamptz;

    musical_birth_visible_at timestamptz;
    musical_birth_start_at   timestamptz;
    musical_birth_stop_at    timestamptz;

    inserted_debut_vote_id INT;
    inserted_birth_male_vote_id INT;
    inserted_birth_female_vote_id INT;
    inserted_musical_vote_id INT;

    result_msg TEXT := '--- create_monthly_votes() result ---' || E'\n';
BEGIN
    WITH base AS (SELECT current_month_start AS d),
         first_sat AS (
             SELECT (
                        d + ((6 - EXTRACT(isodow FROM d)::int + 7) % 7) * interval '1 day'
                            + interval '9 hours'
                        )::timestamptz AS sat FROM base
         )
    SELECT sat, sat + interval '7 days', sat + interval '14 days', sat + interval '21 days'
    INTO current_first_saturday, current_second_saturday, current_third_saturday, current_fourth_saturday
    FROM first_sat;

    WITH base AS (SELECT next_month_start AS d),
         first_sat AS (
             SELECT (
                        d + ((6 - EXTRACT(isodow FROM d)::int + 7) % 7) * interval '1 day'
                            + interval '9 hours'
                        )::timestamptz AS sat FROM base
         )
    SELECT sat, sat + interval '7 days', sat + interval '14 days', sat + interval '21 days'
    INTO next_first_saturday, next_second_saturday, next_third_saturday, next_fourth_saturday
    FROM first_sat;

    WITH base AS (SELECT next_month_start AS d),
         first_sat AS (
             SELECT (
                        d + ((6 - EXTRACT(isodow FROM d)::int + 7) % 7) * interval '1 day'
                            + interval '9 hours'
                        )::timestamptz AS sat FROM base
         )
    SELECT sat, sat + interval '7 days'
    INTO next_month_1st_saturday, next_month_2nd_saturday
    FROM first_sat;

    debut_visible_at := current_first_saturday;
    debut_start_at   := current_second_saturday;
    debut_stop_at    := current_fourth_saturday;

    birth_visible_at := current_third_saturday;
    birth_start_at   := current_fourth_saturday;
    birth_stop_at    := next_month_2nd_saturday;

    musical_birth_visible_at := current_second_saturday;
    musical_birth_start_at   := current_third_saturday;
    musical_birth_stop_at    := next_month_1st_saturday;

    IF NOT EXISTS (
        SELECT 1
        FROM vote
        WHERE area = 'kpop'
          AND vote_category = 'debut'
          AND date_trunc('month', start_at) = current_month_start
          AND deleted_at IS NULL
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'kpop', 'debut', NULL,
                   debut_visible_at, debut_start_at, debut_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_month_start, 'MM') || '월 데뷔 투표',
                           'en', to_char(next_month_start, 'FMMonth') || ' Debut Vote'
                   )
               ) RETURNING id INTO inserted_debut_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_debut_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_kpop = TRUE
          AND a.debut_mm = EXTRACT(MONTH FROM next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[KPOP] Debut vote created for ' || to_char(next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[KPOP] Debut vote already exists for ' || to_char(next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vote
        WHERE area = 'kpop' AND vote_category = 'birthday' AND vote_sub_category = 'male'
          AND date_trunc('month', start_at) = current_month_start
          AND deleted_at IS NULL
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'kpop', 'birthday', 'male',
                   birth_visible_at, birth_start_at, birth_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_next_month_start, 'MM') || '월 생일 투표(남자)',
                           'en', to_char(next_next_month_start, 'FMMonth') || ' Birthday Poll (Male)'
                   )
               ) RETURNING id INTO inserted_birth_male_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_birth_male_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_kpop = TRUE AND a.gender = 'MALE'
          AND EXTRACT(MONTH FROM a.birth_date) = EXTRACT(MONTH FROM next_next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[KPOP] Birthday(MALE) created for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[KPOP] Birthday(MALE) already exists for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vote
        WHERE area = 'kpop' AND vote_category = 'birthday' AND vote_sub_category = 'female'
          AND date_trunc('month', start_at) = current_month_start
          AND deleted_at IS NULL
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'kpop', 'birthday', 'female',
                   birth_visible_at, birth_start_at, birth_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_next_month_start, 'MM') || '월 생일 투표(여자)',
                           'en', to_char(next_next_month_start, 'FMMonth') || ' Birthday Poll (Female)'
                   )
               ) RETURNING id INTO inserted_birth_female_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_birth_female_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_kpop = TRUE AND a.gender = 'FEMALE'
          AND EXTRACT(MONTH FROM a.birth_date) = EXTRACT(MONTH FROM next_next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[KPOP] Birthday(FEMALE) created for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[KPOP] Birthday(FEMALE) already exists for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vote
        WHERE area = 'musical' AND vote_category = 'birthday' AND vote_sub_category IS NULL
          AND date_trunc('month', start_at) = current_month_start
          AND deleted_at IS NULL
    ) THEN
        INSERT INTO vote (area, vote_category, vote_sub_category, visible_at, start_at, stop_at, title)
        VALUES (
                   'musical', 'birthday', NULL,
                   musical_birth_visible_at, musical_birth_start_at, musical_birth_stop_at,
                   jsonb_build_object(
                           'ko', to_char(next_next_month_start, 'MM') || '월 뮤지컬 생일 투표',
                           'en', to_char(next_next_month_start, 'FMMonth') || ' Musical Birthday Poll'
                   )
               ) RETURNING id INTO inserted_musical_vote_id;

        INSERT INTO vote_item (vote_id, artist_id, group_id)
        SELECT inserted_musical_vote_id, a.id, 0
        FROM artist a
        WHERE a.is_musical = TRUE
          AND EXTRACT(MONTH FROM a.birth_date) = EXTRACT(MONTH FROM next_next_month_start)
          AND a.deleted_at IS NULL;

        result_msg := result_msg || '[Musical] Birthday created for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    ELSE
        result_msg := result_msg || '[Musical] Birthday already exists for ' || to_char(next_next_month_start, 'YYYY-MM') || E'\n';
    END IF;

    RAISE NOTICE '%', result_msg;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error in create_monthly_votes(): %', SQLERRM;
END;
$function$;

CREATE UNIQUE INDEX IF NOT EXISTS ux_vote_monthly_auto_dedup
  ON public.vote (
    area,
    vote_category,
    (COALESCE(vote_sub_category, '')),
    (date_trunc('month', start_at AT TIME ZONE 'UTC'))
  )
  WHERE deleted_at IS NULL
    AND vote_category IN ('debut', 'birthday');

DROP FUNCTION IF EXISTS public.detect_abuser_candidates(integer, integer, integer);

CREATE OR REPLACE FUNCTION public.detect_abuser_candidates(
  p_daily_threshold integer DEFAULT 200,
  p_min_days integer DEFAULT 3,
  p_lookback_days integer DEFAULT 30
)
RETURNS TABLE (
  user_id uuid,
  nickname text,
  email text,
  is_banned boolean,
  daily_avg numeric,
  max_daily bigint,
  suspicious_days bigint,
  total_bonus numeric,
  active_bonus integer
)
LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  WITH daily_counts AS (
    SELECT
      h.user_id,
      DATE(h.created_at AT TIME ZONE 'Asia/Seoul') AS day,
      COUNT(*) AS daily_count,
      SUM(h.amount) AS daily_amount
    FROM star_candy_bonus_history h
    WHERE h.type = 'AD'
      AND h.parent_id IS NULL
      AND h.created_at >= NOW() - (p_lookback_days || ' days')::INTERVAL
    GROUP BY h.user_id, DATE(h.created_at AT TIME ZONE 'Asia/Seoul')
    HAVING COUNT(*) >= p_daily_threshold
  ),
  suspicious_users AS (
    SELECT
      dc.user_id,
      ROUND(AVG(dc.daily_count), 1) AS daily_avg,
      MAX(dc.daily_count) AS max_daily,
      COUNT(*) AS suspicious_days,
      SUM(dc.daily_amount)::numeric AS total_bonus
    FROM daily_counts dc
    GROUP BY dc.user_id
    HAVING COUNT(*) >= p_min_days
  )
  SELECT
    su.user_id,
    up.nickname,
    up.email,
    (up.deleted_at IS NOT NULL) AS is_banned,
    su.daily_avg::numeric,
    su.max_daily::bigint,
    su.suspicious_days::bigint,
    su.total_bonus::numeric,
    COALESCE(up.star_candy_bonus, 0) AS active_bonus
  FROM suspicious_users su
  JOIN user_profiles up ON up.id = su.user_id
  ORDER BY su.total_bonus DESC;
END $$;

CREATE TABLE IF NOT EXISTS public.request_ip_log (
  id          BIGSERIAL PRIMARY KEY,
  user_id     UUID NULL,
  action_type TEXT NOT NULL,
  ip_hash     TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  metadata    JSONB
);

CREATE INDEX IF NOT EXISTS request_ip_log_ip_action_time_idx
  ON public.request_ip_log (ip_hash, action_type, created_at DESC);

CREATE INDEX IF NOT EXISTS request_ip_log_user_action_time_idx
  ON public.request_ip_log (user_id, action_type, created_at DESC)
  WHERE user_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS request_ip_log_created_at_brin_idx
  ON public.request_ip_log USING BRIN (created_at);

CREATE TABLE IF NOT EXISTS public.ip_block_decisions (
  id                 BIGSERIAL PRIMARY KEY,
  ip_hash            TEXT NOT NULL,
  action_type        TEXT NOT NULL,
  user_id            UUID NULL,
  decision           TEXT NOT NULL CHECK (decision IN ('suspect','blocked')),
  mode               TEXT NOT NULL CHECK (mode IN ('shadow','enforce')),
  reason             TEXT NOT NULL,
  applied_window     INT NOT NULL,
  threshold_used     INT NOT NULL,
  observed_value     INT NOT NULL,
  attempt_count      INT NOT NULL DEFAULT 1,
  first_seen_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_seen_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at         TIMESTAMPTZ NULL,
  cs_resolution      TEXT NULL CHECK (cs_resolution IN ('false_positive','confirmed_abuse')),
  reviewed_by        UUID NULL,
  reviewed_at        TIMESTAMPTZ NULL,
  attempted_email    TEXT NULL,
  attempted_provider TEXT NULL
);

CREATE INDEX IF NOT EXISTS ip_block_decisions_active_idx
  ON public.ip_block_decisions (ip_hash, decision, expires_at);

CREATE INDEX IF NOT EXISTS ip_block_decisions_queue_idx
  ON public.ip_block_decisions (decision, last_seen_at DESC)
  WHERE cs_resolution IS NULL;

CREATE TABLE IF NOT EXISTS public.anti_abuse_policies (
  id                BIGSERIAL PRIMARY KEY,
  action_type       TEXT NOT NULL,
  window_seconds    INT NOT NULL,
  suspect_threshold INT NOT NULL,
  block_threshold   INT NOT NULL,
  count_strategy    TEXT NOT NULL CHECK (count_strategy IN ('distinct_user_id','row_count')),
  enabled           BOOLEAN NOT NULL DEFAULT true,
  mode              TEXT NOT NULL DEFAULT 'shadow' CHECK (mode IN ('shadow','enforce')),
  enforce_since     TIMESTAMPTZ NULL,
  note              TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by        UUID,
  UNIQUE (action_type, window_seconds)
);

CREATE TABLE IF NOT EXISTS public.anti_abuse_daily_stats (
  day            DATE NOT NULL,
  action_type    TEXT NOT NULL,
  decision       TEXT NOT NULL,
  mode           TEXT NOT NULL,
  count          INT NOT NULL,
  PRIMARY KEY (day, action_type, decision, mode)
);

CREATE TABLE IF NOT EXISTS public.user_abuse_review_queue (
  id                  BIGSERIAL PRIMARY KEY,
  user_id             UUID NOT NULL,
  source_decision_id  BIGINT NOT NULL REFERENCES ip_block_decisions(id),
  status              TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','resolved','skipped')),
  resolution_note     TEXT,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolved_at         TIMESTAMPTZ NULL,
  resolved_by         UUID NULL
);

CREATE INDEX IF NOT EXISTS user_abuse_review_queue_status_idx
  ON public.user_abuse_review_queue (status, created_at);

CREATE INDEX IF NOT EXISTS user_abuse_review_queue_user_idx
  ON public.user_abuse_review_queue (user_id);

CREATE UNIQUE INDEX IF NOT EXISTS user_abuse_review_queue_source_decision_uniq
  ON public.user_abuse_review_queue (source_decision_id);

