CREATE OR REPLACE FUNCTION public.check_ip_quota(
  p_action TEXT,
  p_ip_hash TEXT,
  p_user_id UUID
) RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_policy             anti_abuse_policies%ROWTYPE;
  v_window_start       TIMESTAMPTZ;
  v_observed           INT;
  v_strongest          TEXT := 'allow';
  v_strongest_mode     TEXT;
  v_worst_window       INT;
  v_worst_threshold    INT;
  v_worst_observed     INT := 0;
  v_worst_reason       TEXT;
  v_active_decision_id BIGINT;
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash = '' OR p_ip_hash = 'unknown' THEN
    RETURN 'allow';
  END IF;

  UPDATE ip_block_decisions
     SET attempt_count = attempt_count + 1,
         last_seen_at  = NOW()
   WHERE ip_hash = p_ip_hash
     AND action_type = p_action
     AND decision = 'blocked'
     AND mode = 'enforce'
     AND cs_resolution IS NULL
     AND (expires_at IS NULL OR expires_at > NOW())
   RETURNING id INTO v_active_decision_id;

  IF v_active_decision_id IS NOT NULL THEN
    RETURN 'blocked';
  END IF;

  FOR v_policy IN
    SELECT * FROM anti_abuse_policies
     WHERE action_type = p_action AND enabled = true
  LOOP
    v_window_start := GREATEST(
      NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL,
      COALESCE(v_policy.enforce_since, NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL)
    );

    IF v_policy.count_strategy = 'distinct_user_id' THEN
      IF p_action = 'ad_watch' THEN
        SELECT COUNT(DISTINCT user_id) INTO v_observed
          FROM ad_impressions
         WHERE ip_hash = p_ip_hash
           AND created_at >= v_window_start
           AND user_id IS NOT NULL
           AND ip_hash ~ '^[0-9a-f]{64}$';
      ELSIF p_action = 'artist_request' THEN
        SELECT COUNT(DISTINCT user_id) INTO v_observed
          FROM vote_item_request_users
         WHERE ip_hash = p_ip_hash
           AND created_at >= v_window_start
           AND user_id IS NOT NULL;
      ELSE
        SELECT COUNT(DISTINCT user_id) INTO v_observed
          FROM request_ip_log
         WHERE ip_hash = p_ip_hash
           AND action_type = p_action
           AND created_at >= v_window_start
           AND user_id IS NOT NULL;
      END IF;
    ELSE
      SELECT COUNT(*) INTO v_observed
        FROM request_ip_log
       WHERE ip_hash = p_ip_hash
         AND action_type = p_action
         AND created_at >= v_window_start;
    END IF;

    IF v_observed >= v_policy.block_threshold THEN
      IF v_strongest <> 'blocked'
         OR (v_observed - v_policy.block_threshold) > (v_worst_observed - v_worst_threshold) THEN
        v_strongest       := 'blocked';
        v_strongest_mode  := v_policy.mode;
        v_worst_window    := v_policy.window_seconds;
        v_worst_threshold := v_policy.block_threshold;
        v_worst_observed  := v_observed;
        v_worst_reason    := format('%s_%s_users_per_ip_%ss', p_action, v_observed, v_policy.window_seconds);
      END IF;
    ELSIF v_observed >= v_policy.suspect_threshold AND v_strongest = 'allow' THEN
      v_strongest       := 'suspect';
      v_strongest_mode  := v_policy.mode;
      v_worst_window    := v_policy.window_seconds;
      v_worst_threshold := v_policy.suspect_threshold;
      v_worst_observed  := v_observed;
      v_worst_reason    := format('%s_%s_users_per_ip_%ss_suspect', p_action, v_observed, v_policy.window_seconds);
    ELSIF v_observed >= v_policy.suspect_threshold AND v_strongest = 'suspect'
          AND (v_observed - v_policy.suspect_threshold) > (v_worst_observed - v_worst_threshold) THEN
      v_strongest_mode  := v_policy.mode;
      v_worst_window    := v_policy.window_seconds;
      v_worst_threshold := v_policy.suspect_threshold;
      v_worst_observed  := v_observed;
      v_worst_reason    := format('%s_%s_users_per_ip_%ss_suspect', p_action, v_observed, v_policy.window_seconds);
    END IF;
  END LOOP;

  IF v_strongest IN ('suspect','blocked') THEN
    PERFORM pg_advisory_xact_lock(
      178633894::int,
      (hashtextextended(p_ip_hash || '|' || p_action || '|' || v_strongest || '|' || v_strongest_mode, 0) & 2147483647)::int
    );

    UPDATE ip_block_decisions
       SET attempt_count   = attempt_count + 1,
           last_seen_at    = NOW(),
           observed_value  = GREATEST(observed_value, v_worst_observed),
           reason          = v_worst_reason,
           threshold_used  = v_worst_threshold,
           applied_window  = v_worst_window
     WHERE ip_hash = p_ip_hash
       AND action_type = p_action
       AND decision = v_strongest
       AND mode = v_strongest_mode
       AND cs_resolution IS NULL
       AND (expires_at IS NULL OR expires_at > NOW());

    IF NOT FOUND THEN
      INSERT INTO ip_block_decisions
        (ip_hash, action_type, user_id, decision, mode, reason,
         applied_window, threshold_used, observed_value,
         first_seen_at, last_seen_at, expires_at)
      VALUES
        (p_ip_hash, p_action, p_user_id, v_strongest, v_strongest_mode,
         v_worst_reason, v_worst_window, v_worst_threshold, v_worst_observed,
         NOW(), NOW(),
         CASE WHEN v_strongest = 'blocked' THEN NOW() + INTERVAL '24 hours' ELSE NULL END);
    END IF;
  END IF;

  IF v_strongest = 'allow' THEN
    RETURN 'allow';
  ELSIF v_strongest_mode = 'shadow' THEN
    RETURN 'allow';
  ELSE
    RETURN v_strongest;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.record_request_ip(
  p_action TEXT,
  p_ip_hash TEXT,
  p_user_id UUID,
  p_metadata JSONB
) RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash = '' OR p_ip_hash = 'unknown' THEN
    RETURN;
  END IF;
  INSERT INTO request_ip_log (action_type, ip_hash, user_id, metadata)
  VALUES (p_action, p_ip_hash, p_user_id, p_metadata);
END $$;

CREATE OR REPLACE FUNCTION public.assert_anti_abuse_permission(p_permission_key TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid UUID;
  v_resource TEXT;
  v_action TEXT;
  v_dot_pos INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_dot_pos := position('.' IN p_permission_key);
  IF v_dot_pos = 0 THEN
    RAISE EXCEPTION 'invalid permission key (no dot): %', p_permission_key USING ERRCODE = '22023';
  END IF;
  v_resource := substring(p_permission_key FROM 1 FOR v_dot_pos - 1);
  v_action   := substring(p_permission_key FROM v_dot_pos + 1);

  IF NOT EXISTS (
    SELECT 1
      FROM admin_user_roles aur
      JOIN admin_role_permissions arp ON arp.role_id = aur.role_id
      JOIN admin_permissions ap        ON ap.id = arp.permission_id
     WHERE aur.user_id = v_uid
       AND ap.resource = v_resource
       AND ap.action   = v_action
  ) THEN
    RAISE EXCEPTION 'permission denied: %', p_permission_key USING ERRCODE = '42501';
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.list_my_anti_abuse_permissions()
RETURNS SETOF TEXT
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT DISTINCT ap.resource || '.' || ap.action
    FROM admin_user_roles aur
    JOIN admin_role_permissions arp ON arp.role_id = aur.role_id
    JOIN admin_permissions ap        ON ap.id = arp.permission_id
   WHERE aur.user_id = auth.uid()
     AND ap.resource = 'anti_abuse';
$$;

CREATE OR REPLACE FUNCTION public.get_users_for_ip_hash(
  p_ip_hash TEXT,
  p_window_days INT DEFAULT 7
) RETURNS TABLE (
  user_id    UUID,
  nickname   TEXT,
  email      TEXT,
  created_at TIMESTAMPTZ,
  is_banned  BOOLEAN,
  sources    TEXT
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  RETURN QUERY
  WITH since AS (SELECT NOW() - (p_window_days || ' days')::INTERVAL AS t),
  candidates AS (
    SELECT ai.user_id, 'ad' AS source FROM ad_impressions ai, since
     WHERE ai.ip_hash = p_ip_hash AND ai.created_at >= since.t AND ai.user_id IS NOT NULL
    UNION
    SELECT ril.user_id, 'request_log' FROM request_ip_log ril, since
     WHERE ril.ip_hash = p_ip_hash AND ril.created_at >= since.t AND ril.user_id IS NOT NULL
    UNION
    SELECT vir.user_id, 'artist_req' FROM vote_item_request_users vir, since
     WHERE vir.ip_hash = p_ip_hash AND vir.created_at >= since.t AND vir.user_id IS NOT NULL
  ),
  agg AS (
    SELECT user_id, string_agg(DISTINCT source, ',') AS sources
      FROM candidates GROUP BY user_id
  )
  SELECT
    up.id,
    up.nickname,
    CASE
      WHEN up.email IS NULL OR up.email = '' THEN NULL
      ELSE regexp_replace(up.email, '^(.).*?(@.*)$', '\1***\2')
    END AS email,
    up.created_at,
    (up.deleted_at IS NOT NULL),
    a.sources
   FROM agg a
   JOIN user_profiles up ON up.id = a.user_id
  ORDER BY up.created_at DESC;
END $$;

CREATE OR REPLACE FUNCTION public.list_anti_abuse_policies()
RETURNS SETOF anti_abuse_policies
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY SELECT * FROM anti_abuse_policies ORDER BY action_type, window_seconds;
END $$;

CREATE OR REPLACE FUNCTION public.get_ip_block_queue_count()
RETURNS BIGINT
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE v_count BIGINT;
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  SELECT COUNT(*) INTO v_count FROM ip_block_decisions WHERE cs_resolution IS NULL;
  RETURN v_count;
END $$;

CREATE OR REPLACE FUNCTION public.get_ip_block_decision_detail(p_decision_id BIGINT)
RETURNS SETOF ip_block_decisions
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  RETURN QUERY SELECT * FROM ip_block_decisions WHERE id = p_decision_id;
END $$;

CREATE OR REPLACE FUNCTION public.get_request_ip_activity(
  p_ip_hash TEXT,
  p_window_days INT DEFAULT 7,
  p_limit INT DEFAULT 100
) RETURNS SETOF request_ip_log
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  RETURN QUERY
    SELECT * FROM request_ip_log
     WHERE ip_hash = p_ip_hash
       AND created_at >= NOW() - (p_window_days || ' days')::INTERVAL
     ORDER BY created_at DESC
     LIMIT p_limit;
END $$;

CREATE OR REPLACE FUNCTION public.get_ip_block_queue(
  p_status TEXT DEFAULT 'unresolved',
  p_action_type TEXT DEFAULT NULL,
  p_limit INT DEFAULT 100,
  p_offset INT DEFAULT 0
) RETURNS SETOF ip_block_decisions
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  RETURN QUERY
    SELECT *
      FROM ip_block_decisions
     WHERE (
         p_status = 'all'
         OR (p_status = 'unresolved' AND cs_resolution IS NULL)
         OR (p_status = 'resolved' AND cs_resolution IS NOT NULL)
       )
       AND (p_action_type IS NULL OR action_type = p_action_type)
     ORDER BY (cs_resolution IS NULL) DESC, last_seen_at DESC
     LIMIT p_limit OFFSET p_offset;
END $$;

CREATE OR REPLACE FUNCTION public.resolve_ip_block(
  p_decision_id BIGINT,
  p_resolution TEXT,
  p_admin_user_id UUID
) RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision ip_block_decisions%ROWTYPE;
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  IF p_resolution NOT IN ('false_positive','confirmed_abuse') THEN
    RAISE EXCEPTION 'invalid resolution: %', p_resolution;
  END IF;

  SELECT * INTO v_decision FROM ip_block_decisions WHERE id = p_decision_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'decision not found: %', p_decision_id;
  END IF;

  IF p_resolution = 'false_positive' THEN
    UPDATE ip_block_decisions
       SET cs_resolution = 'false_positive',
           reviewed_by   = p_admin_user_id,
           reviewed_at   = NOW(),
           expires_at    = NOW()
     WHERE id = p_decision_id;
  ELSE
    UPDATE ip_block_decisions
       SET cs_resolution = 'confirmed_abuse',
           reviewed_by   = p_admin_user_id,
           reviewed_at   = NOW(),
           expires_at    = COALESCE(expires_at, NOW()) + INTERVAL '7 days'
     WHERE id = p_decision_id;

    IF v_decision.user_id IS NOT NULL THEN
      INSERT INTO user_abuse_review_queue (user_id, source_decision_id)
      VALUES (v_decision.user_id, p_decision_id)
      ON CONFLICT (source_decision_id) DO NOTHING;
    END IF;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.upsert_anti_abuse_policy(
  p_action_type TEXT,
  p_window INT,
  p_suspect INT,
  p_block INT,
  p_enabled BOOLEAN,
  p_mode TEXT,
  p_admin_user_id UUID
) RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_old_mode TEXT;
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.policy.write');
  SELECT mode INTO v_old_mode FROM anti_abuse_policies
   WHERE action_type = p_action_type AND window_seconds = p_window;

  INSERT INTO anti_abuse_policies
    (action_type, window_seconds, suspect_threshold, block_threshold, count_strategy,
     enabled, mode, enforce_since, updated_at, updated_by)
  VALUES
    (p_action_type, p_window, p_suspect, p_block,
     CASE WHEN p_action_type='signup' THEN 'row_count' ELSE 'distinct_user_id' END,
     p_enabled, p_mode,
     NOW(),
     NOW(), p_admin_user_id)
  ON CONFLICT (action_type, window_seconds) DO UPDATE SET
    suspect_threshold = EXCLUDED.suspect_threshold,
    block_threshold   = EXCLUDED.block_threshold,
    enabled           = EXCLUDED.enabled,
    mode              = EXCLUDED.mode,
    enforce_since     = CASE
      WHEN anti_abuse_policies.mode IS DISTINCT FROM EXCLUDED.mode AND EXCLUDED.mode = 'enforce'
        THEN NOW()
      ELSE anti_abuse_policies.enforce_since
    END,
    updated_at        = NOW(),
    updated_by        = p_admin_user_id;
END $$;

CREATE OR REPLACE FUNCTION public.get_anti_abuse_summary(
  p_window_days INT DEFAULT 7
) RETURNS TABLE (
  total_decisions      BIGINT,
  active_blocked_ips   BIGINT,
  suspect_count        BIGINT,
  blocked_count        BIGINT,
  shadow_count         BIGINT,
  enforce_count        BIGINT,
  fp_ratio             NUMERIC
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY
  WITH base AS (
    SELECT * FROM ip_block_decisions
     WHERE first_seen_at >= NOW() - (p_window_days || ' days')::INTERVAL
  )
  SELECT
    COUNT(*)::BIGINT,
    (SELECT COUNT(DISTINCT ip_hash) FROM ip_block_decisions
      WHERE decision='blocked' AND mode='enforce' AND cs_resolution IS NULL
        AND (expires_at IS NULL OR expires_at > NOW()))::BIGINT,
    COUNT(*) FILTER (WHERE decision = 'suspect')::BIGINT,
    COUNT(*) FILTER (WHERE decision = 'blocked')::BIGINT,
    COUNT(*) FILTER (WHERE mode = 'shadow')::BIGINT,
    COUNT(*) FILTER (WHERE mode = 'enforce')::BIGINT,
    CASE
      WHEN COUNT(*) FILTER (WHERE cs_resolution IS NOT NULL) = 0 THEN 0::NUMERIC
      ELSE ROUND(
        COUNT(*) FILTER (WHERE cs_resolution = 'false_positive')::NUMERIC
        / NULLIF(COUNT(*) FILTER (WHERE cs_resolution IS NOT NULL), 0),
        3)
    END
  FROM base;
END $$;

CREATE OR REPLACE FUNCTION public.get_anti_abuse_timeseries(
  p_metric TEXT DEFAULT 'decision_count',
  p_window_days INT DEFAULT 30,
  p_granularity TEXT DEFAULT 'day'
) RETURNS TABLE (
  bucket      TIMESTAMPTZ,
  action_type TEXT,
  decision    TEXT,
  mode        TEXT,
  count       BIGINT
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  IF p_granularity NOT IN ('hour','day') THEN
    RAISE EXCEPTION 'unsupported granularity: %', p_granularity;
  END IF;

  RETURN QUERY EXECUTE format(
    $f$
    SELECT date_trunc(%L, first_seen_at) AS bucket,
           action_type, decision, mode, COUNT(*)::BIGINT
      FROM ip_block_decisions
     WHERE first_seen_at >= NOW() - ($1 || ' days')::INTERVAL
     GROUP BY 1, 2, 3, 4
     ORDER BY 1
    $f$, p_granularity)
  USING p_window_days;
END $$;

CREATE OR REPLACE FUNCTION public.get_anti_abuse_top_ips(
  p_window_days INT DEFAULT 7,
  p_limit INT DEFAULT 20
) RETURNS TABLE (
  ip_hash             TEXT,
  block_count         BIGINT,
  suspect_count       BIGINT,
  total_attempts      BIGINT,
  distinct_user_ids   BIGINT,
  last_seen_at        TIMESTAMPTZ
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY
  SELECT
    d.ip_hash,
    COUNT(*) FILTER (WHERE decision='blocked')::BIGINT,
    COUNT(*) FILTER (WHERE decision='suspect')::BIGINT,
    SUM(attempt_count)::BIGINT,
    COUNT(DISTINCT user_id) FILTER (WHERE user_id IS NOT NULL)::BIGINT,
    MAX(last_seen_at)
   FROM ip_block_decisions d
   WHERE first_seen_at >= NOW() - (p_window_days || ' days')::INTERVAL
   GROUP BY d.ip_hash
   ORDER BY SUM(attempt_count) DESC
   LIMIT p_limit;
END $$;

CREATE OR REPLACE FUNCTION public.simulate_threshold_change(
  p_action_type TEXT,
  p_window INT,
  p_new_suspect INT,
  p_new_block INT
) RETURNS TABLE (
  would_be_suspect BIGINT,
  would_be_blocked BIGINT,
  current_suspect  BIGINT,
  current_blocked  BIGINT
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_current_suspect INT;
  v_current_block   INT;
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  SELECT suspect_threshold, block_threshold INTO v_current_suspect, v_current_block
    FROM anti_abuse_policies
   WHERE action_type = p_action_type AND window_seconds = p_window
   LIMIT 1;

  RETURN QUERY
  WITH ip_window_counts AS (
    SELECT ip_hash, COUNT(DISTINCT user_id) AS users FROM (
      SELECT ip_hash, user_id, created_at
        FROM ad_impressions
       WHERE p_action_type = 'ad_watch'
         AND user_id IS NOT NULL
         AND ip_hash ~ '^[0-9a-f]{64}$'
      UNION ALL
      SELECT ip_hash, user_id, created_at
        FROM vote_item_request_users
       WHERE p_action_type = 'artist_request'
         AND user_id IS NOT NULL
      UNION ALL
      SELECT ip_hash, user_id, created_at
        FROM request_ip_log
       WHERE p_action_type NOT IN ('ad_watch','artist_request')
         AND action_type = p_action_type
         AND user_id IS NOT NULL
    ) t
    WHERE created_at >= NOW() - (p_window || ' seconds')::INTERVAL
    GROUP BY ip_hash
  )
  SELECT
    COUNT(*) FILTER (WHERE users >= p_new_suspect AND users < p_new_block)::BIGINT,
    COUNT(*) FILTER (WHERE users >= p_new_block)::BIGINT,
    COUNT(*) FILTER (WHERE users >= COALESCE(v_current_suspect, p_new_suspect)
                       AND users < COALESCE(v_current_block, p_new_block))::BIGINT,
    COUNT(*) FILTER (WHERE users >= COALESCE(v_current_block, p_new_block))::BIGINT
   FROM ip_window_counts;
END $$;

CREATE OR REPLACE FUNCTION public.get_anti_abuse_top_ips(
  p_window_days INT DEFAULT 7,
  p_limit INT DEFAULT 20
) RETURNS TABLE (
  ip_hash             TEXT,
  block_count         BIGINT,
  suspect_count       BIGINT,
  total_attempts      BIGINT,
  distinct_user_ids   BIGINT,
  last_seen_at        TIMESTAMPTZ
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY
  SELECT
    d.ip_hash,
    COUNT(*) FILTER (WHERE d.decision='blocked')::BIGINT,
    COUNT(*) FILTER (WHERE d.decision='suspect')::BIGINT,
    SUM(d.attempt_count)::BIGINT,
    COUNT(DISTINCT d.user_id) FILTER (WHERE d.user_id IS NOT NULL)::BIGINT,
    MAX(d.last_seen_at)
   FROM ip_block_decisions d
   WHERE d.first_seen_at >= NOW() - (p_window_days || ' days')::INTERVAL
   GROUP BY d.ip_hash
   ORDER BY SUM(d.attempt_count) DESC
   LIMIT p_limit;
END $$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_nickname text;
  v_avatar_url text;
  v_email text;
  v_provider text;
  v_unique_nickname text;
  v_random_number int;
  v_ip_hash text;
  v_decision text;
BEGIN
  v_ip_hash := new.raw_user_meta_data->>'signup_ip_hash';
  IF v_ip_hash IS NOT NULL AND v_ip_hash <> '' AND v_ip_hash <> 'unknown' THEN
    BEGIN
      v_decision := check_ip_quota('signup', v_ip_hash, NULL);
      IF v_decision = 'blocked' THEN
        UPDATE ip_block_decisions
           SET attempted_email = COALESCE(attempted_email, new.email),
               attempted_provider = COALESCE(attempted_provider, new.raw_user_meta_data->>'provider')
         WHERE ip_hash = v_ip_hash AND action_type = 'signup'
           AND decision = 'blocked' AND cs_resolution IS NULL
           AND (expires_at IS NULL OR expires_at > NOW());

        RAISE EXCEPTION 'RATE_LIMITED:signup' USING ERRCODE = 'P0001';
      ELSE
        PERFORM record_request_ip('signup', v_ip_hash, NULL,
          jsonb_build_object('email', new.email, 'provider', new.raw_user_meta_data->>'provider'));
      END IF;
    EXCEPTION
      WHEN SQLSTATE 'P0001' THEN RAISE;
      WHEN OTHERS THEN
        INSERT INTO public.debug_logs (log_message)
          VALUES ('handle_new_user anti-abuse RPC error: ' || SQLERRM);
    END;
  END IF;

  insert into public.debug_logs (log_message)
  values ('Trigger function handle_new_user() called with user ID: ' || new.id);

  insert into public.debug_logs (log_message)
  values ('raw_user_meta_data: ' || coalesce(new.raw_user_meta_data::text, 'NULL'));

  v_provider := new.raw_user_meta_data->>'provider';
  insert into public.debug_logs (log_message)
  values ('Login provider: ' || coalesce(v_provider, 'unknown'));

  v_email := new.email;
  insert into public.debug_logs (log_message)
  values ('Email: ' || coalesce(v_email, 'NULL'));

  if v_provider = 'apple' then
    v_nickname := split_part(v_email, '@', 1);
    v_avatar_url := null;
    insert into public.debug_logs (log_message)
    values ('Apple login detected. Extracted nickname: ' || coalesce(v_nickname, 'NULL'));
  else
    v_nickname := coalesce(new.raw_user_meta_data->>'name', split_part(v_email, '@', 1));
    v_avatar_url := new.raw_user_meta_data->>'picture';
    insert into public.debug_logs (log_message)
    values ('Non-Apple login detected. Nickname: ' || coalesce(v_nickname, 'NULL'));
  end if;

  v_nickname := replace(v_nickname, ' ', '');

  insert into public.debug_logs (log_message)
  values ('Nickname after removing spaces: ' || coalesce(v_nickname, 'NULL'));

  v_random_number := floor(random() * 9000 + 1000)::int;
  v_unique_nickname := v_nickname || v_random_number::text;

  while exists (select 1 from public.user_profiles where nickname = v_unique_nickname) loop
    v_random_number := floor(random() * 9000 + 1000)::int;
    v_unique_nickname := v_nickname || v_random_number::text;
  end loop;

  insert into public.debug_logs (log_message)
  values ('Generated unique nickname: ' || v_unique_nickname);

  insert into public.debug_logs (log_message)
  values ('Final values - v_unique_nickname: ' || coalesce(v_unique_nickname, 'NULL') ||
          ', v_avatar_url: ' || coalesce(v_avatar_url, 'NULL') ||
          ', v_email: ' || coalesce(v_email, 'NULL'));

  insert into public.debug_logs (log_message)
  values ('Attempting to insert into user_profiles');

  insert into public.user_profiles (id, nickname, avatar_url, email)
  values (new.id, v_unique_nickname, v_avatar_url, v_email);

  insert into public.debug_logs (log_message)
  values ('New user profile created for user ID: ' || new.id || ', Provider: ' || v_provider || ', Unique Nickname: ' || v_unique_nickname);

  return new;
exception
  when sqlstate 'P0001' then raise;
  when others then
    insert into public.debug_logs (log_message)
    values ('Error creating user profile: ' || sqlerrm || ', Provider: ' || coalesce(v_provider, 'unknown'));
    return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.vote_item_request_users_anti_abuse_check()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision text;
BEGIN
  IF NEW.ip_hash IS NULL OR NEW.ip_hash = '' OR NEW.ip_hash = 'unknown' THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_decision := check_ip_quota('artist_request', NEW.ip_hash, NEW.user_id);
    IF v_decision = 'blocked' THEN
      RAISE EXCEPTION 'RATE_LIMITED:artist_request' USING ERRCODE = 'P0001';
    END IF;
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN RAISE;
    WHEN OTHERS THEN
      INSERT INTO public.debug_logs (log_message)
        VALUES ('artist_request anti-abuse RPC error: ' || SQLERRM);
  END;

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS vote_item_request_users_anti_abuse_check_trg
  ON public.vote_item_request_users;

CREATE TRIGGER vote_item_request_users_anti_abuse_check_trg
  BEFORE INSERT ON public.vote_item_request_users
  FOR EACH ROW EXECUTE FUNCTION public.vote_item_request_users_anti_abuse_check();

DROP FUNCTION IF EXISTS public.create_vote_item_request_with_user(integer, integer, uuid);

CREATE OR REPLACE FUNCTION public.create_vote_item_request_with_user(
  vote_id_param integer,
  artist_id_param integer,
  user_id_param uuid,
  p_ip_hash text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
DECLARE
  new_request_id uuid;
  result_data jsonb;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.vote_item_request_users viru
    WHERE viru.vote_id = vote_id_param
      AND viru.user_id = user_id_param
      AND viru.artist_id = artist_id_param
  ) THEN
    RAISE EXCEPTION '이미 해당 아티스트에 대해 신청하셨습니다.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.artist WHERE id = artist_id_param) THEN
    RAISE EXCEPTION '존재하지 않는 아티스트입니다.';
  END IF;

  new_request_id := uuid_generate_v4();

  INSERT INTO public.vote_item_request_users (
    id, vote_item_request_id, vote_id, user_id, artist_id, status, ip_hash
  ) VALUES (
    new_request_id, new_request_id, vote_id_param, user_id_param, artist_id_param,
    'pending', p_ip_hash
  );

  SELECT jsonb_build_object(
    'vote_item_request', jsonb_build_object(
      'id', new_request_id,
      'vote_id', vote_id_param,
      'status', 'pending',
      'created_at', NOW(),
      'updated_at', NOW()
    ),
    'user_request', to_jsonb(viru.*),
    'artist', to_jsonb(a.*)
  ) INTO result_data
  FROM public.vote_item_request_users viru
       JOIN public.artist a ON viru.artist_id = a.id
  WHERE viru.vote_item_request_id = new_request_id AND viru.user_id = user_id_param;

  RETURN result_data;
END;
$fn$;

COMMENT ON COLUMN public.vote_item_request_users.ip_hash IS
  'HMAC-SHA256(IP_HASH_SALT, client IP). anti-abuse trigger 가 검사. 일반 user SELECT 불가 (column-level REVOKE).';

COMMENT ON FUNCTION public.check_ip_quota(TEXT, TEXT, UUID) IS
  'anti-abuse rate limit decision. service_role + postgres (trigger owner) 만 호출 가능.';

COMMENT ON FUNCTION public.record_request_ip(TEXT, TEXT, UUID, JSONB) IS
  'anti-abuse audit log 적재. service_role + postgres (trigger owner) 만 호출 가능.';

CREATE OR REPLACE FUNCTION public.resolve_ip_block(
  p_decision_id BIGINT,
  p_resolution TEXT,
  p_admin_user_id UUID
) RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
DECLARE
  v_decision ip_block_decisions%ROWTYPE;
  v_actor UUID := COALESCE(auth.uid(), p_admin_user_id);
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  IF p_resolution NOT IN ('false_positive','confirmed_abuse') THEN
    RAISE EXCEPTION 'invalid resolution: %', p_resolution;
  END IF;

  SELECT * INTO v_decision FROM ip_block_decisions WHERE id = p_decision_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'decision not found: %', p_decision_id;
  END IF;

  IF p_resolution = 'false_positive' THEN
    UPDATE ip_block_decisions
       SET cs_resolution = 'false_positive',
           reviewed_by   = v_actor,
           reviewed_at   = NOW(),
           expires_at    = NOW()
     WHERE id = p_decision_id;
  ELSE
    UPDATE ip_block_decisions
       SET cs_resolution = 'confirmed_abuse',
           reviewed_by   = v_actor,
           reviewed_at   = NOW(),
           expires_at    = COALESCE(expires_at, NOW()) + INTERVAL '7 days'
     WHERE id = p_decision_id;

    IF v_decision.user_id IS NOT NULL THEN
      INSERT INTO user_abuse_review_queue (user_id, source_decision_id)
      VALUES (v_decision.user_id, p_decision_id)
      ON CONFLICT (source_decision_id) DO NOTHING;
    END IF;
  END IF;
END $fn$;

CREATE OR REPLACE FUNCTION public.upsert_anti_abuse_policy(
  p_action_type TEXT,
  p_window INT,
  p_suspect INT,
  p_block INT,
  p_enabled BOOLEAN,
  p_mode TEXT,
  p_admin_user_id UUID
) RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
DECLARE
  v_old_mode TEXT;
  v_actor UUID := COALESCE(auth.uid(), p_admin_user_id);
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.policy.write');
  SELECT mode INTO v_old_mode FROM anti_abuse_policies
   WHERE action_type = p_action_type AND window_seconds = p_window;

  INSERT INTO anti_abuse_policies
    (action_type, window_seconds, suspect_threshold, block_threshold, count_strategy,
     enabled, mode, enforce_since, updated_at, updated_by)
  VALUES
    (p_action_type, p_window, p_suspect, p_block,
     CASE WHEN p_action_type='signup' THEN 'row_count' ELSE 'distinct_user_id' END,
     p_enabled, p_mode,
     NOW(),
     NOW(), v_actor)
  ON CONFLICT (action_type, window_seconds) DO UPDATE SET
    suspect_threshold = EXCLUDED.suspect_threshold,
    block_threshold   = EXCLUDED.block_threshold,
    enabled           = EXCLUDED.enabled,
    mode              = EXCLUDED.mode,
    enforce_since     = CASE
      WHEN anti_abuse_policies.mode IS DISTINCT FROM EXCLUDED.mode AND EXCLUDED.mode = 'enforce'
        THEN NOW()
      ELSE anti_abuse_policies.enforce_since
    END,
    updated_at        = NOW(),
    updated_by        = v_actor;
END $fn$;

