CREATE OR REPLACE FUNCTION public.get_active_block_spike()
RETURNS TABLE (
  current_count BIGINT,
  baseline      NUMERIC,
  ratio         NUMERIC
)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
  WITH last_hour AS (
    SELECT COUNT(*) AS c
      FROM ip_block_decisions
     WHERE decision = 'blocked' AND mode = 'enforce'
       AND first_seen_at >= NOW() - INTERVAL '1 hour'
  ),
  baseline_calc AS (
    SELECT AVG(c) AS avg_c
      FROM (
        SELECT date_trunc('hour', first_seen_at) AS hr, COUNT(*) AS c
          FROM ip_block_decisions
         WHERE decision = 'blocked' AND mode = 'enforce'
           AND first_seen_at >= NOW() - INTERVAL '7 days'
           AND first_seen_at <  NOW() - INTERVAL '1 hour'
           AND EXTRACT(HOUR FROM first_seen_at) = EXTRACT(HOUR FROM NOW())
         GROUP BY 1
      ) t
  )
  SELECT
    (SELECT c FROM last_hour)::BIGINT AS current_count,
    COALESCE((SELECT avg_c FROM baseline_calc), 0)::NUMERIC AS baseline,
    CASE
      WHEN COALESCE((SELECT avg_c FROM baseline_calc), 0) = 0 THEN 0::NUMERIC
      ELSE ROUND(((SELECT c FROM last_hour)::NUMERIC / (SELECT avg_c FROM baseline_calc))::NUMERIC, 2)
    END AS ratio;
$fn$;

CREATE OR REPLACE FUNCTION public.get_suspect_burst()
RETURNS TABLE (
  current_count BIGINT,
  baseline      NUMERIC,
  ratio         NUMERIC
)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
  WITH last_hour AS (
    SELECT COUNT(*) AS c
      FROM ip_block_decisions
     WHERE decision = 'suspect'
       AND first_seen_at >= NOW() - INTERVAL '1 hour'
  ),
  baseline_calc AS (
    SELECT AVG(c) AS avg_c
      FROM (
        SELECT date_trunc('hour', first_seen_at) AS hr, COUNT(*) AS c
          FROM ip_block_decisions
         WHERE decision = 'suspect'
           AND first_seen_at >= NOW() - INTERVAL '7 days'
           AND first_seen_at <  NOW() - INTERVAL '1 hour'
           AND EXTRACT(HOUR FROM first_seen_at) = EXTRACT(HOUR FROM NOW())
         GROUP BY 1
      ) t
  )
  SELECT
    (SELECT c FROM last_hour)::BIGINT,
    COALESCE((SELECT avg_c FROM baseline_calc), 0)::NUMERIC,
    CASE
      WHEN COALESCE((SELECT avg_c FROM baseline_calc), 0) = 0 THEN 0::NUMERIC
      ELSE ROUND(((SELECT c FROM last_hour)::NUMERIC / (SELECT avg_c FROM baseline_calc))::NUMERIC, 2)
    END;
$fn$;

CREATE OR REPLACE FUNCTION public.get_fp_ratios_24h()
RETURNS TABLE (
  action_type TEXT,
  total       BIGINT,
  fp_count    BIGINT,
  fp_ratio    NUMERIC
)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
  SELECT
    ip_block_decisions.action_type,
    COUNT(*)::BIGINT AS total,
    COUNT(*) FILTER (WHERE cs_resolution = 'false_positive')::BIGINT AS fp_count,
    CASE
      WHEN COUNT(*) FILTER (WHERE cs_resolution IS NOT NULL) = 0 THEN 0::NUMERIC
      ELSE ROUND(
        COUNT(*) FILTER (WHERE cs_resolution = 'false_positive')::NUMERIC
        / NULLIF(COUNT(*) FILTER (WHERE cs_resolution IS NOT NULL), 0), 3)
    END AS fp_ratio
  FROM ip_block_decisions
  WHERE first_seen_at >= NOW() - INTERVAL '24 hours'
  GROUP BY ip_block_decisions.action_type;
$fn$;

CREATE EXTENSION IF NOT EXISTS pg_cron;

CREATE EXTENSION IF NOT EXISTS pg_net;

CREATE OR REPLACE FUNCTION public.aggregate_anti_abuse_daily_stats(p_target_day DATE DEFAULT NULL)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
DECLARE v_day DATE;
BEGIN
  v_day := COALESCE(p_target_day, (NOW() AT TIME ZONE 'Asia/Seoul')::DATE - 1);

  INSERT INTO public.anti_abuse_daily_stats (day, action_type, decision, mode, count)
  SELECT
    v_day,
    action_type,
    decision,
    mode,
    COUNT(*)::INT
  FROM public.ip_block_decisions
  WHERE (first_seen_at AT TIME ZONE 'Asia/Seoul')::DATE = v_day
  GROUP BY action_type, decision, mode
  ON CONFLICT (day, action_type, decision, mode) DO UPDATE
     SET count = EXCLUDED.count;

  DELETE FROM public.anti_abuse_alert_log WHERE sent_at < NOW() - INTERVAL '14 days';
END $fn$;

DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'anti_abuse_daily_stats') THEN
    PERFORM cron.unschedule('anti_abuse_daily_stats');
  END IF;
EXCEPTION WHEN OTHERS THEN NULL;
END $do$;

DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'anti_abuse_alert_dispatcher') THEN
    PERFORM cron.unschedule('anti_abuse_alert_dispatcher');
  END IF;
EXCEPTION WHEN OTHERS THEN NULL;
END $do$;

SELECT cron.schedule(
  'anti_abuse_daily_stats',
  '0 19 * * *',
  $cron$ SELECT public.aggregate_anti_abuse_daily_stats(NULL); $cron$
);

COMMENT ON FUNCTION public.aggregate_anti_abuse_daily_stats(DATE) IS
  'Plan 4 — anti_abuse_daily_stats 일 집계 + alert_log 14일 retention cleanup. p_target_day NULL=어제(KST).';

CREATE OR REPLACE FUNCTION public.get_ip_hash_meta(
  p_ip_hash TEXT,
  p_window_days INT DEFAULT 7
) RETURNS TABLE (
  last_ip      TEXT,
  country_code TEXT,
  user_count   BIGINT
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  RETURN QUERY
  WITH since AS (SELECT NOW() - (p_window_days || ' days')::INTERVAL AS t),
  candidates AS (
    SELECT ai.user_id FROM ad_impressions ai, since
     WHERE ai.ip_hash = p_ip_hash AND ai.created_at >= since.t AND ai.user_id IS NOT NULL
    UNION
    SELECT ril.user_id FROM request_ip_log ril, since
     WHERE ril.ip_hash = p_ip_hash AND ril.created_at >= since.t AND ril.user_id IS NOT NULL
    UNION
    SELECT vir.user_id FROM vote_item_request_users vir, since
     WHERE vir.ip_hash = p_ip_hash AND vir.created_at >= since.t AND vir.user_id IS NOT NULL
  ),
  users AS (
    SELECT up.id, up.last_ip, up.country_code
      FROM user_profiles up
      JOIN candidates c ON c.user_id = up.id
  ),
  ip_majority AS (
    SELECT users.last_ip, COUNT(*) AS cnt
      FROM users WHERE users.last_ip IS NOT NULL
      GROUP BY users.last_ip ORDER BY cnt DESC LIMIT 1
  ),
  cc_majority AS (
    SELECT users.country_code, COUNT(*) AS cnt
      FROM users WHERE users.country_code IS NOT NULL
      GROUP BY users.country_code ORDER BY cnt DESC LIMIT 1
  )
  SELECT
    (SELECT ip_majority.last_ip FROM ip_majority),
    (SELECT cc_majority.country_code FROM cc_majority),
    (SELECT COUNT(*)::BIGINT FROM users);
END $fn$;

DROP FUNCTION IF EXISTS public.get_users_for_ip_hash(TEXT, INT);

CREATE OR REPLACE FUNCTION public.get_users_for_ip_hash(
  p_ip_hash TEXT,
  p_window_days INT DEFAULT 7
) RETURNS TABLE (
  user_id      UUID,
  nickname     TEXT,
  email        TEXT,
  created_at   TIMESTAMPTZ,
  is_banned    BOOLEAN,
  sources      TEXT,
  last_ip      TEXT,
  country_code TEXT
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  RETURN QUERY
  WITH since AS (SELECT NOW() - (p_window_days || ' days')::INTERVAL AS t),
  candidates AS (
    SELECT ai.user_id, 'ad' AS source FROM ad_impressions ai, since
     WHERE ai.ip_hash = p_ip_hash AND ai.created_at >= since.t AND ai.user_id IS NOT NULL
    UNION
    SELECT ril.user_id, 'request_log' FROM request_ip_log ril, since
     WHERE ril.ip_hash = p_ip_hash AND ril.created_at >= since.t AND ril.user_id IS NOT NULL
    UNION
    SELECT vir.user_id, 'artist_req' FROM vote_item_request_users vir, since
     WHERE vir.ip_hash = p_ip_hash AND vir.created_at >= since.t AND vir.user_id IS NOT NULL
  ),
  agg AS (
    SELECT candidates.user_id, string_agg(DISTINCT candidates.source, ',') AS sources
      FROM candidates GROUP BY candidates.user_id
  )
  SELECT
    up.id,
    up.nickname,
    CASE
      WHEN up.email IS NULL OR up.email = '' THEN NULL
      ELSE regexp_replace(up.email, '^(.).*?(@.*)$', '\1***\2')
    END AS email,
    up.created_at,
    (up.deleted_at IS NOT NULL) AS is_banned,
    a.sources,
    up.last_ip,
    up.country_code
   FROM agg a
   JOIN user_profiles up ON up.id = a.user_id
  ORDER BY up.created_at DESC;
END $fn$;

DROP FUNCTION IF EXISTS public.get_anti_abuse_top_ips(INT, INT);

CREATE OR REPLACE FUNCTION public.get_anti_abuse_top_ips(
  p_window_days INT DEFAULT 7,
  p_limit INT DEFAULT 20
) RETURNS TABLE (
  ip_hash             TEXT,
  block_count         BIGINT,
  suspect_count       BIGINT,
  total_attempts      BIGINT,
  distinct_user_ids   BIGINT,
  last_seen_at        TIMESTAMPTZ,
  last_ip             TEXT,
  country_code        TEXT,
  is_active_block     BOOLEAN
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY
  WITH agg AS (
    SELECT
      d.ip_hash,
      COUNT(*) FILTER (WHERE d.decision='blocked')::BIGINT AS block_count,
      COUNT(*) FILTER (WHERE d.decision='suspect')::BIGINT AS suspect_count,
      SUM(d.attempt_count)::BIGINT AS total_attempts,
      COUNT(DISTINCT d.user_id) FILTER (WHERE d.user_id IS NOT NULL)::BIGINT AS distinct_user_ids,
      MAX(d.last_seen_at) AS last_seen_at,
      bool_or(
        d.decision='blocked' AND d.mode='enforce' AND d.cs_resolution IS NULL
        AND (d.expires_at IS NULL OR d.expires_at > NOW())
      ) AS is_active_block
     FROM ip_block_decisions d
     WHERE d.first_seen_at >= NOW() - (p_window_days || ' days')::INTERVAL
     GROUP BY d.ip_hash
     ORDER BY SUM(d.attempt_count) DESC
     LIMIT p_limit
  )
  SELECT
    a.ip_hash, a.block_count, a.suspect_count, a.total_attempts,
    a.distinct_user_ids, a.last_seen_at,
    m.last_ip, m.country_code, a.is_active_block
   FROM agg a
   LEFT JOIN LATERAL (
     SELECT * FROM public.get_ip_hash_meta(a.ip_hash, p_window_days)
   ) m ON TRUE;
END $fn$;

DROP FUNCTION IF EXISTS public.get_ip_block_queue(TEXT, TEXT, INT, INT);

CREATE OR REPLACE FUNCTION public.get_ip_block_queue(
  p_status TEXT DEFAULT 'unresolved',
  p_action_type TEXT DEFAULT NULL,
  p_limit INT DEFAULT 100,
  p_offset INT DEFAULT 0
) RETURNS TABLE (
  id                 BIGINT,
  ip_hash            TEXT,
  action_type        TEXT,
  user_id            UUID,
  decision           TEXT,
  mode               TEXT,
  reason             TEXT,
  applied_window     INT,
  threshold_used     INT,
  observed_value     INT,
  attempt_count      INT,
  first_seen_at      TIMESTAMPTZ,
  last_seen_at       TIMESTAMPTZ,
  expires_at         TIMESTAMPTZ,
  cs_resolution      TEXT,
  reviewed_by        UUID,
  reviewed_at        TIMESTAMPTZ,
  attempted_email    TEXT,
  attempted_provider TEXT,
  last_ip            TEXT,
  country_code       TEXT,
  is_active_block    BOOLEAN
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');
  RETURN QUERY
  SELECT
    d.id, d.ip_hash, d.action_type, d.user_id, d.decision, d.mode, d.reason,
    d.applied_window, d.threshold_used, d.observed_value, d.attempt_count,
    d.first_seen_at, d.last_seen_at, d.expires_at, d.cs_resolution,
    d.reviewed_by, d.reviewed_at, d.attempted_email, d.attempted_provider,
    m.last_ip,
    m.country_code,
    (d.decision='blocked' AND d.mode='enforce' AND d.cs_resolution IS NULL
       AND (d.expires_at IS NULL OR d.expires_at > NOW())) AS is_active_block
    FROM ip_block_decisions d
    LEFT JOIN LATERAL (
      SELECT * FROM public.get_ip_hash_meta(d.ip_hash, 7)
    ) m ON TRUE
   WHERE (
       p_status = 'all'
       OR (p_status = 'unresolved' AND d.cs_resolution IS NULL)
       OR (p_status = 'resolved' AND d.cs_resolution IS NOT NULL)
     )
     AND (p_action_type IS NULL OR d.action_type = p_action_type)
   ORDER BY (d.cs_resolution IS NULL) DESC, d.last_seen_at DESC
   LIMIT p_limit OFFSET p_offset;
END $fn$;

DROP FUNCTION IF EXISTS public.get_anti_abuse_summary(INT);

CREATE OR REPLACE FUNCTION public.get_anti_abuse_summary(
  p_window_days INT DEFAULT 7
) RETURNS TABLE (
  total_decisions       BIGINT,
  active_blocked_ips    BIGINT,
  active_enforce_blocks BIGINT,
  suspect_count         BIGINT,
  blocked_count         BIGINT,
  shadow_count          BIGINT,
  enforce_count         BIGINT,
  fp_ratio              NUMERIC
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY
  WITH base AS (
    SELECT * FROM ip_block_decisions
     WHERE first_seen_at >= NOW() - (p_window_days || ' days')::INTERVAL
  )
  SELECT
    (SELECT COUNT(*) FROM base)::BIGINT,
    (SELECT COUNT(DISTINCT ip_block_decisions.ip_hash) FROM ip_block_decisions
      WHERE decision='blocked' AND cs_resolution IS NULL
        AND (expires_at IS NULL OR expires_at > NOW()))::BIGINT,
    (SELECT COUNT(DISTINCT ip_block_decisions.ip_hash) FROM ip_block_decisions
      WHERE decision='blocked' AND mode='enforce' AND cs_resolution IS NULL
        AND (expires_at IS NULL OR expires_at > NOW()))::BIGINT,
    (SELECT COUNT(*) FROM base WHERE decision='suspect')::BIGINT,
    (SELECT COUNT(*) FROM base WHERE decision='blocked')::BIGINT,
    (SELECT COUNT(*) FROM base WHERE mode='shadow')::BIGINT,
    (SELECT COUNT(*) FROM base WHERE mode='enforce')::BIGINT,
    CASE
      WHEN (SELECT COUNT(*) FROM base WHERE cs_resolution IS NOT NULL) = 0 THEN 0::NUMERIC
      ELSE ROUND(
        (SELECT COUNT(*) FROM base WHERE cs_resolution = 'false_positive')::NUMERIC
        / NULLIF((SELECT COUNT(*) FROM base WHERE cs_resolution IS NOT NULL), 0), 3)
    END;
END $fn$;

