  country_code             TEXT,
  is_active_block          BOOLEAN,
  has_active_shadow_block  BOOLEAN,
  has_resolved             BOOLEAN,
  max_observed             INT,
  channels                 JSONB
)
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.dashboard.read');
  RETURN QUERY
  WITH agg AS (
    SELECT
      d.ip_hash,
      COUNT(*) FILTER (WHERE d.decision='blocked')::BIGINT AS block_count,
      COUNT(*) FILTER (WHERE d.decision='suspect')::BIGINT AS suspect_count,
      SUM(d.attempt_count)::BIGINT AS total_attempts,
      COUNT(DISTINCT d.user_id) FILTER (WHERE d.user_id IS NOT NULL)::BIGINT AS distinct_user_ids,
      MAX(d.last_seen_at) AS last_seen_at,
      bool_or(
        d.decision='blocked' AND d.mode='enforce' AND d.cs_resolution IS NULL
        AND (d.expires_at IS NULL OR d.expires_at > NOW())
      ) AS is_active_block,
      bool_or(
        d.decision='blocked' AND d.mode='shadow' AND d.cs_resolution IS NULL
        AND (d.expires_at IS NULL OR d.expires_at > NOW())
      ) AS has_active_shadow_block,
      bool_or(d.cs_resolution IS NOT NULL) AS has_resolved,
      MAX(d.observed_value)::INT AS max_observed,
      jsonb_agg(
        jsonb_build_object(
          'action_type',    d.action_type,
          'window_seconds', d.applied_window,
          'decision',       d.decision,
          'mode',           d.mode,
          'observed',       d.observed_value,
          'threshold',      d.threshold_used,
          'attempt_count',  d.attempt_count,
          'expires_at',     d.expires_at,
          'cs_resolution',  d.cs_resolution,
          'is_active',      (d.decision='blocked' AND d.cs_resolution IS NULL
                              AND (d.expires_at IS NULL OR d.expires_at > NOW()))
        )
        ORDER BY d.action_type, d.applied_window, d.decision
      ) AS channels
     FROM ip_block_decisions d
     WHERE d.first_seen_at >= NOW() - (p_window_days || ' days')::INTERVAL
     GROUP BY d.ip_hash
     ORDER BY SUM(d.attempt_count) DESC
     LIMIT p_limit
  )
  SELECT
    a.ip_hash, a.block_count, a.suspect_count, a.total_attempts,
    a.distinct_user_ids, a.last_seen_at,
    m.last_ip, m.country_code,
    a.is_active_block, a.has_active_shadow_block, a.has_resolved, a.max_observed,
    a.channels
   FROM agg a
   LEFT JOIN LATERAL (
     SELECT * FROM public.get_ip_hash_meta(a.ip_hash, p_window_days)
   ) m ON TRUE;
