COMMENT ON COLUMN public.vote_item_request_users.ip_hash IS
  'HMAC-SHA256(IP_HASH_SALT, client IP). anti-abuse trigger 가 검사. anon/authenticated SELECT 불가 — 테이블-레벨 SELECT REVOKE + 컬럼별 재부여 (ip_hash 제외).';

NOTIFY pgrst, 'reload schema';

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE OR REPLACE FUNCTION public.verify_ip_hash_sig(
  p_ip_hash text,
  p_exp bigint,
  p_action text,
  p_sig text,
  p_secret text
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE PARALLEL SAFE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_payload text;
  v_expected text;
BEGIN
  IF p_secret IS NULL OR p_secret = '' THEN RETURN false; END IF;
  IF p_sig IS NULL OR p_sig = '' THEN RETURN false; END IF;
  IF EXTRACT(EPOCH FROM NOW())::bigint > p_exp THEN RETURN false; END IF;

  v_payload := p_ip_hash || ':' || p_exp || ':' || p_action;
  v_expected := encode(hmac(v_payload, p_secret, 'sha256'), 'hex');

  IF length(v_expected) <> length(p_sig) THEN RETURN false; END IF;
  RETURN v_expected = lower(p_sig);
END $$;

CREATE OR REPLACE FUNCTION public.verify_ip_hash_sig(
  p_ip_hash text,
  p_exp bigint,
  p_action text,
  p_sig text,
  p_secret text
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE PARALLEL SAFE
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_payload text;
  v_expected text;
BEGIN
  IF p_secret IS NULL OR p_secret = '' THEN RETURN false; END IF;
  IF p_sig IS NULL OR p_sig = '' THEN RETURN false; END IF;
  IF EXTRACT(EPOCH FROM NOW())::bigint > p_exp THEN RETURN false; END IF;

  v_payload := p_ip_hash || ':' || p_exp || ':' || p_action;
  v_expected := encode(extensions.hmac(v_payload::bytea, p_secret::bytea, 'sha256'), 'hex');

  IF length(v_expected) <> length(p_sig) THEN RETURN false; END IF;
  RETURN v_expected = lower(p_sig);
END $$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_nickname text;
  v_avatar_url text;
  v_email text;
  v_provider text;
  v_unique_nickname text;
  v_random_number int;
  v_hint_hash text;
  v_hint_exp bigint;
  v_hint_sig text;
  v_secret text;
  v_sig_valid boolean := false;
BEGIN
  v_hint_hash := new.raw_user_meta_data->>'signup_ip_hash';
  v_hint_exp  := NULLIF(new.raw_user_meta_data->>'signup_ip_exp', '')::bigint;
  v_hint_sig  := new.raw_user_meta_data->>'signup_ip_sig';

  SELECT decrypted_secret INTO v_secret
    FROM vault.decrypted_secrets
   WHERE name = 'anti_abuse_signup_hint_secret'
   LIMIT 1;

  IF v_hint_hash IS NOT NULL AND v_hint_exp IS NOT NULL AND v_hint_sig IS NOT NULL
     AND v_secret IS NOT NULL THEN
    v_sig_valid := verify_ip_hash_sig(v_hint_hash, v_hint_exp, 'signup', v_hint_sig, v_secret);
  END IF;

  IF NOT v_sig_valid THEN
    UPDATE auth.users
       SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb)
                            || jsonb_build_object('signup_unverified', true,
                                                  'signup_unverified_at', NOW())
     WHERE id = new.id;
    INSERT INTO public.debug_logs (log_message)
      VALUES ('handle_new_user: signup_ip_sig invalid/missing for user ' || new.id);
  END IF;

  v_provider := new.raw_user_meta_data->>'provider';
  v_email := new.email;

  IF v_provider = 'apple' THEN
    v_nickname := split_part(v_email, '@', 1);
    v_avatar_url := NULL;
  ELSE
    v_nickname := COALESCE(new.raw_user_meta_data->>'name', split_part(v_email, '@', 1));
    v_avatar_url := new.raw_user_meta_data->>'picture';
  END IF;

  v_nickname := replace(v_nickname, ' ', '');
  v_random_number := floor(random() * 9000 + 1000)::int;
  v_unique_nickname := v_nickname || v_random_number::text;
  WHILE EXISTS (SELECT 1 FROM public.user_profiles WHERE nickname = v_unique_nickname) LOOP
    v_random_number := floor(random() * 9000 + 1000)::int;
    v_unique_nickname := v_nickname || v_random_number::text;
  END LOOP;

  INSERT INTO public.user_profiles (id, nickname, avatar_url, email)
  VALUES (new.id, v_unique_nickname, v_avatar_url, v_email);

  INSERT INTO public.debug_logs (log_message)
  VALUES ('New user profile created for user ID: ' || new.id ||
          ', Provider: ' || COALESCE(v_provider, 'unknown') ||
          ', sig_valid: ' || v_sig_valid::text);

  RETURN new;
EXCEPTION
  WHEN OTHERS THEN
    INSERT INTO public.debug_logs (log_message)
    VALUES ('Error creating user profile: ' || sqlerrm ||
            ', Provider: ' || COALESCE(v_provider, 'unknown'));
    RETURN NULL;
END;
$$;

DROP POLICY IF EXISTS "vote_item_request_users_insert_policy"
  ON public.vote_item_request_users;

CREATE POLICY "vote_item_request_users_insert_service_role_only"
  ON public.vote_item_request_users
  FOR INSERT
  TO service_role
  WITH CHECK (true);

CREATE OR REPLACE FUNCTION public.vote_item_request_users_anti_abuse_check()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.ip_hash IS NOT NULL
     AND NEW.ip_hash <> ''
     AND NEW.ip_hash <> 'unknown'
     AND NEW.ip_hash !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'INVALID_IP_HASH: %', NEW.ip_hash USING ERRCODE = '22P02';
  END IF;

  RETURN NEW;
END $$;

