CREATE OR REPLACE FUNCTION public.get_alert_blocked_rows(
  p_since TIMESTAMPTZ
)
RETURNS TABLE (
  id              BIGINT,
  user_id         UUID,
  ip_hash         TEXT,
  action_type     TEXT,
  decision        TEXT,
  mode            TEXT,
  reason          TEXT,
  applied_window  INTEGER,
  threshold_used  INTEGER,
  observed_value  INTEGER,
  attempt_count   INTEGER,
  first_seen_at   TIMESTAMPTZ,
  expires_at      TIMESTAMPTZ,
  cs_resolution   TEXT,
  user_email      TEXT,
  user_nickname   TEXT,
  last_ip         TEXT,
  country_code    TEXT,
  ip_user_count   BIGINT,
  ip_is_fallback  BOOLEAN
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    d.id, d.user_id, d.ip_hash, d.action_type, d.decision, d.mode, d.reason,
    d.applied_window, d.threshold_used, d.observed_value, d.attempt_count,
    d.first_seen_at, d.expires_at, d.cs_resolution,
    up.email     AS user_email,
    up.nickname  AS user_nickname,
    COALESCE(m.last_ip,      up.last_ip)      AS last_ip,
    COALESCE(m.country_code, up.country_code) AS country_code,
    m.user_count AS ip_user_count,
    (m.last_ip IS NULL AND up.last_ip IS NOT NULL) AS ip_is_fallback
  FROM ip_block_decisions d
  LEFT JOIN user_profiles up ON up.id = d.user_id
  LEFT JOIN LATERAL public.get_ip_hash_meta(d.ip_hash, 7) m ON TRUE
  WHERE d.decision = 'blocked'
    AND d.mode = 'enforce'
    AND d.cs_resolution IS NULL
    AND d.first_seen_at >= p_since;
$function$;

ALTER TABLE public.ip_block_decisions
  ADD COLUMN IF NOT EXISTS raw_ip TEXT;

COMMENT ON COLUMN public.ip_block_decisions.raw_ip IS
  '차단 시점의 raw IP (check_ip_quota 호출자가 직접 전달). NULL 인 옛 row 는 cohort/profile fallback 으로 alert 표시.';

DROP FUNCTION IF EXISTS public.check_ip_quota(text, text, uuid, text);

CREATE OR REPLACE FUNCTION public.check_ip_quota(
  p_action      TEXT,
  p_ip_hash     TEXT,
  p_user_id     UUID,
  p_device_hash TEXT DEFAULT NULL,
  p_raw_ip      TEXT DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_policy             anti_abuse_policies%ROWTYPE;
  v_window_start       TIMESTAMPTZ;
  v_observed           INT;
  v_strongest          TEXT := 'allow';
  v_strongest_mode     TEXT;
  v_worst_window       INT;
  v_worst_threshold    INT;
  v_worst_observed     INT := 0;
  v_worst_reason       TEXT;
  v_active_decision_id BIGINT;
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash = '' OR p_ip_hash = 'unknown' THEN
    RETURN 'allow';
  END IF;

  IF p_user_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM anti_abuse_policies
     WHERE action_type = p_action AND enabled = true
       AND count_strategy = 'creation_clustered_per_ip'
  ) THEN
    RETURN check_ip_quota_clustered(p_action, p_ip_hash, p_user_id, p_device_hash, p_raw_ip);
  END IF;

  UPDATE ip_block_decisions
     SET attempt_count = attempt_count + 1,
         last_seen_at  = NOW(),
         raw_ip = COALESCE(raw_ip, p_raw_ip)
   WHERE ip_hash = p_ip_hash
     AND action_type = p_action
     AND decision = 'blocked'
     AND mode = 'enforce'
     AND cs_resolution IS NULL
     AND (expires_at IS NULL OR expires_at > NOW())
   RETURNING id INTO v_active_decision_id;

  IF v_active_decision_id IS NOT NULL THEN
    RETURN 'blocked';
  END IF;

  FOR v_policy IN
    SELECT * FROM anti_abuse_policies
     WHERE action_type = p_action AND enabled = true
  LOOP
    v_window_start := GREATEST(
      NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL,
      COALESCE(v_policy.enforce_since, NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL)
    );

    IF v_policy.count_strategy = 'distinct_user_id' THEN
      IF p_action = 'ad_watch' THEN
        SELECT COUNT(DISTINCT user_id) INTO v_observed
          FROM ad_impressions
         WHERE ip_hash = p_ip_hash
           AND created_at >= v_window_start
           AND user_id IS NOT NULL
           AND ip_hash ~ '^[0-9a-f]{64}$';
      ELSIF p_action = 'artist_request' THEN
        SELECT COUNT(DISTINCT user_id) INTO v_observed
          FROM vote_item_request_users
         WHERE ip_hash = p_ip_hash
           AND created_at >= v_window_start
           AND user_id IS NOT NULL;
      ELSE
        SELECT COUNT(DISTINCT user_id) INTO v_observed
          FROM request_ip_log
         WHERE ip_hash = p_ip_hash
           AND action_type = p_action
           AND created_at >= v_window_start
           AND user_id IS NOT NULL;
      END IF;
    ELSE
      SELECT COUNT(*) INTO v_observed
        FROM request_ip_log
       WHERE ip_hash = p_ip_hash
         AND action_type = p_action
         AND created_at >= v_window_start;
    END IF;

    IF v_observed >= v_policy.block_threshold THEN
      IF v_strongest <> 'blocked'
         OR (v_observed - v_policy.block_threshold) > (v_worst_observed - v_worst_threshold) THEN
        v_strongest       := 'blocked';
        v_strongest_mode  := v_policy.mode;
        v_worst_window    := v_policy.window_seconds;
        v_worst_threshold := v_policy.block_threshold;
        v_worst_observed  := v_observed;
        v_worst_reason    := format('%s_%s_users_per_ip_%ss', p_action, v_observed, v_policy.window_seconds);
      END IF;
    ELSIF v_observed >= v_policy.suspect_threshold AND v_strongest = 'allow' THEN
      v_strongest       := 'suspect';
      v_strongest_mode  := v_policy.mode;
      v_worst_window    := v_policy.window_seconds;
      v_worst_threshold := v_policy.suspect_threshold;
      v_worst_observed  := v_observed;
      v_worst_reason    := format('%s_%s_users_per_ip_%ss_suspect', p_action, v_observed, v_policy.window_seconds);
    ELSIF v_observed >= v_policy.suspect_threshold AND v_strongest = 'suspect'
          AND (v_observed - v_policy.suspect_threshold) > (v_worst_observed - v_worst_threshold) THEN
      v_strongest_mode  := v_policy.mode;
      v_worst_window    := v_policy.window_seconds;
      v_worst_threshold := v_policy.suspect_threshold;
      v_worst_observed  := v_observed;
      v_worst_reason    := format('%s_%s_users_per_ip_%ss_suspect', p_action, v_observed, v_policy.window_seconds);
    END IF;
  END LOOP;

  IF p_device_hash IS NOT NULL AND p_device_hash <> '' THEN
    DECLARE
      v_dpol         anti_abuse_policies%ROWTYPE;
      v_dwin_start   TIMESTAMPTZ;
      v_dcount       INT;
    BEGIN
      SELECT * INTO v_dpol FROM anti_abuse_policies
       WHERE action_type = p_action AND enabled = true
         AND device_block_threshold IS NOT NULL
       ORDER BY window_seconds DESC LIMIT 1;
      IF FOUND THEN
        v_dwin_start := NOW() - (v_dpol.window_seconds || ' seconds')::INTERVAL;
        v_dcount := aa_device_cohort_count(p_action, p_device_hash, p_user_id, v_dwin_start);

        IF v_dcount >= v_dpol.device_block_threshold THEN
          v_strongest := 'blocked'; v_strongest_mode := v_dpol.mode;
          v_worst_reason := format('%s_device_%s_accounts', p_action, v_dcount);
          v_worst_window := v_dpol.window_seconds; v_worst_threshold := v_dpol.device_block_threshold;
          v_worst_observed := v_dcount;
        ELSIF v_dpol.device_suspect_threshold IS NOT NULL
              AND v_dcount >= v_dpol.device_suspect_threshold THEN
          IF v_strongest IN ('suspect','blocked') THEN
            v_strongest := 'blocked'; v_strongest_mode := v_dpol.mode;
            v_worst_reason := format('%s_device_%s_x_%s', p_action, v_dcount, COALESCE(v_worst_reason,'base'));
            v_worst_window := v_dpol.window_seconds; v_worst_threshold := v_dpol.device_block_threshold;
            v_worst_observed := v_dcount;
          ELSIF v_strongest = 'allow' THEN
            v_strongest := 'suspect'; v_strongest_mode := v_dpol.mode;
            v_worst_reason := format('%s_device_%s_accounts_suspect', p_action, v_dcount);
            v_worst_window := v_dpol.window_seconds; v_worst_threshold := v_dpol.device_suspect_threshold;
            v_worst_observed := v_dcount;
          END IF;
        END IF;
      END IF;
    END;
  END IF;

  IF v_strongest IN ('suspect','blocked') THEN
    PERFORM pg_advisory_xact_lock(
      178633894::int,
      (hashtextextended(p_ip_hash || '|' || p_action || '|' || v_strongest || '|' || v_strongest_mode, 0) & 2147483647)::int
    );

    UPDATE ip_block_decisions
       SET attempt_count   = attempt_count + 1,
           last_seen_at    = NOW(),
           observed_value  = GREATEST(observed_value, v_worst_observed),
           reason          = v_worst_reason,
           threshold_used  = v_worst_threshold,
           applied_window  = v_worst_window,
           raw_ip          = COALESCE(raw_ip, p_raw_ip)
     WHERE ip_hash = p_ip_hash
       AND action_type = p_action
       AND decision = v_strongest
       AND mode = v_strongest_mode
       AND cs_resolution IS NULL
       AND (expires_at IS NULL OR expires_at > NOW());

    IF NOT FOUND THEN
      INSERT INTO ip_block_decisions
        (ip_hash, action_type, user_id, decision, mode, reason,
         applied_window, threshold_used, observed_value,
         first_seen_at, last_seen_at, expires_at, raw_ip)
      VALUES
        (p_ip_hash, p_action, p_user_id, v_strongest, v_strongest_mode,
         v_worst_reason, v_worst_window, v_worst_threshold, v_worst_observed,
         NOW(), NOW(),
         CASE WHEN v_strongest = 'blocked' THEN NOW() + INTERVAL '24 hours' ELSE NULL END,
         p_raw_ip);
    END IF;
  END IF;

  IF v_strongest = 'allow' THEN
    RETURN 'allow';
  ELSIF v_strongest_mode = 'shadow' THEN
    RETURN 'allow';
  ELSE
    RETURN v_strongest;
  END IF;
END $function$;

DROP FUNCTION IF EXISTS public.check_ip_quota_clustered(text, text, uuid, text);

CREATE OR REPLACE FUNCTION public.check_ip_quota_clustered(
  p_action      TEXT,
  p_ip_hash     TEXT,
  p_user_id     UUID,
  p_device_hash TEXT DEFAULT NULL,
  p_raw_ip      TEXT DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_policy        anti_abuse_policies%ROWTYPE;
  v_window_start  TIMESTAMPTZ;
  v_device_window_start TIMESTAMPTZ;
  v_user_created  TIMESTAMPTZ;
  v_cohort_size   INT := 0;
  v_tight_n       INT := 0;
  v_loose_n       INT := 0;
  v_strongest     TEXT := 'allow';
  v_observed      INT := 0;
  v_reason        TEXT;
  v_active_id     BIGINT;
BEGIN
  IF p_user_id IS NULL THEN RETURN 'allow'; END IF;

  UPDATE ip_block_decisions
     SET attempt_count = attempt_count + 1, last_seen_at = NOW(), ip_hash = p_ip_hash,
         raw_ip = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = 'blocked' AND mode = 'enforce' AND cs_resolution IS NULL
     AND (expires_at IS NULL OR expires_at > NOW())
   RETURNING id INTO v_active_id;
  IF v_active_id IS NOT NULL THEN RETURN 'blocked'; END IF;

  SELECT * INTO v_policy FROM anti_abuse_policies
   WHERE action_type = p_action AND enabled = true
     AND count_strategy = 'creation_clustered_per_ip'
   LIMIT 1;
  IF NOT FOUND THEN RETURN 'allow'; END IF;

  v_window_start := GREATEST(
    NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL,
    COALESCE(v_policy.enforce_since, NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL)
  );
  v_device_window_start := NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL;

  SELECT created_at INTO v_user_created FROM auth.users WHERE id = p_user_id;
  IF v_user_created IS NULL THEN RETURN 'allow'; END IF;

  WITH cohort AS (
    SELECT DISTINCT r.user_id
      FROM request_ip_log r
     WHERE r.ip_hash = p_ip_hash AND r.action_type = p_action
       AND r.created_at >= v_window_start AND r.user_id IS NOT NULL
    UNION
    SELECT p_user_id
  ), c AS (
    SELECT au.id, au.created_at
      FROM cohort co JOIN auth.users au ON au.id = co.user_id
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_tight_window_seconds),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_loose_window_seconds)
    INTO v_cohort_size, v_tight_n, v_loose_n
    FROM c;

  IF v_cohort_size < v_policy.suspect_threshold THEN
    v_strongest := 'allow';
  ELSIF v_tight_n >= v_policy.block_threshold THEN
    v_strongest := 'blocked'; v_observed := v_tight_n;
    v_reason := format('%s_creation_cluster_tight_%s_%ss', p_action, v_tight_n, v_policy.link_tight_window_seconds);
  ELSIF v_loose_n >= v_policy.block_threshold THEN
    v_strongest := 'suspect'; v_observed := v_loose_n;
    v_reason := format('%s_creation_cluster_loose_%s_%ss', p_action, v_loose_n, v_policy.link_loose_window_seconds);
  ELSE
    v_strongest := 'allow';
  END IF;

  IF p_device_hash IS NOT NULL AND p_device_hash <> '' THEN
    DECLARE v_dcount INT;
    BEGIN
      IF v_policy.device_block_threshold IS NOT NULL THEN
        v_dcount := aa_device_cohort_count(p_action, p_device_hash, p_user_id, v_device_window_start);
        IF v_dcount >= v_policy.device_block_threshold THEN
          v_strongest := 'blocked'; v_observed := v_dcount;
          v_reason := format('%s_device_%s_accounts', p_action, v_dcount);
        ELSIF v_policy.device_suspect_threshold IS NOT NULL
              AND v_dcount >= v_policy.device_suspect_threshold THEN
          IF v_strongest IN ('suspect','blocked') THEN
            v_strongest := 'blocked';
            v_reason := format('%s_device_%s_x_%s', p_action, v_dcount, COALESCE(v_reason,'cluster'));
          ELSIF v_strongest = 'allow' THEN
            v_strongest := 'suspect'; v_observed := v_dcount;
            v_reason := format('%s_device_%s_accounts_suspect', p_action, v_dcount);
          END IF;
        END IF;
      END IF;
    END;
  END IF;

  IF v_strongest = 'allow' THEN
    RETURN 'allow';
  END IF;

  PERFORM pg_advisory_xact_lock(
    178633894::int,
    (hashtextextended(p_user_id::text || '|' || p_action || '|' || v_strongest || '|' || v_policy.mode, 0) & 2147483647)::int
  );

  UPDATE ip_block_decisions
     SET attempt_count  = attempt_count + 1,
         last_seen_at   = NOW(),
         observed_value = GREATEST(observed_value, v_observed),
         reason         = v_reason,
         threshold_used = v_policy.block_threshold,
         applied_window = v_policy.window_seconds,
         ip_hash        = p_ip_hash,
         raw_ip         = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = v_strongest AND mode = v_policy.mode
     AND cs_resolution IS NULL AND (expires_at IS NULL OR expires_at > NOW());

  IF NOT FOUND THEN
    INSERT INTO ip_block_decisions
      (ip_hash, action_type, user_id, decision, mode, reason,
       applied_window, threshold_used, observed_value, first_seen_at, last_seen_at, expires_at, raw_ip)
    VALUES
      (p_ip_hash, p_action, p_user_id, v_strongest, v_policy.mode, v_reason,
       v_policy.window_seconds, v_policy.block_threshold, v_observed, NOW(), NOW(),
       CASE WHEN v_strongest = 'blocked' THEN NOW() + INTERVAL '24 hours' ELSE NULL END,
       p_raw_ip);
  END IF;

  IF v_policy.mode = 'shadow' THEN RETURN 'allow'; END IF;
  RETURN v_strongest;
END $function$;

DROP FUNCTION IF EXISTS public.get_alert_blocked_rows(TIMESTAMPTZ);

CREATE OR REPLACE FUNCTION public.get_alert_blocked_rows(
  p_since TIMESTAMPTZ
)
RETURNS TABLE (
  id              BIGINT,
  user_id         UUID,
  ip_hash         TEXT,
  action_type     TEXT,
  decision        TEXT,
  mode            TEXT,
  reason          TEXT,
  applied_window  INTEGER,
  threshold_used  INTEGER,
  observed_value  INTEGER,
  attempt_count   INTEGER,
  first_seen_at   TIMESTAMPTZ,
  expires_at      TIMESTAMPTZ,
  cs_resolution   TEXT,
  user_email      TEXT,
  user_nickname   TEXT,
  last_ip         TEXT,
  country_code    TEXT,
  ip_user_count   BIGINT,
  ip_is_fallback  BOOLEAN
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    d.id, d.user_id, d.ip_hash, d.action_type, d.decision, d.mode, d.reason,
    d.applied_window, d.threshold_used, d.observed_value, d.attempt_count,
    d.first_seen_at, d.expires_at, d.cs_resolution,
    up.email     AS user_email,
    up.nickname  AS user_nickname,
    COALESCE(d.raw_ip, m.last_ip,      up.last_ip)      AS last_ip,
    COALESCE(             m.country_code, up.country_code) AS country_code,
    m.user_count AS ip_user_count,
    (d.raw_ip IS NULL AND m.last_ip IS NULL AND up.last_ip IS NOT NULL) AS ip_is_fallback
  FROM ip_block_decisions d
  LEFT JOIN user_profiles up ON up.id = d.user_id
  LEFT JOIN LATERAL public.get_ip_hash_meta(d.ip_hash, 7) m ON TRUE
  WHERE d.decision = 'blocked'
    AND d.mode = 'enforce'
    AND d.cs_resolution IS NULL
    AND d.first_seen_at >= p_since;
$function$;

CREATE OR REPLACE FUNCTION public.check_ip_quota_clustered(p_action text, p_ip_hash text, p_user_id uuid, p_device_hash text DEFAULT NULL::text, p_raw_ip text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_policy        anti_abuse_policies%ROWTYPE;
  v_window_start  TIMESTAMPTZ;
  v_device_window_start TIMESTAMPTZ;
  v_user_created  TIMESTAMPTZ;
  v_cohort_size   INT := 0;
  v_tight_n       INT := 0;
  v_loose_n       INT := 0;
  v_strongest     TEXT := 'allow';
  v_observed      INT := 0;
  v_reason        TEXT;
  v_active_id     BIGINT;
  v_threshold_used INT;
BEGIN
  IF p_user_id IS NULL THEN RETURN 'allow'; END IF;

  UPDATE ip_block_decisions
     SET attempt_count = attempt_count + 1, last_seen_at = NOW(), ip_hash = p_ip_hash,
         raw_ip = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = 'blocked' AND mode = 'enforce' AND cs_resolution IS NULL
     AND (expires_at IS NULL OR expires_at > NOW())
   RETURNING id INTO v_active_id;
  IF v_active_id IS NOT NULL THEN RETURN 'blocked'; END IF;

  SELECT * INTO v_policy FROM anti_abuse_policies
   WHERE action_type = p_action AND enabled = true
     AND count_strategy = 'creation_clustered_per_ip'
   LIMIT 1;
  IF NOT FOUND THEN RETURN 'allow'; END IF;

  v_threshold_used := v_policy.block_threshold;

  v_window_start := GREATEST(
    NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL,
    COALESCE(v_policy.enforce_since, NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL)
  );
  v_device_window_start := NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL;

  SELECT created_at INTO v_user_created FROM auth.users WHERE id = p_user_id;
  IF v_user_created IS NULL THEN RETURN 'allow'; END IF;

  WITH cohort AS (
    SELECT DISTINCT r.user_id
      FROM request_ip_log r
     WHERE r.ip_hash = p_ip_hash AND r.action_type = p_action
       AND r.created_at >= v_window_start AND r.user_id IS NOT NULL
    UNION
    SELECT p_user_id
  ), c AS (
    SELECT au.id, au.created_at
      FROM cohort co JOIN auth.users au ON au.id = co.user_id
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_tight_window_seconds),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_loose_window_seconds)
    INTO v_cohort_size, v_tight_n, v_loose_n
    FROM c;

  IF v_cohort_size < v_policy.suspect_threshold THEN
    v_strongest := 'allow';
  ELSIF v_tight_n >= v_policy.block_threshold THEN
    v_strongest := 'blocked'; v_observed := v_tight_n;
    v_reason := format('%s_creation_cluster_tight_%s_%ss', p_action, v_tight_n, v_policy.link_tight_window_seconds);
  ELSIF v_loose_n >= v_policy.block_threshold THEN
    v_strongest := 'suspect'; v_observed := v_loose_n;
    v_reason := format('%s_creation_cluster_loose_%s_%ss', p_action, v_loose_n, v_policy.link_loose_window_seconds);
  ELSE
    v_strongest := 'allow';
  END IF;

  IF p_device_hash IS NOT NULL AND p_device_hash <> '' THEN
    DECLARE v_dcount INT;
    BEGIN
      IF v_policy.device_block_threshold IS NOT NULL THEN
        v_dcount := aa_device_cohort_count(p_action, p_device_hash, p_user_id, v_device_window_start);
        IF v_dcount >= v_policy.device_block_threshold THEN
          v_strongest := 'blocked'; v_observed := v_dcount;
          v_reason := format('%s_device_%s_accounts', p_action, v_dcount);
          v_threshold_used := v_policy.device_block_threshold;
        ELSIF v_policy.device_suspect_threshold IS NOT NULL
              AND v_dcount >= v_policy.device_suspect_threshold THEN
          IF v_strongest IN ('suspect','blocked') THEN
            v_strongest := 'blocked';
            v_reason := format('%s_device_%s_x_%s', p_action, v_dcount, COALESCE(v_reason,'cluster'));
          ELSIF v_strongest = 'allow' THEN
            v_strongest := 'suspect'; v_observed := v_dcount;
            v_reason := format('%s_device_%s_accounts_suspect', p_action, v_dcount);
            v_threshold_used := v_policy.device_suspect_threshold;
          END IF;
        END IF;
      END IF;
    END;
  END IF;

  IF v_strongest = 'allow' THEN
    RETURN 'allow';
  END IF;

  PERFORM pg_advisory_xact_lock(
    178633894::int,
    (hashtextextended(p_user_id::text || '|' || p_action || '|' || v_strongest || '|' || v_policy.mode, 0) & 2147483647)::int
  );

  UPDATE ip_block_decisions
     SET attempt_count  = attempt_count + 1,
         last_seen_at   = NOW(),
         observed_value = GREATEST(observed_value, v_observed),
         reason         = v_reason,
         threshold_used = v_threshold_used,
         applied_window = v_policy.window_seconds,
         ip_hash        = p_ip_hash,
         raw_ip         = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = v_strongest AND mode = v_policy.mode
     AND cs_resolution IS NULL AND (expires_at IS NULL OR expires_at > NOW());

  IF NOT FOUND THEN
    INSERT INTO ip_block_decisions
      (ip_hash, action_type, user_id, decision, mode, reason,
       applied_window, threshold_used, observed_value, first_seen_at, last_seen_at, expires_at, raw_ip)
    VALUES
      (p_ip_hash, p_action, p_user_id, v_strongest, v_policy.mode, v_reason,
       v_policy.window_seconds, v_threshold_used, v_observed, NOW(), NOW(),
       CASE WHEN v_strongest = 'blocked' THEN NOW() + INTERVAL '24 hours' ELSE NULL END,
       p_raw_ip);
  END IF;

  IF v_policy.mode = 'shadow' THEN RETURN 'allow'; END IF;
  RETURN v_strongest;
END $function$;

SELECT cron.unschedule('anti_abuse_auto_confirm');

DROP FUNCTION IF EXISTS public.auto_confirm_abuse();

ALTER TABLE public.ip_block_decisions
  DROP CONSTRAINT IF EXISTS ip_block_decisions_cs_resolution_check;

ALTER TABLE public.ip_block_decisions
  ADD CONSTRAINT ip_block_decisions_cs_resolution_check
  CHECK (cs_resolution IS NULL OR cs_resolution = 'false_positive');

DROP FUNCTION IF EXISTS public.get_users_abuse_summary(uuid[], integer);

CREATE FUNCTION public.get_users_abuse_summary(p_user_ids uuid[], p_window_days integer DEFAULT 30)
 RETURNS TABLE(user_id uuid, has_active_block boolean, decision_count integer, earliest_active_expires timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM assert_anti_abuse_permission('anti_abuse.queue.review');

  IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    d.user_id,
    BOOL_OR(
      d.decision = 'blocked'
      AND d.mode = 'enforce'
      AND d.cs_resolution IS NULL
      AND (d.expires_at IS NULL OR d.expires_at > NOW())
    ) AS has_active_block,
    COUNT(*)::INT AS decision_count,
    MIN(d.expires_at) FILTER (
      WHERE d.decision = 'blocked'
        AND d.mode = 'enforce'
        AND d.cs_resolution IS NULL
        AND (d.expires_at IS NULL OR d.expires_at > NOW())
    ) AS earliest_active_expires
  FROM ip_block_decisions d
  WHERE d.user_id = ANY(p_user_ids)
    AND d.last_seen_at > NOW() - (p_window_days || ' days')::INTERVAL
  GROUP BY d.user_id;
END
$function$;

CREATE OR REPLACE FUNCTION public.check_ip_quota_clustered(p_action text, p_ip_hash text, p_user_id uuid, p_device_hash text DEFAULT NULL::text, p_raw_ip text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_policy        anti_abuse_policies%ROWTYPE;
  v_window_start  TIMESTAMPTZ;
  v_device_window_start TIMESTAMPTZ;
  v_user_created  TIMESTAMPTZ;
  v_cohort_size   INT := 0;
  v_tight_n       INT := 0;
  v_loose_n       INT := 0;
  v_strongest     TEXT := 'allow';
  v_observed      INT := 0;
  v_reason        TEXT;
  v_active_id     BIGINT;
  v_threshold_used INT;
BEGIN
  IF p_user_id IS NULL THEN RETURN 'allow'; END IF;

  UPDATE ip_block_decisions
     SET attempt_count = attempt_count + 1, last_seen_at = NOW(), ip_hash = p_ip_hash,
         raw_ip = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = 'blocked' AND mode = 'enforce' AND cs_resolution IS NULL
     AND (expires_at IS NULL OR expires_at > NOW())
   RETURNING id INTO v_active_id;
  IF v_active_id IS NOT NULL THEN RETURN 'blocked'; END IF;

  SELECT * INTO v_policy FROM anti_abuse_policies
   WHERE action_type = p_action AND enabled = true
     AND count_strategy = 'creation_clustered_per_ip'
   LIMIT 1;
  IF NOT FOUND THEN RETURN 'allow'; END IF;

  v_threshold_used := v_policy.block_threshold;

  v_window_start := GREATEST(
    NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL,
    COALESCE(v_policy.enforce_since, NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL)
  );
  v_device_window_start := NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL;

  SELECT created_at INTO v_user_created FROM auth.users WHERE id = p_user_id;
  IF v_user_created IS NULL THEN RETURN 'allow'; END IF;

  WITH cohort AS (
    SELECT DISTINCT r.user_id
      FROM request_ip_log r
     WHERE r.ip_hash = p_ip_hash AND r.action_type = p_action
       AND r.created_at >= v_window_start AND r.user_id IS NOT NULL
    UNION
    SELECT p_user_id
  ), c AS (
    SELECT au.id, au.created_at
      FROM cohort co JOIN auth.users au ON au.id = co.user_id
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_tight_window_seconds),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_loose_window_seconds)
    INTO v_cohort_size, v_tight_n, v_loose_n
    FROM c;

  IF v_cohort_size < v_policy.suspect_threshold THEN
    v_strongest := 'allow';
  ELSIF v_tight_n >= v_policy.block_threshold THEN
    v_strongest := 'suspect'; v_observed := v_tight_n;
    v_reason := format('%s_creation_cluster_tight_%s_%ss', p_action, v_tight_n, v_policy.link_tight_window_seconds);
  ELSIF v_loose_n >= v_policy.block_threshold THEN
    v_strongest := 'suspect'; v_observed := v_loose_n;
    v_reason := format('%s_creation_cluster_loose_%s_%ss', p_action, v_loose_n, v_policy.link_loose_window_seconds);
  ELSE
    v_strongest := 'allow';
  END IF;

  IF p_device_hash IS NOT NULL AND p_device_hash <> '' THEN
    DECLARE v_dcount INT;
    BEGIN
      IF v_policy.device_block_threshold IS NOT NULL THEN
        v_dcount := aa_device_cohort_count(p_action, p_device_hash, p_user_id, v_device_window_start);
        IF v_dcount >= v_policy.device_block_threshold THEN
          v_strongest := 'blocked'; v_observed := v_dcount;
          v_reason := format('%s_device_%s_accounts', p_action, v_dcount);
          v_threshold_used := v_policy.device_block_threshold;
        ELSIF v_policy.device_suspect_threshold IS NOT NULL
              AND v_dcount >= v_policy.device_suspect_threshold
              AND v_strongest = 'allow' THEN
          v_strongest := 'suspect'; v_observed := v_dcount;
          v_reason := format('%s_device_%s_accounts_suspect', p_action, v_dcount);
          v_threshold_used := v_policy.device_suspect_threshold;
        END IF;
      END IF;
    END;
  END IF;

  IF v_strongest = 'allow' THEN
    RETURN 'allow';
  END IF;

  PERFORM pg_advisory_xact_lock(
    178633894::int,
    (hashtextextended(p_user_id::text || '|' || p_action || '|' || v_strongest || '|' || v_policy.mode, 0) & 2147483647)::int
  );

  UPDATE ip_block_decisions
     SET attempt_count  = attempt_count + 1,
         last_seen_at   = NOW(),
         observed_value = GREATEST(observed_value, v_observed),
         reason         = v_reason,
         threshold_used = v_threshold_used,
         applied_window = v_policy.window_seconds,
         ip_hash        = p_ip_hash,
         raw_ip         = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = v_strongest AND mode = v_policy.mode
     AND cs_resolution IS NULL AND (expires_at IS NULL OR expires_at > NOW());

  IF NOT FOUND THEN
    INSERT INTO ip_block_decisions
      (ip_hash, action_type, user_id, decision, mode, reason,
       applied_window, threshold_used, observed_value, first_seen_at, last_seen_at, expires_at, raw_ip)
    VALUES
      (p_ip_hash, p_action, p_user_id, v_strongest, v_policy.mode, v_reason,
       v_policy.window_seconds, v_threshold_used, v_observed, NOW(), NOW(),
       CASE WHEN v_strongest = 'blocked' THEN NOW() + INTERVAL '24 hours' ELSE NULL END,
       p_raw_ip);
  END IF;

  IF v_policy.mode = 'shadow' THEN RETURN 'allow'; END IF;
  RETURN v_strongest;
END $function$;

UPDATE public.anti_abuse_policies
   SET mode = 'shadow', updated_at = NOW()
 WHERE action_type IN ('attendance', 'ad_watch') AND count_strategy = 'creation_clustered_per_ip';

UPDATE public.ip_block_decisions
   SET expires_at = NOW()
 WHERE action_type IN ('attendance', 'ad_watch') AND decision = 'blocked' AND mode = 'enforce'
   AND (expires_at IS NULL OR expires_at > NOW());

CREATE TABLE IF NOT EXISTS public.ad_fraud_policy (
  id                smallint    PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  min_watch_seconds integer     NOT NULL DEFAULT 10,
  min_gap_seconds   integer     NOT NULL DEFAULT 10,
  mode              text        NOT NULL DEFAULT 'shadow' CHECK (mode IN ('shadow','enforce')),
  enabled           boolean     NOT NULL DEFAULT true,
  updated_at        timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.ad_fraud_policy ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.ad_fraud_decisions (
  id                bigserial   PRIMARY KEY,
  impression_id     uuid        NOT NULL,
  user_id           uuid        NOT NULL,
  signal            text        NOT NULL CHECK (signal IN ('completion_speed','burst')),
  decision          text        NOT NULL DEFAULT 'blocked',
  mode              text        NOT NULL,
  observed_seconds  numeric     NOT NULL,
  threshold_seconds integer     NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ad_fraud_decisions_created_idx ON public.ad_fraud_decisions (created_at);

CREATE INDEX IF NOT EXISTS ad_fraud_decisions_user_created_idx ON public.ad_fraud_decisions (user_id, created_at);

ALTER TABLE public.ad_fraud_decisions ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.check_ad_view_fraud(p_user_id uuid, p_impression_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pol       ad_fraud_policy%ROWTYPE;
  v_issued    timestamptz;
  v_elapsed   numeric;
  v_last      timestamptz;
  v_gap       numeric;
  v_signal    text := NULL;
  v_observed  numeric;
  v_threshold integer;
BEGIN
  SELECT * INTO v_pol FROM ad_fraud_policy WHERE id = 1;
  IF NOT FOUND OR NOT v_pol.enabled THEN RETURN 'allow'; END IF;

  SELECT issued_at INTO v_issued FROM ad_impressions
   WHERE id = p_impression_id AND user_id = p_user_id;
  IF v_issued IS NULL THEN RETURN 'allow'; END IF;

  v_elapsed := EXTRACT(EPOCH FROM (NOW() - v_issued));
  IF v_elapsed < v_pol.min_watch_seconds THEN
    v_signal := 'completion_speed'; v_observed := v_elapsed; v_threshold := v_pol.min_watch_seconds;
  ELSE
    SELECT MAX(created_at) INTO v_last FROM ad_reward_events WHERE user_id = p_user_id;
    IF v_last IS NOT NULL THEN
      v_gap := EXTRACT(EPOCH FROM (NOW() - v_last));
      IF v_gap < v_pol.min_gap_seconds THEN
        v_signal := 'burst'; v_observed := v_gap; v_threshold := v_pol.min_gap_seconds;
      END IF;
    END IF;
  END IF;

  IF v_signal IS NULL THEN RETURN 'allow'; END IF;

  INSERT INTO ad_fraud_decisions
    (impression_id, user_id, signal, decision, mode, observed_seconds, threshold_seconds)
  VALUES
    (p_impression_id, p_user_id, v_signal, 'blocked', v_pol.mode, v_observed, v_threshold);

  IF v_pol.mode = 'enforce' THEN RETURN 'blocked'; END IF;
  RETURN 'allow';
END $function$;

CREATE OR REPLACE FUNCTION public.guard_user_profiles_protected_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'UPDATE' THEN
      IF NEW.star_candy       IS DISTINCT FROM OLD.star_candy
      OR NEW.star_candy_bonus IS DISTINCT FROM OLD.star_candy_bonus
      OR NEW.jma_candy        IS DISTINCT FROM OLD.jma_candy
      OR NEW.is_admin         IS DISTINCT FROM OLD.is_admin
      OR NEW.is_super_admin   IS DISTINCT FROM OLD.is_super_admin THEN
        RAISE EXCEPTION
          'protected columns (star_candy/star_candy_bonus/jma_candy/is_admin/is_super_admin) cannot be modified by role %',
          current_user
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSIF TG_OP = 'INSERT' THEN
      IF COALESCE(NEW.star_candy, 0)       <> 0
      OR COALESCE(NEW.star_candy_bonus, 0) <> 0
      OR COALESCE(NEW.jma_candy, 0)        <> 0
      OR COALESCE(NEW.is_admin, false)     <> false
      OR COALESCE(NEW.is_super_admin, false) <> false THEN
        RAISE EXCEPTION
          'protected columns cannot be pre-set on insert by role %', current_user
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_guard_user_profiles_protected ON public.user_profiles;

CREATE TRIGGER trg_guard_user_profiles_protected
  BEFORE INSERT OR UPDATE ON public.user_profiles
  FOR EACH ROW EXECUTE FUNCTION public.guard_user_profiles_protected_columns();

ALTER TABLE public.vote_pick     ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.pic_vote_pick ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.guard_admin_only_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.user_profiles up
      WHERE up.id = auth.uid() AND up.is_admin = true
    ) THEN
      RAISE EXCEPTION 'table %.% is admin/server write-only (role=%, not admin)',
        TG_TABLE_SCHEMA, TG_TABLE_NAME, current_user
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['vote_item','pic_vote_item','vote','vote_reward']
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_guard_admin_write ON public.%I', t);
    EXECUTE format('CREATE TRIGGER trg_guard_admin_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_admin_only_write()', t);
  END LOOP;
END $$;

ALTER TABLE public.vote_pick     DISABLE ROW LEVEL SECURITY;

ALTER TABLE public.pic_vote_pick DISABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.guard_user_profiles_protected_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon')
     AND NOT EXISTS (
       SELECT 1 FROM public.user_profiles up
       WHERE up.id = auth.uid() AND up.is_admin = true
     )
  THEN
    IF TG_OP = 'UPDATE' THEN
      IF NEW.star_candy       IS DISTINCT FROM OLD.star_candy
      OR NEW.star_candy_bonus IS DISTINCT FROM OLD.star_candy_bonus
      OR NEW.jma_candy        IS DISTINCT FROM OLD.jma_candy
      OR NEW.is_admin         IS DISTINCT FROM OLD.is_admin
      OR NEW.is_super_admin   IS DISTINCT FROM OLD.is_super_admin THEN
        RAISE EXCEPTION 'protected columns require admin or server role (role=%)', current_user
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSIF TG_OP = 'INSERT' THEN
      IF COALESCE(NEW.star_candy, 0)       <> 0
      OR COALESCE(NEW.star_candy_bonus, 0) <> 0
      OR COALESCE(NEW.jma_candy, 0)        <> 0
      OR COALESCE(NEW.is_admin, false)     <> false
      OR COALESCE(NEW.is_super_admin, false) <> false THEN
        RAISE EXCEPTION 'protected columns cannot be pre-set on insert (role=%)', current_user
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['star_candy_history','star_candy_bonus_history']
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_guard_admin_write ON public.%I', t);
    EXECUTE format('CREATE TRIGGER trg_guard_admin_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_admin_only_write()', t);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.is_request_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
      AND ( up.is_admin = true
            OR EXISTS (
              SELECT 1 FROM public.admin_whitelist aw
              WHERE lower(aw.email) = lower(up.email) AND aw.is_active = true
            ) )
  );
$$;

CREATE OR REPLACE FUNCTION public.guard_admin_only_write()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF current_user IN ('authenticated','anon') AND NOT public.is_request_admin() THEN
    RAISE EXCEPTION 'table %.% is admin/server write-only (role=%, not admin)',
      TG_TABLE_SCHEMA, TG_TABLE_NAME, current_user USING ERRCODE='insufficient_privilege';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_user_profiles_protected_columns()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF current_user IN ('authenticated','anon') AND NOT public.is_request_admin() THEN
    IF TG_OP = 'UPDATE' THEN
      IF NEW.star_candy IS DISTINCT FROM OLD.star_candy
      OR NEW.star_candy_bonus IS DISTINCT FROM OLD.star_candy_bonus
      OR NEW.jma_candy IS DISTINCT FROM OLD.jma_candy
      OR NEW.is_admin IS DISTINCT FROM OLD.is_admin
      OR NEW.is_super_admin IS DISTINCT FROM OLD.is_super_admin THEN
        RAISE EXCEPTION 'protected columns require admin or server role (role=%)', current_user USING ERRCODE='insufficient_privilege';
      END IF;
    ELSIF TG_OP = 'INSERT' THEN
      IF COALESCE(NEW.star_candy,0)<>0 OR COALESCE(NEW.star_candy_bonus,0)<>0 OR COALESCE(NEW.jma_candy,0)<>0
      OR COALESCE(NEW.is_admin,false)<>false OR COALESCE(NEW.is_super_admin,false)<>false THEN
        RAISE EXCEPTION 'protected columns cannot be pre-set on insert (role=%)', current_user USING ERRCODE='insufficient_privilege';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'activities','ad_campaigns','admin_whitelist','application_logs','artist','artist_group',
    'audit_logs','banner','config','faq_categories','faqs','media','notices','popup','prompts',
    'qna_categories','reward','version','vote_achieve'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_guard_admin_write ON public.%I', t);
    EXECUTE format('CREATE TRIGGER trg_guard_admin_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_admin_only_write()', t);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.guard_own_row_or_admin_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
DECLARE
  owner_col text := TG_ARGV[0];
  row_owner text;
  old_owner text;
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'DELETE' THEN
      row_owner := to_jsonb(OLD) ->> owner_col;
    ELSE
      row_owner := to_jsonb(NEW) ->> owner_col;
    END IF;

    IF row_owner IS DISTINCT FROM (auth.uid())::text THEN
      IF NOT public.is_request_admin() THEN
        RAISE EXCEPTION '%.%: can only write your own rows (% must equal current user) — admin/server only otherwise',
          TG_TABLE_SCHEMA, TG_TABLE_NAME, owner_col USING ERRCODE = 'insufficient_privilege';
      END IF;
    END IF;

    IF TG_OP = 'UPDATE' THEN
      old_owner := to_jsonb(OLD) ->> owner_col;
      IF (to_jsonb(NEW) ->> owner_col) IS DISTINCT FROM old_owner AND NOT public.is_request_admin() THEN
        RAISE EXCEPTION '%.%: cannot change row ownership', TG_TABLE_SCHEMA, TG_TABLE_NAME
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;

DO $$
DECLARE r text; tbl text; col text;
BEGIN
  FOREACH r IN ARRAY ARRAY[
    'comment_likes:user_id','comment_reports:user_id','artist_user_bookmark:user_id',
    'board_user_bookmark:user_id','celeb_bookmark_user:user_id','post_likes:user_id',
    'post_reports:user_id','post_scraps:user_id','goonghap_results:user_id',
    'qna_messages:user_id','qna_threads:user_id','user_blocks:user_id',
    'user_notifications:user_id','user_agreement:id','boards:creator_id'
  ] LOOP
    tbl := split_part(r, ':', 1);
    col := split_part(r, ':', 2);
    EXECUTE format('DROP TRIGGER IF EXISTS trg_guard_own_row ON public.%I', tbl);
    EXECUTE format('CREATE TRIGGER trg_guard_own_row BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_own_row_or_admin_write(%L)', tbl, col);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.aa_device_cohort_ip_count(
  p_action text, p_device_hash text, p_ip_hash text, p_window_start timestamptz
) RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public','pg_temp'
AS $function$
DECLARE
  v_count INT := 0;
BEGIN
  IF p_device_hash IS NULL OR p_device_hash = '' THEN
    RETURN 0;
  END IF;

  SELECT COUNT(DISTINCT ip_hash) INTO v_count
    FROM request_ip_log
   WHERE device_hash = p_device_hash
     AND action_type = p_action
     AND created_at >= p_window_start
     AND ip_hash IS NOT NULL;

  IF p_ip_hash IS NOT NULL AND p_ip_hash <> '' THEN
    IF NOT EXISTS (
      SELECT 1 FROM request_ip_log
       WHERE device_hash = p_device_hash
         AND action_type = p_action
         AND created_at >= p_window_start
         AND ip_hash = p_ip_hash
    ) THEN
      v_count := v_count + 1;
    END IF;
  END IF;

  RETURN v_count;
END
$function$;

CREATE OR REPLACE FUNCTION public.check_ip_quota_clustered(p_action text, p_ip_hash text, p_user_id uuid, p_device_hash text DEFAULT NULL::text, p_raw_ip text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_policy        anti_abuse_policies%ROWTYPE;
  v_window_start  TIMESTAMPTZ;
  v_device_window_start TIMESTAMPTZ;
  v_user_created  TIMESTAMPTZ;
  v_cohort_size   INT := 0;
  v_tight_n       INT := 0;
  v_loose_n       INT := 0;
  v_strongest     TEXT := 'allow';
  v_observed      INT := 0;
  v_reason        TEXT;
  v_active_id     BIGINT;
  v_threshold_used INT;
BEGIN
  IF p_user_id IS NULL THEN RETURN 'allow'; END IF;

  UPDATE ip_block_decisions
     SET attempt_count = attempt_count + 1, last_seen_at = NOW(), ip_hash = p_ip_hash,
         raw_ip = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = 'blocked' AND mode = 'enforce' AND cs_resolution IS NULL
     AND (expires_at IS NULL OR expires_at > NOW())
   RETURNING id INTO v_active_id;
  IF v_active_id IS NOT NULL THEN RETURN 'blocked'; END IF;

  SELECT * INTO v_policy FROM anti_abuse_policies
   WHERE action_type = p_action AND enabled = true
     AND count_strategy = 'creation_clustered_per_ip'
   LIMIT 1;
  IF NOT FOUND THEN RETURN 'allow'; END IF;

  v_threshold_used := v_policy.block_threshold;

  v_window_start := GREATEST(
    NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL,
    COALESCE(v_policy.enforce_since, NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL)
  );
  v_device_window_start := NOW() - (v_policy.window_seconds || ' seconds')::INTERVAL;

  SELECT created_at INTO v_user_created FROM auth.users WHERE id = p_user_id;
  IF v_user_created IS NULL THEN RETURN 'allow'; END IF;

  WITH cohort AS (
    SELECT DISTINCT r.user_id
      FROM request_ip_log r
     WHERE r.ip_hash = p_ip_hash AND r.action_type = p_action
       AND r.created_at >= v_window_start AND r.user_id IS NOT NULL
    UNION
    SELECT p_user_id
  ), c AS (
    SELECT au.id, au.created_at
      FROM cohort co JOIN auth.users au ON au.id = co.user_id
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_tight_window_seconds),
    COUNT(*) FILTER (WHERE ABS(EXTRACT(EPOCH FROM (c.created_at - v_user_created))) <= v_policy.link_loose_window_seconds)
    INTO v_cohort_size, v_tight_n, v_loose_n
    FROM c;

  IF v_cohort_size < v_policy.suspect_threshold THEN
    v_strongest := 'allow';
  ELSIF v_tight_n >= v_policy.block_threshold THEN
    v_strongest := 'suspect'; v_observed := v_tight_n;
    v_reason := format('%s_creation_cluster_tight_%s_%ss', p_action, v_tight_n, v_policy.link_tight_window_seconds);
  ELSIF v_loose_n >= v_policy.block_threshold THEN
    v_strongest := 'suspect'; v_observed := v_loose_n;
    v_reason := format('%s_creation_cluster_loose_%s_%ss', p_action, v_loose_n, v_policy.link_loose_window_seconds);
  ELSE
    v_strongest := 'allow';
  END IF;

  IF p_device_hash IS NOT NULL AND p_device_hash <> '' THEN
    DECLARE
      v_dcount INT;
      v_dip    INT;
    BEGIN
      IF v_policy.device_block_threshold IS NOT NULL THEN
        v_dcount := aa_device_cohort_count(p_action, p_device_hash, p_user_id, v_device_window_start);
        IF v_dcount >= v_policy.device_block_threshold THEN
          v_dip := aa_device_cohort_ip_count(p_action, p_device_hash, p_ip_hash, v_device_window_start);
          IF v_dip < v_dcount THEN
            v_strongest := 'blocked'; v_observed := v_dcount;
            v_reason := format('%s_device_%s_accounts_%sip', p_action, v_dcount, v_dip);
            v_threshold_used := v_policy.device_block_threshold;
          ELSIF v_strongest = 'allow' THEN
            v_strongest := 'suspect'; v_observed := v_dcount;
            v_reason := format('%s_device_%s_accounts_%sip_dispersed', p_action, v_dcount, v_dip);
            v_threshold_used := v_policy.device_block_threshold;
          END IF;
        ELSIF v_policy.device_suspect_threshold IS NOT NULL
              AND v_dcount >= v_policy.device_suspect_threshold
              AND v_strongest = 'allow' THEN
          v_strongest := 'suspect'; v_observed := v_dcount;
          v_reason := format('%s_device_%s_accounts_suspect', p_action, v_dcount);
          v_threshold_used := v_policy.device_suspect_threshold;
        END IF;
      END IF;
    END;
  END IF;

  IF v_strongest = 'allow' THEN
    RETURN 'allow';
  END IF;

  PERFORM pg_advisory_xact_lock(
    178633894::int,
    (hashtextextended(p_user_id::text || '|' || p_action || '|' || v_strongest || '|' || v_policy.mode, 0) & 2147483647)::int
  );

  UPDATE ip_block_decisions
     SET attempt_count  = attempt_count + 1,
         last_seen_at   = NOW(),
         observed_value = GREATEST(observed_value, v_observed),
         reason         = v_reason,
         threshold_used = v_threshold_used,
         applied_window = v_policy.window_seconds,
         ip_hash        = p_ip_hash,
         raw_ip         = COALESCE(raw_ip, p_raw_ip)
   WHERE user_id = p_user_id AND action_type = p_action
     AND decision = v_strongest AND mode = v_policy.mode
     AND cs_resolution IS NULL AND (expires_at IS NULL OR expires_at > NOW());

  IF NOT FOUND THEN
    INSERT INTO ip_block_decisions
      (ip_hash, action_type, user_id, decision, mode, reason,
       applied_window, threshold_used, observed_value, first_seen_at, last_seen_at, expires_at, raw_ip)
    VALUES
      (p_ip_hash, p_action, p_user_id, v_strongest, v_policy.mode, v_reason,
       v_policy.window_seconds, v_threshold_used, v_observed, NOW(), NOW(),
       CASE WHEN v_strongest = 'blocked' THEN NOW() + INTERVAL '24 hours' ELSE NULL END,
       p_raw_ip);
  END IF;

  IF v_policy.mode = 'shadow' THEN RETURN 'allow'; END IF;
  RETURN v_strongest;
END $function$;

CREATE OR REPLACE FUNCTION public.compute_bonus_expiry(at_ts timestamptz DEFAULT now())
RETURNS timestamptz
LANGUAGE sql
STABLE
SET search_path = pg_catalog, public
AS $$
  SELECT (
    date_trunc('month', at_ts AT TIME ZONE 'Asia/Seoul')
    + CASE
        WHEN extract(day FROM (at_ts AT TIME ZONE 'Asia/Seoul')) < 15
          THEN interval '1 month'
        ELSE interval '2 months'
      END
    + interval '14 days'
  ) AT TIME ZONE 'Asia/Seoul';
$$;

COMMENT ON FUNCTION public.compute_bonus_expiry(timestamptz) IS
  '보너스 별사탕 소멸 시각. KST 1~14일 적립분은 다음달 15일 00:00 KST, '
  '15일~말일 적립분은 다다음달 15일 00:00 KST. '
  'TS 구현(_shared/bonus/expiry.ts)과 반드시 동일하게 유지할 것.';

CREATE OR REPLACE FUNCTION public.get_weekday_stats(
  p_start timestamptz DEFAULT NULL,
  p_end   timestamptz DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'permission denied: admin only'
      USING ERRCODE = '42501';
  END IF;

  WITH vote_hm AS (
    SELECT EXTRACT(ISODOW FROM vp.created_at AT TIME ZONE 'Asia/Seoul')::int AS dow,
           EXTRACT(HOUR   FROM vp.created_at AT TIME ZONE 'Asia/Seoul')::int AS hour,
           COUNT(*)::bigint                    AS vote_cnt,
           COALESCE(SUM(vp.amount), 0)::bigint AS votes
    FROM public.vote_pick vp
    WHERE vp.deleted_at IS NULL
      AND (p_start IS NULL OR vp.created_at >= p_start)
      AND (p_end   IS NULL OR vp.created_at <  p_end)
    GROUP BY 1, 2
  ),
  pay_hm AS (
    SELECT EXTRACT(ISODOW FROM rc.created_at AT TIME ZONE 'Asia/Seoul')::int AS dow,
           EXTRACT(HOUR   FROM rc.created_at AT TIME ZONE 'Asia/Seoul')::int AS hour,
           COUNT(*)::bigint                       AS pay_cnt,
           COALESCE(SUM(pr.price::numeric), 0)    AS revenue_usd
    FROM public.receipts rc
    JOIN public.products pr ON pr.id = rc.product_id
    WHERE rc.status = 'valid'
      AND rc.environment = 'production'
      AND (p_start IS NULL OR rc.created_at >= p_start)
      AND (p_end   IS NULL OR rc.created_at <  p_end)
    GROUP BY 1, 2
  ),
  hm AS (
    SELECT COALESCE(v.dow, p.dow)          AS dow,
           COALESCE(v.hour, p.hour)        AS hour,
           COALESCE(v.vote_cnt, 0)         AS vote_cnt,
           COALESCE(v.votes, 0)            AS votes,
           COALESCE(p.pay_cnt, 0)          AS pay_cnt,
           COALESCE(p.revenue_usd, 0)      AS revenue_usd
    FROM vote_hm v
    FULL OUTER JOIN pay_hm p ON p.dow = v.dow AND p.hour = v.hour
  ),
  wd AS (
    SELECT dow,
           SUM(vote_cnt)::bigint    AS vote_cnt,
           SUM(votes)::bigint       AS votes,
           SUM(pay_cnt)::bigint     AS pay_cnt,
           SUM(revenue_usd)::numeric AS revenue_usd
    FROM hm
    GROUP BY dow
  )
  SELECT jsonb_build_object(
    'weekday', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
         'dow', dow, 'vote_cnt', vote_cnt, 'votes', votes,
         'pay_cnt', pay_cnt, 'revenue_usd', revenue_usd
       ) ORDER BY dow) FROM wd), '[]'::jsonb),
    'heatmap', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
         'dow', dow, 'hour', hour, 'vote_cnt', vote_cnt, 'votes', votes,
         'pay_cnt', pay_cnt, 'revenue_usd', revenue_usd
       ) ORDER BY dow, hour) FROM hm), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_payment_breakdown(
  p_start     timestamptz DEFAULT NULL,
  p_end       timestamptz DEFAULT NULL,
  p_dimension text        DEFAULT 'platform'
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'permission denied: admin only' USING ERRCODE = '42501';
  END IF;
  IF p_dimension NOT IN ('platform', 'product') THEN
    RAISE EXCEPTION 'invalid dimension: %', p_dimension USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object('key', key, 'pay_cnt', pay_cnt, 'revenue_usd', revenue_usd)
           ORDER BY revenue_usd DESC, key
         ), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT CASE p_dimension
             WHEN 'platform' THEN rc.platform
             ELSE COALESCE(pr.product_name, pr.id::text)
           END                                 AS key,
           COUNT(*)::bigint                     AS pay_cnt,
           COALESCE(SUM(pr.price::numeric), 0)  AS revenue_usd
    FROM public.receipts rc
    JOIN public.products pr ON pr.id = rc.product_id
    WHERE rc.status = 'valid'
      AND rc.environment = 'production'
      AND (p_start IS NULL OR rc.created_at >= p_start)
      AND (p_end   IS NULL OR rc.created_at <  p_end)
    GROUP BY 1
  ) t;

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_artist_vote_breakdown(
  p_start         timestamptz DEFAULT NULL,
  p_end           timestamptz DEFAULT NULL,
  p_limit         int         DEFAULT 20,
  p_exclude_admin boolean     DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'permission denied: admin only' USING ERRCODE = '42501';
  END IF;

  WITH per_artist AS (
    SELECT a.id                             AS artist_id,
           a.name::jsonb                    AS artist_name,
           SUM(vp.amount)::bigint           AS votes,
           COUNT(DISTINCT vp.user_id)::bigint AS voters
    FROM public.vote_pick vp
    JOIN public.vote_item vi ON vi.id = vp.vote_item_id
    JOIN public.artist a     ON a.id  = vi.artist_id
    LEFT JOIN public.user_profiles up ON up.id = vp.user_id
    WHERE vp.deleted_at IS NULL
      AND (p_start IS NULL OR vp.created_at >= p_start)
      AND (p_end   IS NULL OR vp.created_at <  p_end)
      AND (NOT p_exclude_admin OR COALESCE(up.is_admin, false) = false)
    GROUP BY a.id, a.name::jsonb
  ),
  ranked AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY votes DESC, artist_id) AS rn
    FROM per_artist
  ),
  top_n AS (
    SELECT artist_id, artist_name, votes, voters, 0 AS grp
    FROM ranked WHERE rn <= p_limit
  ),
  others AS (
    SELECT NULL::bigint AS artist_id, NULL::jsonb AS artist_name,
           COALESCE(SUM(votes), 0)::bigint  AS votes,
           COALESCE(SUM(voters), 0)::bigint AS voters,
           1 AS grp
    FROM ranked WHERE rn > p_limit
    HAVING COUNT(*) > 0
  )
  SELECT COALESCE(jsonb_agg(
           jsonb_build_object('artist_id', artist_id, 'artist_name', artist_name,
                              'votes', votes, 'voters', voters)
           ORDER BY grp, votes DESC
         ), '[]'::jsonb)
  INTO v_result
  FROM (SELECT * FROM top_n UNION ALL SELECT * FROM others) u;

  RETURN v_result;
END;
$$;

BEGIN;

DROP POLICY IF EXISTS "vote_item_request_users_select_policy"
  ON public.vote_item_request_users;

DROP POLICY IF EXISTS "vote_item_request_users_select_own"
  ON public.vote_item_request_users;

CREATE POLICY "vote_item_request_users_select_own"
  ON public.vote_item_request_users FOR SELECT TO authenticated
  USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "vote_item_request_users_update_policy"
  ON public.vote_item_request_users;

DROP POLICY IF EXISTS "vote_item_request_users_delete_policy"
  ON public.vote_item_request_users;

ALTER VIEW public.vote_item_requests SET (security_invoker = true);

ALTER VIEW public.user_vote_item_request_history SET (security_invoker = true);

DROP VIEW public.vote_item_request_status_summary;

CREATE VIEW public.vote_item_request_status_summary AS
SELECT
  viru.vote_id,
  viru.status AS request_status,
  a.id AS artist_id,
  a.name ->> 'ko' AS artist_name,
  count(*) AS request_count
FROM public.vote_item_request_users AS viru
JOIN public.artist AS a ON viru.artist_id = a.id
GROUP BY viru.vote_id, viru.status, a.id, a.name ->> 'ko'
ORDER BY count(*) DESC;

CREATE OR REPLACE FUNCTION public.create_vote_item_request_with_user(
  vote_id_param integer,
  artist_id_param integer,
  user_id_param uuid,
  p_ip_hash text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  new_request_id uuid;
  result_data jsonb;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.vote_item_request_users viru
    WHERE viru.vote_id = vote_id_param
      AND viru.user_id = user_id_param
      AND viru.artist_id = artist_id_param
  ) THEN
    RAISE EXCEPTION '이미 해당 아티스트에 대해 신청하셨습니다.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.artist WHERE id = artist_id_param) THEN
    RAISE EXCEPTION '존재하지 않는 아티스트입니다.';
  END IF;

  new_request_id := extensions.uuid_generate_v4();

  INSERT INTO public.vote_item_request_users (
    id, vote_item_request_id, vote_id, user_id, artist_id, status, ip_hash
  ) VALUES (
    new_request_id, new_request_id, vote_id_param, user_id_param, artist_id_param,
    'pending', p_ip_hash
  );

  SELECT jsonb_build_object(
    'vote_item_request', jsonb_build_object(
      'id', new_request_id,
      'vote_id', vote_id_param,
      'status', 'pending',
      'created_at', viru.created_at,
      'updated_at', viru.updated_at
    ),
    'user_request', jsonb_build_object(
      'id', viru.id,
      'vote_item_request_id', viru.vote_item_request_id,
      'user_id', viru.user_id,
      'vote_id', viru.vote_id,
      'artist_id', viru.artist_id,
      'status', viru.status,
      'created_at', viru.created_at,
      'updated_at', viru.updated_at
    ),
    'artist', to_jsonb(a.*)
  ) INTO result_data
  FROM public.vote_item_request_users viru
  JOIN public.artist a ON viru.artist_id = a.id
  WHERE viru.vote_item_request_id = new_request_id
    AND viru.user_id = user_id_param;

  RETURN result_data;
END;
$$;

NOTIFY pgrst, 'reload schema';

COMMIT;

DROP TRIGGER IF EXISTS "alarm-artist-request"
  ON public.vote_item_request_users;

DROP TRIGGER IF EXISTS "alarm-qna-message"
  ON public.qna_messages;

-- CLEAN BASELINE SCHEMA OVERLAY

